import{n as e}from"./rolldown-runtime-8BhlS34s.js";var t;function n(){return(n=e((()=>{t={configHints:{acp:{label:{"v1-w1ybzr-3":`ACP`},help:{"v1-gwlf91-44":`Controlli del runtime ACP per abilitare l'inoltro, selezionare i backend, limitare gli agenti di destinazione consentiti e selezionare il comportamento di proiezione dei turni in streaming.`}},"acp%2EallowedAgents":{label:{"v1-nvlwwz-i":`Agenti ACP consentiti`},help:{"v1-f2mw0d-3a":`Elenco degli ID degli agenti di destinazione ACP consentiti per le sessioni del runtime ACP. Se vuoto, non vengono applicate ulteriori restrizioni basate sull'elenco.`}},"acp%2Ebackend":{label:{"v1-vx60lb-b":`Backend ACP`},help:{"v1-1s1l6bz-2v":`ID del backend predefinito del runtime ACP (ad esempio: acpx). Deve corrispondere a un backend di un plugin del runtime ACP registrato.`}},"acp%2EdefaultAgent":{label:{"v1-xso6e7-h":`Agente ACP predefinito`},help:{"v1-7donnu-2c":`ID dell'agente di destinazione ACP di riserva, usato quando gli avvii ACP non specificano una destinazione esplicita.`}},"acp%2Edispatch%2Eenabled":{label:{"v1-nw9kyy-k":`Inoltro ACP abilitato`},help:{"v1-1ug9t9m-3w":`Controllo di abilitazione indipendente dell'inoltro per i turni delle sessioni ACP (valore predefinito: true). Imposta su false per mantenere disponibili i comandi ACP bloccando l'esecuzione dei turni ACP.`}},"acp%2Eenabled":{label:{"v1-5j1g3y-b":`ACP abilitato`},help:{"v1-1uonl1v-2a":`Controllo globale di abilitazione delle funzionalità ACP. Mantienilo disabilitato finché il runtime ACP e i criteri non sono configurati.`}},"acp%2Efallbacks":{label:{"v1-j79b6g-l":`Backend ACP di fallback`},help:{"v1-1wvdifq-5m":`Elenco ordinato degli ID dei backend ACP di fallback da provare quando il backend primario restituisce l'errore UNAVAILABLE (ad esempio: limite di richieste raggiunto / quota esaurita). Ogni voce deve corrispondere a un backend di un plugin runtime ACP registrato.`}},"acp%2Eruntime%2EinstallCommand":{label:{"v1-14jcqqd-r":`Comando di installazione del runtime ACP`},help:{"v1-1jjuv9m-39":"Comando facoltativo di installazione/configurazione per l'operatore, mostrato da `/acp install` e `/acp doctor` quando manca il collegamento al backend ACP."}},"acp%2Estream":{label:{"v1-1j9fe39-a":`Flusso ACP`},help:{"v1-1bka5p-2v":`Controlli della proiezione in streaming ACP per la dimensione dei blocchi, la visibilità dei metadati e il comportamento di invio senza duplicati.`}},"acp%2Estream%2EdeliveryMode":{label:{"v1-mfvqy2-o":`Modalità di invio del flusso ACP`},help:{"v1-19gdmx1-3s":`Modalità di invio ACP: live trasmette in streaming l'output proiettato in modo incrementale, final_only mantiene in un buffer tutto l'output ACP proiettato fino agli eventi di fine turno.`}},"acp%2Estream%2ErepeatSuppression":{label:{"v1-15imczj-t":`Soppressione delle ripetizioni nel flusso ACP`},help:{"v1-manh32-3d":`Se impostato su true (valore predefinito), sopprime le righe ripetute della proiezione di stato/strumenti ACP all'interno di un turno, mantenendo invariati gli eventi ACP grezzi.`}},"acp%2Estream%2EtagVisibility":{label:{"v1-6o90yj-p":`Visibilità dei tag del flusso ACP`},help:{"v1-1ybhx22-34":`Impostazioni di visibilità specifiche per ciascun sessionUpdate che prevalgono su quelle della proiezione ACP (ad esempio usage_update, available_commands_update).`}},agents:{label:{"v1-1sa8ub3-6":`Agenti`},help:{"v1-2rc4v8-55":`Radice della configurazione del runtime degli agenti. I nodi allo stesso livello della radice gestiscono l'infrastruttura e i valori predefiniti comuni a tutti gli agenti; agents.defaults gestisce il comportamento del ciclo degli agenti; le voci dei singoli agenti possono sovrascrivere entrambi, ove supportato.`}},"agents%2Edefaults":{label:{"v1-16khodg-e":`Impostazioni predefinite degli agenti`},help:{"v1-1af7k5b-5a":`Impostazioni predefinite condivise ereditate dagli agenti, salvo override nelle singole voci di agents.entries. Usa le impostazioni predefinite per garantire un comportamento di base coerente e ridurre le configurazioni duplicate per ciascun agente.`}},"agents%2Edefaults%2EauthInheritance":{label:{"v1-9wdrzg-n":`Destinazione dell'ereditarietà dell'autenticazione`},help:{"v1-2d16wl-2x":`Proprietario dell'archivio delle credenziali ereditato, mantenuto per compatibilità durante l'aggiornamento finché le credenziali non vengono trasferite ai singoli agenti.`}},"agents%2Edefaults%2EauthInheritance%2EagentId":{label:{"v1-bva26o-m":`Proprietario dell'ereditarietà dell'autenticazione`},help:{"v1-1a1s7nm-4s":`Agente il cui archivio delle credenziali legacy rimane la fonte dell'ereditarietà dopo la rimozione del marcatore predefinito. Scritto automaticamente durante l'aggiornamento quando il proprietario precedente non era main.`}},"agents%2Edefaults%2EbootstrapMaxChars":{label:{"v1-dzxrwm-j":`Numero massimo di caratteri di bootstrap`},help:{"v1-drlo3i-37":`Numero massimo di caratteri di ciascun file di bootstrap dell'area di lavoro inseriti nel prompt di sistema prima del troncamento (valore predefinito: 20000).`}},"agents%2Edefaults%2EbootstrapTotalMaxChars":{label:{"v1-brbs24-p":`Numero massimo totale di caratteri di bootstrap`},help:{"v1-1evwsjb-2c":`Numero massimo totale di caratteri per tutti i file di bootstrap dell'area di lavoro inseriti (valore predefinito: 60000).`}},"agents%2Edefaults%2Ecompaction":{label:{"v1-1d4drzc-a":`Compattazione`},help:{"v1-1qxdwz8-5p":`Comportamento di compattazione quando il contesto si avvicina ai limiti di token, inclusi la strategia e il comportamento di salvataggio della memoria prima della compattazione. Usa questa impostazione quando le sessioni di lunga durata richiedono una continuità stabile con finestre di contesto limitate.`}},"agents%2Edefaults%2Ecompaction%2Eenabled":{label:{"v1-iri7g4-o":`Compattazione automatica integrata`},help:{"v1-1et7vwu-5l":`Abilita la compattazione automatica proattiva integrata (valore predefinito: true). Imposta false per interrompere la compattazione integrata basata su soglie, mantenendo il recupero da overflow di OpenClaw, la compattazione preliminare e il comando manuale /compact.`}},"agents%2Edefaults%2Ecompaction%2EidentifierPolicy":{label:{"v1-i1jgob-s":`Criterio per gli identificatori nella compattazione`},help:{"v1-hby01l-4l":`Criterio di conservazione degli identificatori nei riepiloghi di compattazione: "strict" antepone le istruzioni integrate per la conservazione degli identificatori opachi (valore predefinito), mentre "off" disabilita questo prefisso.`}},"agents%2Edefaults%2Ecompaction%2EkeepRecentTokens":{label:{"v1-ljajga-t":`Token recenti da conservare nella compattazione`},help:{"v1-tgysub-5h":`Numero minimo di token della finestra di conversazione più recente da conservare durante la compattazione. Usa valori più alti per proteggere la continuità del contesto immediato e valori più bassi per conservare una porzione maggiore della cronologia meno recente.`}},"agents%2Edefaults%2Ecompaction%2EmaxActiveTranscriptBytes":{label:{"v1-1il6xj6-17":`Soglia di dimensione della trascrizione attiva per la compattazione`},help:{"v1-u715n1-90":`Soglia in byte che attiva la normale compattazione locale preliminare quando la finestra di trascrizione visibile al modello (dall'ultima compattazione o reimpostazione) raggiunge questa dimensione (byte o stringhe come "20mb"). Imposta 0 o lascia il valore non impostato per disabilitare. Limita anche le trascrizioni native di rollout di Codex app-server; i thread nativi che superano il limite ripartono da zero.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush":{label:{"v1-1sphznd-n":`Salvataggio della memoria prima della compattazione`},help:{"v1-18q0ve9-55":`Impostazioni di salvataggio della memoria prima della compattazione, che fanno eseguire all'agente una scrittura in memoria prima di una compattazione intensa. Mantieni questa funzione abilitata per le sessioni lunghe, in modo che il contesto rilevante venga salvato prima di una riduzione drastica.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Eenabled":{label:{"v1-14wdoio-v":`Salvataggio della memoria prima della compattazione abilitato`},help:{"v1-9xllgp-5o":`Abilita il salvataggio della memoria prima che il runtime esegua una riduzione più incisiva della cronologia in prossimità dei limiti di token. Mantieni questa opzione abilitata, a meno che tu non voglia disabilitare intenzionalmente gli effetti sulla memoria in ambienti con risorse limitate.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EforceFlushTranscriptBytes":{label:{"v1-10u43o5-1d":`Soglia di dimensione della trascrizione per il salvataggio della memoria prima della compattazione`},help:{"v1-1rzov1e-93":`Forza il salvataggio della memoria prima della compattazione quando la finestra della trascrizione visibile al modello raggiunge questa soglia (in byte o con stringhe come "2mb"). Dopo la compattazione, questa finestra include la parte finale conservata e i turni successivi, anziché la cronologia scartata. Usa questa opzione per evitare blocchi nelle sessioni lunghe anche quando i contatori di token non sono aggiornati; imposta su 0 per disabilitarla.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Emodel":{label:{"v1-z6o9nc-12":`Modello alternativo per il salvataggio della memoria prima della compattazione`},help:{"v1-1r3ctyu-7w":`Fornitore/modello alternativo facoltativo, utilizzato solo per i turni di salvataggio della memoria prima della compattazione. Imposta un modello locale come ollama/qwen3:8b quando l'estrazione della memoria persistente deve evitare il modello a pagamento della sessione attiva. La sostituzione è esatta e non eredita la catena di fallback del modello attivo.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EsoftThresholdTokens":{label:{"v1-1h1tkzc-12":`Soglia flessibile per il salvataggio della memoria prima della compattazione`},help:{"v1-1dqo2l1-5c":`Distanza dalla soglia di compattazione (in token) che attiva il salvataggio della memoria prima della compattazione. Usa soglie anticipate per una persistenza più sicura oppure soglie più ravvicinate per ridurre la frequenza dei salvataggi.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck":{label:{"v1-rb9ni9-s":`Controllo preliminare della compattazione durante il turno`},help:{"v1-am6gbh-6x":`Controllo preliminare facoltativo integrato nel ciclo degli strumenti di OpenClaw che rileva la pressione sul contesto dopo l'aggiunta del risultato di uno strumento e prima della successiva chiamata al modello. Quando è abilitato, OpenClaw riutilizza il meccanismo di recupero del controllo preliminare esistente per troncare i risultati degli strumenti o compattare il contesto prima di riprovare.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck%2Eenabled":{label:{"v1-1kxoip4-10":`Controllo preliminare della compattazione durante il turno abilitato`},help:{"v1-engbwe-5u":`Abilita controlli strutturati della pressione sul contesto durante il turno per i cicli degli strumenti integrati in OpenClaw. Valore predefinito: false. Lascia disabilitato, a meno che le sessioni lunghe con uso intensivo degli strumenti non superino il limite del contesto prima che possa essere eseguita la normale compattazione di fine turno.`}},"agents%2Edefaults%2Ecompaction%2Emode":{label:{"v1-70zfez-f":`Modalità di compattazione`},help:{"v1-1unahwc-76":`Modalità della strategia di compattazione: "safeguard" (il valore predefinito effettivo se non impostato) applica misure di protezione per preservare il contesto recente, mentre "default" usa una sintesi di base senza tali misure. Imposta "default" solo se la sintesi con "safeguard" causa problemi con il tuo fornitore.`}},"agents%2Edefaults%2Ecompaction%2Emodel":{label:{"v1-rqz37z-p":`Modello alternativo per la compattazione`},help:{"v1-cfeys9-6q":`Fornitore/modello facoltativo o alias semplice configurato, usato solo per la sintesi di compattazione. Gli alias semplici vengono risolti prima dell'invio; un ID modello letterale configurato ha la precedenza in caso di conflitto con un alias. Lascia non impostato per continuare a usare il modello principale dell'agente.`}},"agents%2Edefaults%2Ecompaction%2EnotifyUser":{label:{"v1-ub28vk-m":`Notifica all'utente della compattazione`},help:{"v1-lvymm8-bv":`Quando abilitata, invia all'utente brevi avvisi sulla manutenzione del contesto: all'avvio e al completamento della compattazione (ad esempio, '🧹 Compattazione del contesto...' e '🧹 Compattazione completata') e quando i tentativi di salvataggio della memoria prima della compattazione sono esauriti, per cui la risposta prosegue in condizioni degradate (ad esempio, '⚠️ Manutenzione della memoria temporaneamente non riuscita; la risposta prosegue.'). Disabilitata per impostazione predefinita per mantenere la manutenzione del contesto silenziosa e non invasiva.`}},"agents%2Edefaults%2Ecompaction%2EpostCompactionSections":{label:{"v1-x1uxbk-w":`Sezioni del contesto dopo la compattazione`},help:{"v1-1n0ln2u-5f":`Nomi delle sezioni H2/H3 di AGENTS.md da reinserire dopo la compattazione, previa attivazione esplicita. Lasciare non impostato o impostare [] per disabilitare il reinserimento. Impostare esplicitamente ["Session Startup", "Red Lines"] per abilitare la coppia predefinita delle versioni precedenti.`}},"agents%2Edefaults%2Ecompaction%2EpostIndexSync":{label:{"v1-1p0j1ty-q":`Sincronizzazione dell'indice dopo la compattazione`},help:{"v1-ekpjeq-6l":`Controlla la modalità di reindicizzazione della memoria di sessione dopo la compattazione: "off", "async" o "await" (impostazione predefinita: "async"). Usare "await" per garantire il massimo aggiornamento, "async" per ridurre la latenza della compattazione e "off" solo quando la sincronizzazione della memoria di sessione è gestita altrove.`}},"agents%2Edefaults%2Ecompaction%2Eprovider":{label:{"v1-1autmd-j":`Provider di compattazione`},help:{"v1-kiwk91-86":`ID di un plugin provider di compattazione registrato, usato per la sintesi. Quando è impostato e il provider è registrato, viene chiamato il relativo metodo summarize() al posto della pipeline integrata summarizeInStages. In caso di errore del provider, viene usata la sintesi integrata. Lasciare non impostato per usare la sintesi integrata predefinita.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard":{label:{"v1-nh0x1k-o":`Controllo qualità della compattazione`},help:{"v1-u9ognp-4k":`Impostazioni dei tentativi di verifica della qualità per i riepiloghi di compattazione in modalità safeguard. La modalità safeguard attiva questa funzione per impostazione predefinita; imposta enabled: false per saltare le verifiche e la rigenerazione dei riepiloghi.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2Eenabled":{label:{"v1-14z377t-w":`Controllo qualità della compattazione attivato`},help:{"v1-1xk2vt3-36":`Attiva le verifiche della qualità dei riepiloghi e i tentativi di rigenerazione per la compattazione in modalità safeguard. Valore predefinito: true in modalità safeguard.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2EmaxRetries":{label:{"v1-1wbiubo-10":`Numero massimo di tentativi del controllo qualità della compattazione`},help:{"v1-n7l46y-3y":`Numero massimo di tentativi di rigenerazione dopo una verifica non superata della qualità del riepilogo in modalità safeguard. Usa valori bassi per limitare la latenza aggiuntiva e il costo dei token.`}},"agents%2Edefaults%2Ecompaction%2ErecentTurnsPreserve":{label:{"v1-lhuyqv-w":`Conservazione dei turni recenti durante la compattazione`},help:{"v1-y34ihi-5k":`Numero di turni utente/assistente più recenti conservati integralmente ed esclusi dalla sintesi in modalità safeguard (valore predefinito: 3). Aumenta questo valore per preservare il contesto esatto del dialogo recente oppure riducilo per massimizzare il risparmio ottenuto con la compattazione.`}},"agents%2Edefaults%2Ecompaction%2EthinkingLevel":{label:{"v1-5qtj6m-p":`Livello di ragionamento della compattazione`},help:{"v1-1vafgaw-g1":`Livello di ragionamento utilizzato solo per i riepiloghi di compattazione incorporati di OpenClaw: "off", "minimal", "low", "medium", "high", "xhigh", "adaptive", "max", "ultra" o "inherit". Per impostazione predefinita, usa la preferenza di compattazione del provider, altrimenti "low"; Ollama locale nativo preferisce "off". Imposta "inherit" per riutilizzare il livello della sessione. Le impostazioni esplicite prevalgono sui valori predefiniti del provider e il livello selezionato viene limitato in base al modello e al runtime di compattazione effettivi. La compattazione nativa di Codex app-server ignora questa impostazione perché la sua richiesta di compattazione non prevede una sostituzione del livello di ragionamento per singola operazione e OpenClaw registra un avviso.`}},"agents%2Edefaults%2Ecompaction%2EtimeoutSeconds":{label:{"v1-1x6zijf-s":`Timeout di compattazione (secondi)`},help:{"v1-2bhn29-7m":`Intervallo di sicurezza in secondi per ogni richiesta integrata al modello di compattazione (valore predefinito: 180). La compattazione in più fasi rinnova l'intervallo all'avvio di ogni richiesta sequenziale, quindi la compattazione completa può richiedere più tempo; la compattazione gestita da un plugin riceve un unico intervallo per l'intera operazione.`}},"agents%2Edefaults%2EcontextInjection":{label:{"v1-1blm5yl-h":`Inserimento del contesto`},help:{"v1-u18x0-7u":`Controlla l'iniezione dei file di inizializzazione dell'area di lavoro nel runtime incorporato: "always" usa l'iniezione normale (impostazione predefinita), "continuation-skip" salta i turni di continuazione idonei dopo un turno registrato con inizializzazione completa e "never" disabilita l'iniezione. Non controlla la preparazione dei prompt tramite CLI.`}},"agents%2Edefaults%2EcontextLimits":{label:{"v1-1lphwvv-m":`Limiti di contesto predefiniti`},help:{"v1-1coeez8-5d":`Valori predefiniti mirati per il budget di contesto di ciascun agente, applicati a estratti selezionati di grandi dimensioni e blocchi di prompt inseriti. Usa questa opzione per regolare i limiti di lettura e inserimento senza riaprire percorsi di chiamata privi di limiti.`}},"agents%2Edefaults%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-197rwel-s":`Numero massimo predefinito di caratteri per memory_get`},help:{"v1-1qb40qv-4v":`Numero massimo predefinito di caratteri restituiti da memory_get prima dell'aggiunta dei metadati di troncamento e dell'avviso di continuazione. Aumentalo per ottenere estratti più ampi, simili a quelli precedenti, ma mantieni un limite ragionevole.`}},"agents%2Edefaults%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-hh1flp-x":`Numero massimo predefinito di caratteri dopo la compattazione`},help:{"v1-64qo8g-5r":`Numero massimo predefinito di caratteri conservati da AGENTS.md durante l'iniezione di aggiornamento del contesto dopo la compattazione. Riduci questo valore per rendere meno costoso il ripristino dopo la compattazione, oppure aumentalo per gli agenti che dipendono da istruzioni iniziali più lunghe.`}},"agents%2Edefaults%2Ecwd":{label:{"v1-1akuwgr-h":`Directory di lavoro`},help:{"v1-1y8wlxn-6a":`Directory di lavoro per le esecuzioni di risposta dell'agente, separata dai file di inizializzazione dello spazio di lavoro e di memoria. Il valore cwd specifico dell'agente e quello delle sessioni create hanno la precedenza. Supporta ~ e percorsi relativi; un valore cwd distinto richiede un'esecuzione senza sandbox.`}},"agents%2Edefaults%2EdecisionModel":{label:{"v1-45jwcu-e":`Modello decisionale`},help:{"v1-7nd7ze-64":`Provider/modello facoltativo per scelte tipizzate, punteggi e probabilità booleane. Se non impostato o vuoto, disabilita le chiamate decisionali. I plugin compatibili inviano a questo provider un insieme limitato di dati relativi all'attività; i modelli di chat e di utilità restano invariati.`}},"agents%2Edefaults%2EembeddedAgent":{label:{"v1-78x3fi-h":`OpenClaw incorporato`},help:{"v1-1keek32-3k":`Controlli di rafforzamento della sicurezza del motore di esecuzione OpenClaw incorporato, che definiscono come le impostazioni dell'agente locali allo spazio di lavoro vengono considerate attendibili e applicate nelle sessioni OpenClaw.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover":{label:{"v1-1qnu0am-l":`Failover per le policy di sicurezza informatica`},help:{"v1-xvv6wl-2r":`Escalation automatica a Daybreak per i rifiuti dovuti alle policy di sicurezza informatica di OpenAI nel runtime integrato, quando la ripetizione della richiesta è sicura.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2EcooloffMs":{label:{"v1-j5ckj0-t":`Pausa del failover per le policy di sicurezza informatica`},help:{"v1-16smtrl-25":`Per quanto tempo una destinazione di escalation non disponibile viene ignorata nella sessione corrente.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emode":{label:{"v1-1mx8pup-q":`Modalità di failover per le policy di sicurezza informatica`},help:{"v1-rzsd2b-2h":`Abilita l'escalation automatica ("auto", impostazione predefinita) oppure mantieni definitivi i rifiuti del provider ("off").`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emodel":{label:{"v1-1oxd3p3-r":`Modello di failover per le policy di sicurezza informatica`},help:{"v1-1aaj8nn-1t":`Provider/modello di destinazione usato per l'escalation automatica relativa alle policy di sicurezza informatica.`}},"agents%2Edefaults%2EembeddedAgent%2EexecutionContract":{label:{"v1-1e1r7sa-10":`Contratto di esecuzione di OpenClaw incorporato`},help:{"v1-1fch2ig-66":`Contratto di esecuzione di OpenClaw incorporato: "default" mantiene il comportamento standard del motore di esecuzione, mentre "strict-agentic" abilita il monitoraggio strutturato del piano e il recupero non visibile dei turni per le esecuzioni supportate della famiglia GPT-5 di OpenAI/OpenAI Codex.`}},"agents%2Edefaults%2EembeddedAgent%2EprojectSettingsPolicy":{label:{"v1-xaw8em-15":`Criteri delle impostazioni di progetto di OpenClaw incorporato`},help:{"v1-fdyy04-65":'Come OpenClaw integrato gestisce il file `.openclaw/settings.json` locale dell\'area di lavoro: "sanitize" (predefinito) rimuove shellPath/shellCommandPrefix, "ignore" disabilita completamente le impostazioni del progetto e "trusted" le applica così come sono.'}},"agents%2Edefaults%2Eexperimental":{label:{"v1-biomsl-o":`Opzioni sperimentali dell'agente`},help:{"v1-cvv5cl-2w":`Opzioni sperimentali predefinite degli agenti. Mantienile disattivate, a meno che tu non stia testando intenzionalmente una funzionalità in anteprima.`}},"agents%2Edefaults%2Eexperimental%2ElocalModelLean":{label:{"v1-x4h50k-17":`Abilita la modalità leggera per i modelli locali (sperimentale)`},help:{"v1-gj06u6-7b":`Impostazione avanzata per la risoluzione dei problemi che limita gli strumenti facoltativi come browser, automations e message. Disattivata per impostazione predefinita; i runtime locali supportati usano la ricerca automatica degli strumenti senza questa limitazione. Le autorizzazioni esplicite per gli strumenti e gli strumenti di consegna obbligatori vengono mantenuti.`}},"agents%2Edefaults%2EfastModeDefault":{label:{"v1-1l6uhpu-n":`Modalità veloce predefinita dell'agente`},help:{"v1-zv4y98-2z":`Criterio predefinito della modalità veloce per il ciclo dell'agente ("auto", true o false). Le voci dei singoli agenti hanno la precedenza.`}},"agents%2Edefaults%2Eheartbeat%2EagentId":{label:{"v1-1kugcom-f":`Agente heartbeat`},help:{"v1-1jynxej-3w":`Agente responsabile delle esecuzioni heartbeat in background quando non esiste una configurazione heartbeat specifica per agente. Lascia il valore non impostato per mantenere l'instradamento predefinito configurato.`}},"agents%2Edefaults%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`Criterio per i messaggi diretti heartbeat`},help:{"v1-nhyxa9-41":`Controlla se gli heartbeat possono essere recapitati a chat dirette o messaggi privati: "allow" (predefinito) consente il recapito tramite messaggi privati e "block" impedisce gli invii a destinatari diretti.`}},"agents%2Edefaults%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`Timeout del segnale periodico (secondi)`},help:{"v1-1se21py-5f":`Tempo massimo in secondi consentito per un turno dell'agente attivato dal segnale periodico prima che venga interrotto. Lasciare non impostato per usare agents.defaults.timeoutSeconds, se impostato, altrimenti l'intervallo del segnale periodico, con un limite massimo di 600 secondi.`}},"agents%2Edefaults%2EhumanDelay%2EmaxMs":{label:{"v1-1mrn73i-k":`Ritardo umano massimo (ms)`},help:{"v1-vnmvli-1m":`Ritardo massimo in ms per humanDelay personalizzato (valore predefinito: 2500).`}},"agents%2Edefaults%2EhumanDelay%2EminMs":{label:{"v1-1wd5i8o-k":`Ritardo umano minimo (ms)`},help:{"v1-5nrtr5-1l":`Ritardo minimo in ms per humanDelay personalizzato (valore predefinito: 800).`}},"agents%2Edefaults%2EhumanDelay%2Emode":{label:{"v1-ck9798-g":`Modalità del ritardo umano`},help:{"v1-k7hyg3-1n":`Tipo di ritardo per le risposte a blocchi ("off", "natural", "custom").`}},"agents%2Edefaults%2EimageMaxDimensionPx":{label:{"v1-qmer27-o":`Dimensione massima delle immagini (px)`},help:{"v1-vju8x-2u":`Lunghezza massima del lato delle immagini in pixel durante la sanitizzazione dei dati immagine nelle trascrizioni e nei risultati degli strumenti (valore predefinito: 1200).`}},"agents%2Edefaults%2EimageModel%2Efallbacks":{label:{"v1-d75sz8-l":`Modelli alternativi per le immagini`},help:{"v1-1kgx5i9-1b":`Modelli alternativi per le immagini in ordine di priorità (provider/model).`}},"agents%2Edefaults%2EimageModel%2Eprimary":{label:{"v1-1533tn-b":`Modello per le immagini`},help:{"v1-dstqyh-2c":`Modello opzionale per le immagini (provider/model) usato quando il modello principale non supporta immagini in ingresso.`}},"agents%2Edefaults%2EimageQuality":{label:{"v1-1x0wkcr-d":`Qualità delle immagini`},help:{"v1-1uyxc5s-6u":`Preferenza di compressione dei contenuti multimediali per lo strumento immagini: "auto" si adatta ai limiti del fornitore/modello e al numero di immagini, "efficient" riduce il consumo di token e byte, "balanced" mantiene l'attuale compromesso e "high" conserva più dettagli per schermate e immagini di documenti.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Efallbacks":{label:{"v1-104q8cy-w":`Modelli alternativi per la generazione di immagini`},help:{"v1-oljfk4-1m":`Elenco ordinato dei modelli alternativi per la generazione di immagini (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Eprimary":{label:{"v1-hzzdnh-m":`Modello per la generazione di immagini`},help:{"v1-g4yw0h-2o":`Modello facoltativo per la generazione di immagini (provider/model) utilizzato dalla funzionalità condivisa di generazione di immagini.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2EtimeoutMs":{label:{"v1-4y5oza-t":`Timeout per la generazione di immagini (ms)`},help:{"v1-9yesfj-31":`Timeout predefinito in millisecondi delle richieste al fornitore per le chiamate image_generate. Il valore timeoutMs della singola chiamata ha la precedenza.`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Efallbacks":{label:{"v1-qkwbmc-w":`Modelli alternativi per la generazione musicale`},help:{"v1-wyg9xe-1m":`Elenco ordinato dei modelli alternativi per la generazione musicale (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Eprimary":{label:{"v1-f7mzln-m":`Modello per la generazione musicale`},help:{"v1-xs1e2h-2o":`Modello facoltativo per la generazione musicale (provider/model) utilizzato dalla funzionalità condivisa di generazione musicale.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Efallbacks":{label:{"v1-xoqak-w":`Modelli alternativi per la generazione di video`},help:{"v1-wpbf1e-1m":`Modelli alternativi per la generazione video in ordine di priorità (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Eprimary":{label:{"v1-fokknn-m":`Modello di generazione video`},help:{"v1-hfmlbl-2o":`Modello opzionale di generazione video (provider/model) utilizzato dalla funzionalità condivisa di generazione video.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2EtimeoutMs":{label:{"v1-1dtok9w-t":`Timeout della generazione video (ms)`},help:{"v1-1bqj80s-4i":`Timeout predefinito delle richieste al provider in millisecondi per le chiamate video_generate. Il valore timeoutMs della singola chiamata ha la precedenza su questo valore, che a sua volta ha la precedenza sui valori predefiniti del provider.`}},"agents%2Edefaults%2Emodel%2Efallbacks":{label:{"v1-dz2y4l-f":`Modelli alternativi`},help:{"v1-t4djq2-24":`Modelli alternativi in ordine di priorità (provider/model). Utilizzati quando il modello principale non funziona.`}},"agents%2Edefaults%2Emodel%2Eprimary":{label:{"v1-1jjnzq0-d":`Modello principale`},help:{"v1-1i8a1v4-v":`Modello principale (provider/model).`}},"agents%2Edefaults%2EmodelPolicy":{label:{"v1-m0l2o-c":`Criteri per i modelli`},help:{"v1-z0txb7-2e":`Criteri espliciti per la sostituzione dei modelli. Omettili o lascia allow vuoto per consentire qualsiasi modello.`}},"agents%2Edefaults%2EmodelPolicy%2Eallow":{label:{"v1-a807hj-e":`Modelli consentiti`},help:{"v1-1fqace-3x":`Riferimenti ai modelli consentiti per la sostituzione. Accetta alias, riferimenti completi "provider/model" e caratteri jolly per i provider come "openai/*". Se vuoto, consente qualsiasi modello.`}},"agents%2Edefaults%2Emodels":{label:{"v1-hzmwb-6":`Modelli`},help:{"v1-13cvq23-4i":`Catalogo dei modelli configurati e impostazioni per ciascun modello. Le voci forniscono alias, parametri, metadati di runtime e impostazioni sostitutive per Code Mode; non limitano la sostituzione dei modelli.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime":{label:{"v1-7nd0vy-r":`Runtime del modello dell'agente predefinito`},help:{"v1-6km9kx-41":`Criterio di runtime facoltativo per ciascun modello dell'agente predefinito. Usalo per definire eccezioni di runtime specifiche per un modello anziché impostare un runtime per l'intero agente.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-y10gjb-u":`ID runtime del modello dell'agente predefinito`},help:{"v1-1co96w7-4a":`ID runtime del modello dell'agente predefinito: "openclaw", "auto", un ID harness di un plugin registrato come "codex" oppure un alias di backend CLI supportato come "claude-cli".`}},"agents%2Edefaults%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Modalità codice`},help:{"v1-rsdl5o-6x":`Modalità codice di OpenClaw per questa specifica combinazione di provider e modello: Attivata ne forza l'attivazione, Disattivata la disabilita e Predefinita eredita tools.codeMode.enabled. Le impostazioni di attivazione specifiche dell'agente hanno la precedenza. Questa opzione non modifica il runtime selezionato né la modalità codice nativa di Codex.`}},"agents%2Edefaults%2EmodelSelectionScope":{label:{"v1-rtarqk-l":`Ambito di selezione del modello`},help:{"v1-sj8owq-bl":`Ambito per i comandi di chat e gli aggiornamenti del modello di sessione del Gateway senza un ambito esplicito: "session" (predefinito) modifica solo la sessione corrente, "agent" aggiorna anche il modello principale di quell'agente e "global" aggiorna anche il modello di fallback condiviso agents.defaults.model. I flag di ambito espliciti hanno la precedenza; le modifiche ai valori predefiniti configurati richiedono i privilegi di proprietario o amministratore. I selettori di callback di Telegram e la TUI locale integrata restano limitati alla sessione.`}},"agents%2Edefaults%2EpdfMaxMb":{label:{"v1-ked92u-h":`Dimensione massima PDF (MB)`},help:{"v1-1uig1dr-1u":`Dimensione massima dei file PDF in megabyte per lo strumento PDF (predefinita: 10).`}},"agents%2Edefaults%2EpdfMaxPages":{label:{"v1-1mbzuxr-d":`Numero massimo di pagine PDF`},help:{"v1-11na7hp-1y":`Numero massimo di pagine PDF da elaborare con lo strumento PDF (valore predefinito: 20).`}},"agents%2Edefaults%2EpdfModel%2Efallbacks":{label:{"v1-pu595v-j":`Modelli PDF di ripiego`},help:{"v1-89ebd8-19":`Modelli PDF di ripiego in ordine di priorità (provider/model).`}},"agents%2Edefaults%2EpdfModel%2Eprimary":{label:{"v1-u2jryk-9":`Modello PDF`},help:{"v1-2ktkxt-2y":`Modello PDF facoltativo (provider/model) per lo strumento di analisi PDF. Per impostazione predefinita usa imageModel, quindi il modello della sessione.`}},"agents%2Edefaults%2ErepoRoot":{label:{"v1-1wgofmz-9":`Radice del repository`},help:{"v1-j3sh74-2h":`Radice facoltativa del repository mostrata nella riga del runtime del prompt di sistema (sostituisce il rilevamento automatico).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-a168yk-11":`Intervallo di porte di origine CDP del browser nella sandbox`},help:{"v1-1jkowdc-2b":`Elenco facoltativo di indirizzi CIDR consentiti per il traffico CDP in ingresso al perimetro del container (ad esempio 172.21.0.1/32).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-w9qjiq-n":`Rete del browser nella sandbox`},help:{"v1-8m74ud-5w":`Rete Docker per i container del browser nella sandbox (valore predefinito: openclaw-sandbox-browser). Usa la rete predefinita dedicata o una rete bridge personalizzata; "none" non è supportato perché il controllo del browser richiede porte CDP pubblicate.`}},"agents%2Edefaults%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-m0t0f7-19":`Consenti l'accesso al namespace di un container per Docker nella sandbox`},help:{"v1-qm39de-4c":`Deroga di emergenza PERICOLOSA che consente la modalità di rete Docker container:<id> nella sandbox. Questa opzione accede al namespace di un altro container e indebolisce l'isolamento della sandbox.`}},"agents%2Edefaults%2Esandbox%2Edocker%2Egpus":{label:{"v1-c8tb-j":`GPU Docker della sandbox`},help:{"v1-jj0yhw-4k":`Valore opzionale per il passthrough delle GPU Docker passato a --gpus, ad esempio "all" o "device=GPU-uuid". Richiede un runtime host compatibile come NVIDIA Container Toolkit.`}},"agents%2Edefaults%2EsessionStore":{label:{"v1-qna6lw-r":`Destinazione dell'archivio sessioni legacy`},help:{"v1-1xkej6i-2g":`Proprietario per la compatibilità durante l'aggiornamento delle righe main-agent dismesse e degli archivi sessioni legacy fissi.`}},"agents%2Edefaults%2EsessionStore%2EagentId":{label:{"v1-3s8frc-q":`Proprietario dell'archivio sessioni legacy`},help:{"v1-ommm7e-5w":`Agente proprietario delle righe main-agent dismesse o delle righe prive di ambito in un archivio sessioni legacy fisso dopo la dismissione di default-marker. Scritto automaticamente durante l'aggiornamento quando il precedente proprietario non era main né l'unico agente.`}},"agents%2Edefaults%2Eskills":{label:{"v1-1bk7xrz-6":`Skills`},help:{"v1-1pbsu94-75":`Elenco opzionale predefinito delle abilità consentite, ereditato dagli agenti che omettono agents.entries.*.skills. Ometterlo per non limitare le abilità, impostare [] per non assegnare alcuna abilità agli agenti che lo ereditano e ricordare che un valore esplicito di agents.entries.*.skills sostituisce questo valore predefinito anziché unirsi a esso.`}},"agents%2Edefaults%2EskipBootstrap":{label:{"v1-10c1qje-x":`Salta la creazione dei file di inizializzazione dell'area di lavoro`},help:{"v1-kbstgw-5v":`Salta la creazione automatica dei file di inizializzazione dell'area di lavoro, ma non l'iniezione dei file esistenti. Per il runtime incorporato, imposta agents.defaults.contextInjection su "never" per disabilitare l'iniezione, salvo override per singolo agente.`}},"agents%2Edefaults%2EskipOptionalBootstrapFiles":{label:{"v1-xzxxz4-w":`File di inizializzazione opzionali ignorati`},help:{"v1-1j2z4yj-4c":`File di inizializzazione opzionali che non devono essere creati negli spazi di lavoro degli agenti. Valori validi: SOUL.md, USER.md, IDENTITY.md (HEARTBEAT.md è accettato ma non ha alcun effetto).`}},"agents%2Edefaults%2EstartupContext":{label:{"v1-2srlwp-f":`Contesto di avvio`},help:{"v1-1ugsihy-5o":`Preludio del primo turno gestito dal runtime per "/new" e "/reset" senza argomenti. Consente di scegliere se precaricare i file di memoria giornaliera recenti nel primo prompt anziché chiedere al modello di decidere cosa leggere.`}},"agents%2Edefaults%2EstartupContext%2EapplyOn":{label:{"v1-8ngrte-o":`Comandi a cui applicare il contesto iniziale`},help:{"v1-wav4a5-36":`Specifica quali comandi di reimpostazione senza argomenti ricevono il contesto iniziale: includere "new", "reset" o entrambi (valore predefinito: ["new","reset"]).`}},"agents%2Edefaults%2EstartupContext%2EdailyMemoryDays":{label:{"v1-oj0fzi-x":`Giorni di memoria giornaliera nel contesto iniziale`},help:{"v1-4i5xcm-3p":`Numero di file di memoria datati da caricare, contando a ritroso da oggi nel fuso orario configurato per l’utente (valore predefinito: 2, per oggi e ieri).`}},"agents%2Edefaults%2EstartupContext%2Eenabled":{label:{"v1-1iode8k-m":`Abilita il contesto iniziale`},help:{"v1-1d5vz2u-4i":`Abilita il preludio del contesto iniziale per le reimpostazioni della sessione senza argomenti (valore predefinito: true). Disabilitare questa opzione per tornare al comportamento basato solo sul prompt, senza memoria giornaliera caricata dal runtime.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileBytes":{label:{"v1-816erw-u":`Byte massimi per file nel contesto iniziale`},help:{"v1-11cbian-41":`Numero massimo di byte consentiti per ciascun file di memoria giornaliera durante la creazione del contesto iniziale (valore predefinito: 16384). I file che superano questo limite di lettura sicura vengono ignorati.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileChars":{label:{"v1-1xzziaa-u":`Caratteri massimi per file nel contesto iniziale`},help:{"v1-10z53s-2u":`Numero massimo di caratteri conservati da ciascun file di memoria giornaliera caricato nel preludio iniziale (valore predefinito: 1200).`}},"agents%2Edefaults%2EstartupContext%2EmaxTotalChars":{label:{"v1-1gx8bpc-v":`Numero massimo totale di caratteri del contesto di avvio`},help:{"v1-sf676u-54":`Numero massimo totale di caratteri conservati in tutti i file di memoria giornaliera caricati nel preambolo di avvio (valore predefinito: 2800). Una volta raggiunto questo limite, i file aggiuntivi vengono troncati nel preambolo.`}},"agents%2Edefaults%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Modalità di delega ai sottoagenti`},help:{"v1-pqewbk-5o":`Intensità della delega ai sottoagenti applicata solo tramite prompt. Il valore predefinito è "prefer" nella sessione principale di ciascun agente e "suggest" altrove; "prefer" indica con forza all'agente di delegare le attività non banali tramite sessions_spawn.`}},"agents%2Edefaults%2EsystemAgent":{label:{"v1-d8xvga-j":`Destinazione dell'agente di sistema`},help:{"v1-1wwimo9-34":`Impostazioni di destinazione per l'inferenza in background dell'agente di sistema OpenClaw e di Custodian, oltre che per alcune letture dell'operatore senza ambito specificato.`}},"agents%2Edefaults%2EsystemAgent%2EagentId":{label:{"v1-xsnrm-i":`Proprietario dell'agente di sistema`},help:{"v1-15rvt92-8c":`Agente di cui vengono usati il modello e le credenziali per le consultazioni in background dell'agente di sistema e di Custodian. Viene usato anche quando models.list, models.authStatus, skills.status, doctor.memory.status o un comando CLI infer che risolve il modello o lo stato di autenticazione di proprietà dell'agente omette agentId o --agent; un agentId esplicito nella richiesta ha sempre la precedenza.`}},"agents%2Edefaults%2EtypingIntervalSeconds":{label:{"v1-5vbq6f-p":`Intervallo di digitazione (secondi)`},help:{"v1-1y701ox-42":`Controlla la frequenza, in secondi, con cui viene mantenuto attivo l'indicatore di digitazione per ogni agente. Aumenta questo valore per ridurre la frequenza degli aggiornamenti su tutti i canali che supportano gli indicatori di digitazione.`}},"agents%2Edefaults%2EtypingMode":{label:{"v1-17u58e1-b":`Modalità di digitazione`},help:{"v1-m2hvpw-3m":`Controlla quando gli agenti iniziano a mostrare l'indicatore di digitazione: "never", "instant", "thinking" o "message". Il valore typingMode del singolo agente ha la precedenza su questa impostazione predefinita.`}},"agents%2Edefaults%2EutilityModel":{label:{"v1-7gi7gi-d":`Modello ausiliario`},help:{"v1-1wg7h1a-7s":`Modello opzionale a costo ridotto (provider/model o alias) per brevi attività interne, come la generazione di titoli e la descrizione dell'avanzamento. Se non impostato, viene usato il modello di piccole dimensioni dichiarato dal provider principale, se disponibile (altrimenti il modello principale); impostare una stringa vuota per disabilitare l'instradamento al modello ausiliario.`}},"agents%2Edefaults%2EvoiceModel%2Efallbacks":{label:{"v1-v34llj-l":`Modelli vocali di riserva`},help:{"v1-faazv4-1b":`Modelli vocali di riserva in ordine di priorità (provider/model).`}},"agents%2Edefaults%2EvoiceModel%2Eprimary":{label:{"v1-hvyby0-b":`Modello vocale`},help:{"v1-1yeh3h4-2t":`Modello vocale opzionale (provider/model) utilizzato dalle funzionalità di sintesi vocale, trascrizione e voce in tempo reale.`}},"agents%2Edefaults%2EvoiceModel%2EtimeoutMs":{label:{"v1-1hw6a5x-i":`Timeout vocale (ms)`},help:{"v1-1sbergs-32":`Timeout predefinito delle richieste al provider, in millisecondi, per le operazioni del modello vocale quando il chiamante supporta i timeout.`}},"agents%2Edefaults%2Eworkspace":{label:{"v1-aw4cba-9":`Area di lavoro`},help:{"v1-1lssx8l-5w":`Area di lavoro predefinita degli agenti per i file di inizializzazione e di memoria. Viene usata anche come directory di lavoro quando agents.defaults.cwd non è impostato. Impostarla esplicitamente quando si esegue tramite wrapper, in modo che la risoluzione dei percorsi rimanga deterministica.`}},"agents%2Eentries":{label:{"v1-1ts48oe-a":`Elenco degli agenti`},help:{"v1-yurood-5l":`Elenco esplicito degli agenti configurati, con ID e impostazioni personalizzate opzionali per modello, strumenti, identità e area di lavoro. Mantenere gli ID stabili nel tempo affinché le associazioni, le approvazioni e l'instradamento delle sessioni rimangano deterministici.`}},"agents%2Eentries%2E*%2EagentRuntime":{label:{"v1-rmaqyr-k":`Runtime legacy dell'agente`}},"agents%2Eentries%2E*%2EagentRuntime%2Eid":{label:{"v1-mtthss-n":`ID del runtime legacy dell'agente`}},"agents%2Eentries%2E*%2EbootstrapMaxChars":{label:{"v1-beqsv3-p":`Numero massimo di caratteri di inizializzazione dell'agente`},help:{"v1-rsf1es-4j":`Impostazione specifica per l'agente che sostituisce il numero massimo di caratteri di ciascun file di inizializzazione dell'area di lavoro inserito nel prompt di sistema di questo agente. Omettere per ereditare agents.defaults.bootstrapMaxChars.`}},"agents%2Eentries%2E*%2EbootstrapTotalMaxChars":{label:{"v1-1hf8zr9-v":`Numero massimo totale di caratteri di inizializzazione dell'agente`},help:{"v1-1bal68p-4y":`Impostazione specifica per l'agente che sostituisce il numero massimo totale di caratteri di tutti i file di inizializzazione dell'area di lavoro inseriti nel prompt di sistema di questo agente. Omettere per ereditare agents.defaults.bootstrapTotalMaxChars.`}},"agents%2Eentries%2E*%2EcontextInjection":{label:{"v1-1rpaags-n":`Inserimento del contesto dell'agente`},help:{"v1-1j68ys8-50":`Impostazione specifica per agente che sostituisce quella predefinita per l'iniezione dei file di bootstrap dell'area di lavoro nel runtime incorporato. Omettere per ereditare agents.defaults.contextInjection. Non controlla la preparazione dei prompt tramite CLI.`}},"agents%2Eentries%2E*%2EcontextLimits":{label:{"v1-1nx137n-k":`Limiti del contesto dell'agente`},help:{"v1-f1qxq8-3c":`Impostazioni facoltative specifiche per l'agente che sostituiscono i parametri mirati del budget di contesto. I campi omessi ereditano agents.defaults.contextLimits.`}},"agents%2Eentries%2E*%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-7rulph-q":`Numero massimo di caratteri di memory_get dell'agente`},help:{"v1-12hlmsv-1v":`Impostazione specifica per l'agente che sostituisce il budget massimo predefinito di caratteri di memory_get.`}},"agents%2Eentries%2E*%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-s7gnc5-v":`Numero massimo di caratteri dell'agente dopo la compattazione`},help:{"v1-15s0npd-1w":`Override per agente del limite di caratteri per l'estratto di AGENTS.md dopo la compattazione.`}},"agents%2Eentries%2E*%2Ecwd":{label:{"v1-19t4x9u-n":`Directory di lavoro dell'agente`},help:{"v1-mv43ak-6a":`Directory di lavoro per le esecuzioni di risposta di questo agente. Ha la precedenza su agents.defaults.cwd, ma non sulla cwd delle sessioni avviate; i file di inizializzazione e memoria rimangono nell'area di lavoro. Supporta ~ e percorsi relativi; una cwd distinta richiede un'esecuzione senza sandbox.`}},"agents%2Eentries%2E*%2EdecisionModel":{label:{"v1-73avf9-k":`Modello decisionale dell'agente`},help:{"v1-1mih8bf-3j":`Modello decisionale per singolo agente. Se non impostato, eredita agents.defaults.decisionModel; una stringa vuota disabilita le chiamate decisionali per questo agente.`}},"agents%2Eentries%2E*%2EembeddedAgent":{label:{"v1-5clak7-n":`OpenClaw integrato dell'agente`},help:{"v1-uoomza-4b":`Override facoltativi per agente di OpenClaw integrato. Usa questa opzione per attivare un comportamento di esecuzione GPT-5 più rigoroso per agenti specifici senza modificare l'impostazione predefinita globale.`}},"agents%2Eentries%2E*%2EembeddedAgent%2EexecutionContract":{label:{"v1-za8cop-16":`Contratto di esecuzione di OpenClaw integrato dell'agente`},help:{"v1-1d1jaoi-7k":`Override facoltativo per agente del contratto di esecuzione di OpenClaw integrato. Imposta "strict-agentic" per abilitare il monitoraggio strutturato del piano e il recupero dei turni non visibili per quell'agente nelle esecuzioni supportate della famiglia GPT-5 di OpenAI/OpenAI Codex, oppure "default" per ereditare il comportamento standard del runner.`}},"agents%2Eentries%2E*%2Eexperimental":{label:{"v1-lzii83-o":`Flag sperimentali dell'agente`},help:{"v1-1r06jov-2a":`Flag sperimentali per agente. I campi omessi ereditano i valori di agents.defaults.experimental.`}},"agents%2Eentries%2E*%2Eexperimental%2ElocalModelLean":{label:{"v1-9htxgz-r":`Modalità leggera del modello locale dell'agente`},help:{"v1-5o3tgx-58":`Impostazione di risoluzione dei problemi per singolo agente relativa alla modalità semplificata dei modelli locali. Attivala solo quando la limitazione degli strumenti facoltativi risolve un malfunzionamento accertato del modello, senza ridurre gli strumenti di tutti gli agenti.`}},"agents%2Eentries%2E*%2EfastModeDefault":{label:{"v1-9gqmky-n":`Modalità rapida predefinita dell’agente`},help:{"v1-1ujydjc-3o":`Valore predefinito facoltativo per la modalità rapida di ciascun agente ("auto", true o false). Si applica quando non è impostata alcuna sostituzione della modalità rapida a livello di messaggio o sessione.`}},"agents%2Eentries%2E*%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`Criterio di invio diretto dell’heartbeat`},help:{"v1-11gl9l0-41":`Sostituzione per singolo agente del criterio di invio diretto/tramite DM dell’heartbeat; usa "block" per gli agenti che devono inviare avvisi heartbeat solo a destinazioni diverse dai DM.`}},"agents%2Eentries%2E*%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`Timeout dell’heartbeat (secondi)`},help:{"v1-kdetv4-6s":`Tempo massimo in secondi consentito per ciascun agente per un turno heartbeat prima che venga interrotto. Lascia non impostato per ereditare il timeout heartbeat risultante dall’unione delle configurazioni, poi agents.defaults.timeoutSeconds se impostato, altrimenti l’intervallo heartbeat con un limite massimo di 600 secondi.`}},"agents%2Eentries%2E*%2Eidentity%2Eavatar":{label:{"v1-fs5x3k-f":`Avatar dell'identità`},help:{"v1-pzp9gr-1t":`Avatar dell’agente (percorso relativo all’area di lavoro, URL http(s) o URI data).`}},"agents%2Eentries%2E*%2EmodelPolicy":{label:{"v1-1locq7r-i":`Criterio dei modelli dell’agente`},help:{"v1-17d5je8-2r":`Criterio di sostituzione del modello per singolo agente. Un elenco esplicito di modelli consentiti sostituisce il criterio predefinito per questo agente.`}},"agents%2Eentries%2E*%2EmodelPolicy%2Eallow":{label:{"v1-xgq0i8-k":`Modelli consentiti per l’agente`},help:{"v1-v1ueke-5b":`Riferimenti ai modelli consentiti come sostituzioni per questo agente. Accetta alias, riferimenti completi "provider/model" e prefissi con carattere jolly finale come "provider/*" o "provider/namespace/*"; se vuoto, consente qualsiasi modello.`}},"agents%2Eentries%2E*%2Emodels":{label:{"v1-yawisy-l":`Sostituzioni dei modelli dell’agente`},help:{"v1-nld1vq-1v":`Override del catalogo dei modelli per agente, indicizzati tramite gli ID completi provider/modello.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime":{label:{"v1-1cv283-j":`Runtime del modello dell'agente`},help:{"v1-7b59y-3s":`Criterio di runtime facoltativo per ciascun modello di questo agente. Usalo per le eccezioni dei modelli specifiche dell'agente anziché impostare un runtime per l'intero agente.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-1j5q5p8-m":`ID runtime del modello dell'agente`},help:{"v1-1ckfc39-46":`ID del runtime del modello per agente: "openclaw", "auto", l'ID di un harness di plugin registrato come "codex" oppure un alias di backend CLI supportato come "claude-cli".`}},"agents%2Eentries%2E*%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Modalità codice`},help:{"v1-91zu7f-7m":`OpenClaw Code Mode per questo agente e per l'esatta combinazione provider/modello: Attivo ne forza l'attivazione, Disattivo la disabilita e Predefinito eredita l'impostazione di attivazione dell'agente, poi l'override condiviso del modello, poi tools.codeMode.enabled. Questo non modifica il runtime selezionato né la Code Mode nativa di Codex.`}},"agents%2Eentries%2E*%2EreasoningDefault":{label:{"v1-drq4cj-n":`Visibilità predefinita del ragionamento dell'agente`},help:{"v1-13ly0xf-3m":`Visibilità predefinita facoltativa del ragionamento per agente (on|off|stream). Si applica quando non è impostato alcun override del ragionamento a livello di messaggio o sessione.`}},"agents%2Eentries%2E*%2Eruntime":{label:{"v1-10xv3pm-d":`Runtime dell'agente`},help:{"v1-avjgkf-3l":`Descrittore di runtime facoltativo per questo agente. Usa embedded per l'esecuzione predefinita di OpenClaw oppure acp per le impostazioni predefinite di un harness ACP esterno.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp":{label:{"v1-81375y-h":`Runtime ACP dell'agente`},help:{"v1-91zvdk-3i":`Impostazioni predefinite del runtime ACP per questo agente quando runtime.type=acp. Le impostazioni ACP specifiche a livello di associazione continuano ad avere la precedenza per ogni conversazione.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Eagent":{label:{"v1-ildwsn-n":`Agente dell'harness ACP per l'agente`},help:{"v1-1pm98vp-37":`ID facoltativo dell'agente dell'harness ACP da usare per questo agente OpenClaw (ad esempio codex, claude, cursor, gemini, openclaw).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ebackend":{label:{"v1-1vygqw2-h":`Backend ACP dell'agente`},help:{"v1-1u3cdsg-2n":`Impostazione facoltativa del backend ACP per le sessioni ACP di questo agente (in assenza, viene usato il valore globale di acp.backend).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ecwd":{label:{"v1-1ts2vd2-r":`Directory di lavoro ACP dell'agente`},help:{"v1-d9p9rf-1t":`Directory di lavoro predefinita facoltativa per le sessioni ACP di questo agente.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Emode":{label:{"v1-1zgumd-e":`Modalità ACP dell'agente`},help:{"v1-yatuk4-21":`Modalità di sessione ACP predefinita facoltativa per questo agente (persistent o oneshot).`}},"agents%2Eentries%2E*%2Eruntime%2Etype":{label:{"v1-8wr11a-i":`Tipo di runtime dell'agente`},help:{"v1-139fbk6-2r":`Tipo di runtime per questo agente: "embedded" (runtime predefinito di OpenClaw) o "acp" (impostazioni predefinite dell'harness ACP).`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-k202bg-12":`Intervallo di origine CDP del browser nella sandbox dell'agente`},help:{"v1-1q1qyso-1d":`Impostazione specifica per agente dell'elenco dei CIDR di origine consentiti per CDP.`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-7jh9lr-t":`Rete del browser nella sandbox dell'agente`},help:{"v1-13bdfww-4c":`Override per agente della rete Docker del browser nella sandbox. Usa una rete bridge; "none" non è supportato perché il controllo del browser richiede porte CDP pubblicate.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-n1z0dm-1f":`Consenti l'accesso al namespace del container Docker nella sandbox dell'agente`},help:{"v1-1xtnseb-2i":`Override PERICOLOSO per agente per l'accesso ai namespace dei container nella modalità di rete Docker della sandbox.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2Egpus":{label:{"v1-nbwnmy-p":`GPU Docker nella sandbox dell'agente`},help:{"v1-1kek1n2-1t":`Override per agente del passthrough GPU Docker per i container della sandbox.`}},"agents%2Eentries%2E*%2Eskills":{label:{"v1-nfmhzv-i":`Filtro delle Skills dell'agente`},help:{"v1-igchue-6v":`Elenco facoltativo delle Skills consentite per questo agente. Se omesso, l'agente eredita agents.defaults.skills, se impostato; altrimenti le Skills restano senza restrizioni. Imposta [] per non consentire alcuna Skills. Un elenco esplicito sostituisce completamente le impostazioni predefinite ereditate anziché unirsi a esse.`}},"agents%2Eentries%2E*%2EskillsLimits":{label:{"v1-dghtbk-j":`Limiti delle Skills dell'agente`},help:{"v1-1sv10v9-4y":`Override facoltativi per agente dei budget del sottosistema delle Skills. Usa questa opzione quando un agente necessita di un budget diverso per il prompt delle Skills senza introdurre un secondo percorso generico per i limiti di contesto.`}},"agents%2Eentries%2E*%2EskillsLimits%2EmaxSkillsPromptChars":{label:{"v1-mg9zup-t":`Numero massimo di caratteri del prompt delle Skills dell'agente`},help:{"v1-dys63y-52":`Impostazione specifica per agente del limite di caratteri del prompt delle abilità. Estende il percorso esistente skills.limits.maxSkillsPromptChars anziché gestire lo stesso limite tramite contextLimits.`}},"agents%2Eentries%2E*%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Modalità di delega ai sottoagenti`},help:{"v1-1rkgh6p-4s":`Impostazione specifica per agente del livello di propensione alla delega ai sottoagenti. Omettere per usare "prefer" nella sessione principale di questo agente e "suggest" altrove; un valore esplicito "prefer" o "suggest" ha sempre la precedenza.`}},"agents%2Eentries%2E*%2EthinkingDefault":{label:{"v1-ymctpn-m":`Livello di ragionamento predefinito dell'agente`},help:{"v1-173q7vy-43":`Livello di ragionamento predefinito facoltativo per agente. Sostituisce agents.defaults.thinkingDefault per questo agente quando non è impostato un valore specifico per messaggio o sessione.`}},"agents%2Eentries%2E*%2Etools%2EalsoAllow":{label:{"v1-1kf1wpw-u":`Aggiunte all'elenco degli strumenti consentiti dell'agente`},help:{"v1-1550ui9-46":`Elenco aggiuntivo di strumenti consentiti per agente, oltre a quelli previsti dai criteri globali e del profilo. Mantenerlo limitato per evitare ampliamenti accidentali dei privilegi degli agenti specializzati.`}},"agents%2Eentries%2E*%2Etools%2EbyProvider":{label:{"v1-w3qxm8-t":`Criteri degli strumenti dell'agente per fornitore`},help:{"v1-mthxv9-4t":`Impostazioni specifiche per agente e fornitore che sostituiscono i criteri degli strumenti per controllare le funzionalità a livello di canale. Usare quando un singolo agente richiede restrizioni più severe per un fornitore rispetto agli altri.`}},"agents%2Eentries%2E*%2Etools%2EcodeMode":{label:{"v1-1l1vsai-f":`Modalità codice dell'agente`},help:{"v1-118t8u5-65":`Opzioni di Code Mode per ciascun agente. Un valore esplicito di enabled prevale sui valori predefiniti di attivazione del modello condiviso e globali; un override di codeMode del modello specifico dell'agente ha la precedenza. Le altre opzioni vengono unite a tools.codeMode, prevalendo sui valori esistenti senza modificare l'attivazione.`}},"agents%2Eentries%2E*%2Etools%2Eexec%2EtimeoutSeconds":{label:{"v1-leof0k-s":`Timeout di esecuzione dell'agente (secondi)`}},"agents%2Eentries%2E*%2Etools%2Egithub":{label:{"v1-1nky9u1-y":`Override dell'identità GitHub CLI dell'agente`},help:{"v1-mjwdh4-38":`Override completo dell'identità gestita di GitHub CLI e dell'autore Git per questo agente. Ometterlo per ereditare l'identità di sistema.`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-1i4m01d-m":`Email dell'autore Git dell'agente`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-1j0pl20-l":`Nome dell'autore Git dell'agente`}},"agents%2Eentries%2E*%2Etools%2Egithub%2Ekind":{label:{"v1-14pqhd4-s":`Tipo di credenziale GitHub dell'agente`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EprofileId":{label:{"v1-1fmzzvk-s":`Versione del profilo GitHub dell'agente`}},"agents%2Eentries%2E*%2Etools%2Emessage%2Eactions%2Eallow":{label:{"v1-1cpyq5g-u":`Elenco delle azioni consentite sui messaggi per l'agente`},help:{"v1-1g5gov3-67":`Elenco delle azioni consentite sui messaggi per ciascun agente nello strumento message. Per gli agenti pubblici in sandbox, impostare un elenco minimo come ["send"], in modo che le azioni di lettura, modifica, eliminazione, reazione e le altre azioni sui messaggi specifiche del provider rimangano nascoste e bloccate.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-1js3r9e-1c":`Messaggistica tra contesti dell'agente (tra provider)`},help:{"v1-pehesn-49":`Impostazione specifica per agente per l'invio tra provider diversi. Eredita l'impostazione globale (valore predefinito: true). Imposta false per bloccare l'invio di messaggi tra provider diversi per questo agente.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-z29ji-19":`Messaggistica dell'agente tra contesti (stesso provider)`},help:{"v1-s9u09h-4t":`Controllo per agente sull'invio di messaggi ad altre conversazioni sullo stesso provider. Imposta sia questa opzione sia allowAcrossProviders su false per limitare gli agenti pubblici alla sola conversazione corrente.`}},"agents%2Eentries%2E*%2Etools%2Eprofile":{label:{"v1-kybcdd-i":`Profilo degli strumenti dell'agente`},help:{"v1-1du76ix-57":`Sostituzione per singolo agente della selezione del profilo degli strumenti, quando un agente necessita di un insieme diverso di funzionalità di base. Usala con moderazione affinché le differenze tra i criteri degli agenti restino intenzionali e verificabili.`}},"agents%2Eentries%2E*%2Etools%2Eswarm":{label:{"v1-54zhti-b":`Sciame di agenti`},help:{"v1-420ljs-2c":`Sostituzione della configurazione dello sciame per singolo agente. I valori vengono uniti alla configurazione tools.swarm di primo livello e hanno la precedenza.`}},"agents%2Eentries%2E*%2EtypingMode":{label:{"v1-1nl61h4-h":`Modalità di digitazione dell'agente`},help:{"v1-oxir52-2e":`Sostituisce il criterio predefinito di avvio della digitazione per un agente senza modificare gli altri.`}},"agents%2Eentries%2E*%2EutilityModel":{label:{"v1-1k6g1v3-j":`Modello ausiliario dell'agente`},help:{"v1-1v9oskz-2z":`Sostituzione facoltativa del modello ausiliario per singolo agente, destinato a brevi attività interne. Sostituisce agents.defaults.utilityModel.`}},"agents%2Eownership":{label:{"v1-uuzaon-q":`Generazione della titolarità degli agenti`},help:{"v1-m2hp61-8g":`Indicatore persistente della generazione della titolarità in un sistema multiagente. "explicit" significa che i canali ambientali, gli heartbeat, le consultazioni dell'agente di sistema, Talk, cron e le operazioni CLI dirette devono individuare un titolare specifico per l'interfaccia oppure bloccarsi per sicurezza. OpenClaw imposta questo indicatore automaticamente durante la creazione o la migrazione di una flotta; omettilo se è presente un solo agente.`}},approvals:{label:{"v1-1m405m7-9":`Approvazioni`},help:{"v1-4y3in-5w":`Controlli di instradamento delle approvazioni per inoltrare le richieste di approvazione di exec e dei plugin a destinazioni di chat esterne alla sessione di origine. Mantienili disabilitati, a meno che gli operatori non abbiano bisogno di visibilità esplicita sulle approvazioni tramite canali separati.`}},"approvals%2Eexec":{label:{"v1-hhphou-o":`Inoltro delle approvazioni di exec`},help:{"v1-1r2mozk-5v":`Raggruppa le impostazioni di inoltro delle approvazioni di exec, tra cui abilitazione, modalità di instradamento, filtri e destinazioni esplicite. Configura qui quando le richieste di approvazione devono raggiungere i canali operativi anziché solo il thread di origine.`}},"approvals%2Eexec%2EagentFilter":{label:{"v1-1gg1zh3-l":`Filtro agenti per le approvazioni`},help:{"v1-xbuhd3-5i":'Elenco facoltativo di ID degli agenti per i quali è consentito inoltrare le approvazioni, ad esempio `["primary", "ops-agent"]`. Usalo per limitare la portata dell\'inoltro ed evitare di inviare ai canali notifiche relative ad agenti non pertinenti.'}},"approvals%2Eexec%2Eenabled":{label:{"v1-oukdkb-m":`Inoltra le approvazioni di exec`},help:{"v1-1t0whe8-5s":`Abilita l'inoltro delle richieste di approvazione di exec alle destinazioni di consegna configurate (valore predefinito: false). Mantienilo disabilitato nelle configurazioni a basso rischio e abilitalo solo quando le persone incaricate delle approvazioni hanno bisogno di richieste visibili nei canali.`}},"approvals%2Eexec%2Emode":{label:{"v1-733gc4-o":`Modalità di inoltro delle approvazioni`},help:{"v1-1dedfo4-69":`Controlla dove vengono inviate le richieste di approvazione: "session" usa la chat di origine, "targets" usa le destinazioni configurate e "both" invia a entrambe. Usa "session" come impostazione di base ed estendi l'inoltro solo quando il flusso di lavoro operativo richiede ridondanza.`}},"approvals%2Eexec%2EsessionFilter":{label:{"v1-1lqr9y4-n":`Filtro sessioni per le approvazioni`},help:{"v1-smeg8e-5u":'Filtri facoltativi per le chiavi di sessione, confrontati come sottostringhe o pattern di tipo regex, ad esempio `["discord:", "^agent:ops:"]`. Usa pattern restrittivi affinché solo i contesti di approvazione previsti vengano inoltrati alle destinazioni condivise.'}},"approvals%2Eexec%2Etargets":{label:{"v1-uht69z-r":`Destinatari dell'inoltro delle approvazioni`},help:{"v1-17ah848-5u":`Destinatari espliciti utilizzati quando la modalità di inoltro include targets, ciascuno con dettagli sul canale e sulla destinazione. Limita gli elenchi dei destinatari secondo il principio del privilegio minimo e verifica ogni destinazione prima di abilitare l'inoltro su larga scala.`}},"approvals%2Eexec%2Etargets%5B%5D%2EaccountId":{label:{"v1-1pizj1x-q":`ID account del destinatario delle approvazioni`},help:{"v1-16zopng-5e":`Selettore facoltativo dell'account per configurazioni di canali con più account, quando le approvazioni devono essere instradate attraverso il contesto di un account specifico. Usalo solo quando il canale di destinazione ha più identità configurate.`}},"approvals%2Eexec%2Etargets%5B%5D%2Echannel":{label:{"v1-14ol0m8-n":`Canale di destinazione delle approvazioni`},help:{"v1-ji1igl-59":`ID del canale o del provider utilizzato per la consegna delle approvazioni inoltrate, come discord, slack o l'ID di un canale plugin. Usa solo ID di canale validi per evitare che la consegna delle approvazioni fallisca senza segnalazioni a causa di percorsi sconosciuti.`}},"approvals%2Eexec%2Etargets%5B%5D%2EthreadId":{label:{"v1-18ez6dm-p":`ID thread di destinazione delle approvazioni`},help:{"v1-1axynw7-59":`Thread o argomento di destinazione facoltativo per i canali che supportano la consegna delle approvazioni inoltrate nei thread. Usalo per mantenere il traffico delle approvazioni nei thread operativi anziché nei canali principali.`}},"approvals%2Eexec%2Etargets%5B%5D%2Eto":{label:{"v1-19bm483-r":`Destinazione delle approvazioni`},help:{"v1-1ijng7e-5n":`Identificatore della destinazione all'interno del canale di destinazione (ID del canale, ID dell'utente o messaggio iniziale del thread, a seconda del provider). Verifica la semantica per ciascun provider, poiché il formato della destinazione varia tra le integrazioni dei canali.`}},"approvals%2Eplugin":{label:{"v1-swf7m4-q":`Inoltro delle approvazioni dei plugin`},help:{"v1-1m6pzxv-6b":`Raggruppa le impostazioni di inoltro delle approvazioni dei plugin, tra cui abilitazione, modalità di instradamento, filtri e destinazioni esplicite. È indipendente dall'inoltro delle approvazioni di exec. Configura queste impostazioni quando le richieste di approvazione dei plugin devono raggiungere i canali operativi.`}},"approvals%2Eplugin%2EagentFilter":{label:{"v1-12csxm6-s":`Filtro degli agenti per le approvazioni dei plugin`},help:{"v1-jb1bra-4b":`Elenco facoltativo degli ID degli agenti per i quali è consentito inoltrare le approvazioni dei plugin, ad esempio \`["primary", "ops-agent"]\`. Usalo per limitare l'ambito dell'inoltro.`}},"approvals%2Eplugin%2Eenabled":{label:{"v1-q9f62x-o":`Inoltra le approvazioni dei plugin`},help:{"v1-1ntctaf-3v":`Abilita l'inoltro delle richieste di approvazione dei plugin alle destinazioni di recapito configurate (valore predefinito: false). È indipendente da approvals.exec.enabled.`}},"approvals%2Eplugin%2Emode":{label:{"v1-1mgp0vb-v":`Modalità di inoltro delle approvazioni dei plugin`},help:{"v1-1h62vy4-3z":`Controlla dove vengono inviate le richieste di approvazione dei plugin: "session" usa la chat di origine, "targets" usa le destinazioni configurate e "both" invia a entrambe.`}},"approvals%2Eplugin%2EsessionFilter":{label:{"v1-15vplo5-u":`Filtro delle sessioni per le approvazioni dei plugin`},help:{"v1-1eppxmt-57":'Filtri facoltativi sulle chiavi di sessione, con corrispondenza per sottostringa o tramite pattern di espressioni regolari, ad esempio `["discord:", "^agent:ops:"]`. Usa pattern specifici per inoltrare solo i contesti di approvazione desiderati.'}},"approvals%2Eplugin%2Etargets":{label:{"v1-1snpvju-y":`Destinatari dell'inoltro delle approvazioni dei plugin`},help:{"v1-o92qze-3k":`Destinatari espliciti utilizzati quando la modalità di inoltro delle approvazioni dei plugin include destinatari, ciascuno con dettagli sul canale e sulla destinazione.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EaccountId":{label:{"v1-oxqv86-x":`ID account del destinatario delle approvazioni dei plugin`},help:{"v1-1wf3lqn-3j":`Selettore di account facoltativo per configurazioni di canali con più account, quando le approvazioni dei plugin devono essere instradate tramite il contesto di un account specifico.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Echannel":{label:{"v1-1jz34xt-u":`Canale di destinazione delle approvazioni dei plugin`},help:{"v1-1mzhzi9-34":`ID del canale o del provider utilizzato per la consegna delle approvazioni dei plugin inoltrate, ad esempio discord, slack o l'ID di un canale di plugin.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EthreadId":{label:{"v1-1beipnf-w":`ID del thread di destinazione delle approvazioni dei plugin`},help:{"v1-1scaw9c-2v":`Thread o argomento di destinazione facoltativo per i canali che supportano la consegna nei thread delle approvazioni dei plugin inoltrate.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Eto":{label:{"v1-1df4m22-y":`Destinazione delle approvazioni dei plugin`},help:{"v1-sh5te1-31":`Identificatore della destinazione all'interno del canale di destinazione (ID del canale, ID utente o messaggio iniziale del thread, a seconda del provider).`}},attachments:{label:{"v1-8925gh-b":`Allegati`},help:{"v1-1xvgkss-40":`Comportamento di conservazione di primo livello condiviso tra i provider e gli strumenti che memorizzano contenuti multimediali. Usa ttlHours quando i contenuti multimediali temporanei generici devono essere eliminati entro un limite di tempo.`}},"attachments%2EttlHours":{label:{"v1-m9sx0s-w":`TTL di conservazione degli allegati (ore)`},help:{"v1-1g90day-9e":`Periodo di conservazione facoltativo, in ore, per i file multimediali salvati e gestiti dalla pulizia generale basata su mtime. Lascia non impostato per disabilitare questa pulizia oppure imposta valori come 24 (1 giorno) o 168 (7 giorni) per rimuovere periodicamente i file multimediali temporanei meno recenti. I file multimediali in uscita gestiti (allegati generati in chat) sono esclusi e seguono criteri di conservazione propri che tengono conto di SQLite e delle trascrizioni.`}},audio:{label:{"v1-11wczsp-5":`Audio`}},auth:{label:{"v1-5xz433-4":`Autenticazione`},help:{"v1-1eu3aud-5c":`Sezione radice dei profili di autenticazione, usata per le credenziali dei provider con più profili e per l'ordine di failover basato sui tempi di attesa. Mantieni i profili essenziali ed espliciti affinché il comportamento del failover automatico resti verificabile.`}},"auth%2Eorder":{label:{"v1-gadtii-i":`Ordine dei profili di autenticazione`},help:{"v1-1x6kknp-1w":`ID dei profili di autenticazione ordinati per provider (usati per il failover automatico).`}},"auth%2Eprofiles":{label:{"v1-nbj2kv-d":`Profili di autenticazione`},help:{"v1-kzoqcn-1j":`Profili di autenticazione con nome (provider + modalità + email facoltativa).`}},bindings:{label:{"v1-1hcih9f-8":`Associazioni`},help:{"v1-y7hrzb-4i":`Regole di associazione di primo livello per l'instradamento e l'assegnazione persistente delle conversazioni ACP. Usa type=route per l'instradamento normale e type=acp per le associazioni persistenti all'harness ACP.`}},"bindings%5B%5D%2Eacp":{label:{"v1-1c1of5r-l":`Impostazioni sostitutive dell'associazione ACP`},help:{"v1-1t4lisi-44":`Impostazioni ACP sostitutive facoltative per ogni associazione con bindings[].type=acp. Questo livello sostituisce i valori predefiniti di agents.entries.*.runtime.acp per la conversazione corrispondente.`}},"bindings%5B%5D%2Eacp%2Ebackend":{label:{"v1-1qfk8bu-j":`Backend dell'associazione ACP`},help:{"v1-rsrbkp-2x":`Backend ACP sostitutivo per questa associazione (in assenza, viene usato il backend ACP del runtime dell'agente, quindi il valore globale acp.backend).`}},"bindings%5B%5D%2Eacp%2Ecwd":{label:{"v1-1w2wp4u-t":`Directory di lavoro dell'associazione ACP`},help:{"v1-ngpkj0-1y":`Directory di lavoro alternativa per le sessioni ACP create da questa associazione.`}},"bindings%5B%5D%2Eacp%2Elabel":{label:{"v1-mc3w70-h":`Etichetta dell'associazione ACP`},help:{"v1-azce82-23":`Etichetta di facile lettura per lo stato e la diagnostica ACP in questa conversazione associata.`}},"bindings%5B%5D%2Eacp%2Emode":{label:{"v1-1mko9zx-g":`Modalità dell'associazione ACP`},help:{"v1-cgq8xv-1v":`Modalità della sessione ACP alternativa per questa associazione (persistent o oneshot).`}},"bindings%5B%5D%2EagentId":{label:{"v1-1j1g5rg-g":`ID agente dell'associazione`},help:{"v1-17ra0cl-4m":`ID dell'agente di destinazione che riceve il traffico quando la regola di corrispondenza dell'associazione è soddisfatta. Usa solo ID agente configurati e validi per evitare errori di instradamento in fase di esecuzione.`}},"bindings%5B%5D%2Ematch":{label:{"v1-13eg2e3-i":`Regola di corrispondenza dell'associazione`},help:{"v1-sc1w2e-51":`Oggetto della regola di corrispondenza che determina quando si applica un'associazione, con il canale e gli eventuali vincoli relativi ad account e interlocutore. Mantieni le regole specifiche per evitare che un agente subentri accidentalmente in altri contesti.`}},"bindings%5B%5D%2Ematch%2EaccountId":{label:{"v1-1csp6k6-i":`ID account dell'associazione`},help:{"v1-1d209g7-56":`Selettore account facoltativo per configurazioni di canale con più account, affinché l'associazione si applichi a una sola identità. Usalo quando l'instradamento deve essere limitato a un account; altrimenti, lascialo non impostato.`}},"bindings%5B%5D%2Ematch%2Echannel":{label:{"v1-mucsyp-f":`Canale dell'associazione`},help:{"v1-d22m5-54":"Identificatore del canale o del provider a cui si applica questa associazione, ad esempio `telegram`, `discord` o l'ID di un canale di un plugin. Usa esattamente la chiave del canale configurata affinché la valutazione dell'associazione funzioni in modo affidabile."}},"bindings%5B%5D%2Ematch%2EguildId":{label:{"v1-1hgwzxi-g":`ID server dell'associazione`},help:{"v1-jzzfj1-4x":`Vincolo facoltativo sull'ID della community/server in stile Discord per la valutazione delle associazioni nelle distribuzioni con più server. Usalo quando gli stessi identificatori dei peer possono comparire in community diverse.`}},"bindings%5B%5D%2Ematch%2Epeer":{label:{"v1-1x3w5cz-i":`Corrispondenza del peer per l'associazione`},help:{"v1-gcjxff-4i":`Criterio facoltativo di corrispondenza del peer per conversazioni specifiche, che include il tipo e l'ID del peer. Usalo quando è necessario assegnare stabilmente a un agente una sola destinazione: conversazione diretta, gruppo o canale.`}},"bindings%5B%5D%2Ematch%2Epeer%2Eid":{label:{"v1-181lr2n-f":`ID del peer per l'associazione`},help:{"v1-86fbh7-4b":`Identificatore della conversazione usato per la corrispondenza del peer, ad esempio un ID di chat, canale o gruppo del provider. Riportalo esattamente per evitare mancate corrispondenze non segnalate.`}},"bindings%5B%5D%2Ematch%2Epeer%2Ekind":{label:{"v1-wii7p0-h":`Tipo di peer per l'associazione`},help:{"v1-uufscp-4x":`Tipo di conversazione del peer: "direct", "group", "channel" oppure il valore legacy "dm" (alias deprecato di direct). Preferisci "direct" per le nuove configurazioni e mantieni kind coerente con la semantica del canale.`}},"bindings%5B%5D%2Ematch%2Eroles":{label:{"v1-1ishhl3-d":`Ruoli per l'associazione`},help:{"v1-6s891m-4k":`Elenco facoltativo di filtri basati sui ruoli, usato dai provider che associano ruoli al contesto della chat. Usalo per instradare il traffico dei ruoli privilegiati o operativi verso agenti specializzati.`}},"bindings%5B%5D%2Ematch%2EteamId":{label:{"v1-1yh6sjs-f":`ID del team per l'associazione`},help:{"v1-hh9ps2-48":`Vincolo facoltativo sull'ID del team o dell'area di lavoro, usato dai provider che organizzano le chat per team. Aggiungilo quando è necessario limitare le associazioni al contesto di una sola area di lavoro.`}},"bindings%5B%5D%2Esession":{label:{"v1-1weokpm-f":`Sessione dell'associazione`},help:{"v1-x325l2-4v":`Sostituzioni facoltative delle impostazioni di sessione della rotta per le conversazioni corrispondenti a questa associazione. Usale quando una rotta specifica deve mantenere lo stesso agente ma isolare diversamente la continuità della sessione.`}},"bindings%5B%5D%2Esession%2EdmScope":{label:{"v1-1jcplmp-o":`Ambito dei messaggi diretti della sessione dell'associazione`},help:{"v1-10sg3xw-4s":`Sostituzione facoltativa dell'ambito della sessione dei messaggi diretti per questa associazione di rotta. Ad esempio, mantieni l'impostazione globale session.dmScope="main" usando al contempo "per-account-channel-peer" per interlocutori diretti selezionati.`}},"bindings%5B%5D%2Esession%2EgroupScope":{label:{"v1-1dkb0a1-r":`Ambito dei gruppi della sessione dell'associazione`},help:{"v1-1ys2u7k-6n":`Sostituzione facoltativa dell'ambito della sessione di gruppi/canali per questa associazione di rotta. "per-group" mantiene separate le stanze corrispondenti e le fa monitorare in background dalla sessione principale dell'agente, indipendentemente da dmScope; "main" ne unisce il contesto alla sessione principale e non richiede monitoraggio.`}},"bindings%5B%5D%2Etype":{label:{"v1-1l3bpjq-c":`Tipo di associazione`},help:{"v1-172mhtk-3o":`Tipo di associazione. Usa "route" (oppure ometti il valore per le voci di rotta legacy) per l'instradamento normale e "acp" per le associazioni persistenti di conversazioni ACP.`}},broadcast:{label:{"v1-awqjh0-j":`Thread di gruppo degli agenti`},help:{"v1-1tz72sr-6b":`Usa i thread di gruppo degli agenti per eseguire più agenti configurati su un'unica conversazione in ingresso, ciascuno nella propria sessione. Le voci qualificate per canale supportano cicli di interazione successivi limitati; gli array di peer WhatsApp legacy mantengono il comportamento a passaggio singolo.`}},"broadcast%2E*":{label:{"v1-k5obp6-10":`Partecipanti e opzioni del gruppo di agenti`},help:{"v1-1b63zmt-7d":`Usa un ID peer qualificato per canale (ad esempio "telegram:-100123") per configurare un array di ID agente o un oggetto a struttura rigida con agents, mentionGating, maxRounds e maxTurns. Le voci qualificate hanno la precedenza sulle chiavi peer WhatsApp legacy e consentono al massimo 16 agenti.`}},"broadcast%2E*%2Eagents":{label:{"v1-od29y1-o":`Partecipanti del gruppo di agenti`},help:{"v1-g5o0ky-43":`ID degli agenti partecipanti da agents.entries (massimo: 16). Ogni partecipante usa una propria sessione per questo canale, account, conversazione e thread.`}},"broadcast%2E*%2EmaxRounds":{label:{"v1-1l8x0fc-q":`Numero massimo di round del gruppo di agenti`},help:{"v1-i6v4jc-5a":`Numero massimo di round per messaggio in arrivo, incluso il round iniziale (intero: 1–4, valore predefinito: 1). I round successivi condividono un insieme limitato di risposte degli altri partecipanti, con indicazione dell'autore, e si interrompono quando tutti i partecipanti passano.`}},"broadcast%2E*%2EmaxTurns":{label:{"v1-aobwmz-p":`Numero massimo di turni del gruppo di agenti`},help:{"v1-1kiv8dy-72":`Numero massimo di turni dei partecipanti per messaggio in arrivo, considerando tutti i round (intero: 1–32, valore predefinito: agents.length). Gli slot vengono riservati prima dell'invio in parallelo; questo limita i turni degli agenti, non i singoli frammenti di messaggio o gli invii degli strumenti. I budget non vengono ripristinati dopo un riavvio.`}},"broadcast%2E*%2EmentionGating":{label:{"v1-1ykkdid-t":`Selezione tramite menzione nel gruppo di agenti`},help:{"v1-uay9zu-5u":`Seleziona solo i partecipanti esplicitamente menzionati con @ se vengono trovate corrispondenze; altrimenti esegue tutti i partecipanti (valore predefinito: true). I semplici nomi o le emoji non selezionano i partecipanti. Gli elenchi dei canali consentiti e le regole di ammissione continuano ad applicarsi.`}},"broadcast%2Estrategy":{label:{"v1-nm62ea-k":`Strategia del gruppo di agenti`},help:{"v1-p4k9hu-4q":`Ordine di esecuzione dei partecipanti: "parallel" (valore predefinito) esegue gli agenti contemporaneamente, mentre "sequential" li esegue nell'ordine configurato. Ogni round termina prima che inizi il successivo.`}},browser:{label:{"v1-13dzmen-7":`Browser`},help:{"v1-5b74wi-5l":`Controlli di esecuzione del browser per la connessione CDP locale o remota, l'instradamento dei profili e il comportamento di screenshot e snapshot. Mantieni i valori predefiniti a meno che il flusso di lavoro di automazione non richieda impostazioni di trasporto del browser personalizzate.`}},"browser%2EallowSystemProfileImport":{label:{"v1-17h3693-r":`Consenti importazione del profilo di sistema`},help:{"v1-1lsvlxw-5w":`Consente agli host macOS di importare cookie da un profilo di sistema locale di un browser della famiglia Chrome in un profilo browser gestito da OpenClaw. Disabilita questa opzione per impedire l'importazione dei cookie del profilo browser e la relativa richiesta di consenso per il Portachiavi macOS.`}},"browser%2EattachOnly":{label:{"v1-1pt3uds-o":`Modalità di sola connessione del browser`},help:{"v1-xaw7xm-4s":`Limita il browser alla sola connessione, senza avviare processi browser locali. Usa questa opzione quando tutte le sessioni del browser sono gestite esternamente da un provider CDP remoto.`}},"browser%2EcdpUrl":{label:{"v1-oc982r-f":`URL CDP del browser`},help:{"v1-2n72jb-65":`URL dell'endpoint CDP/DevTools usato per connettersi a un'istanza del browser gestita esternamente. Usalo per host browser centralizzati, tunnel o connessioni a sessioni esistenti e limita l'accesso all'URL a percorsi di rete attendibili.`}},"browser%2EdefaultProfile":{label:{"v1-gx1r6n-n":`Profilo predefinito del browser`},help:{"v1-a6xo96-52":`Nome del profilo browser predefinito selezionato quando i chiamanti non scelgono esplicitamente un profilo. Usa come predefinito un profilo stabile con privilegi limitati per ridurre l'uso accidentale dello stato tra contesti diversi.`}},"browser%2Eenabled":{label:{"v1-ur2izq-f":`Browser abilitato`},help:{"v1-19qr4oj-56":`Abilita l'integrazione delle funzionalità del browser nel Gateway, consentendo l'esecuzione degli strumenti del browser e dei flussi di lavoro basati su CDP. Disabilita questa opzione quando l'automazione del browser non è necessaria, per ridurre la superficie esposta e le operazioni all'avvio.`}},"browser%2EevaluateEnabled":{label:{"v1-17r8d2b-o":`Valutazione nel browser abilitata`},help:{"v1-1oa79mq-59":`Abilita le funzioni ausiliarie di valutazione lato browser per eseguire script a runtime, dove supportato. Mantieni questa opzione disabilitata, a meno che i tuoi flussi di lavoro non richiedano funzionalità di valutazione oltre alle istantanee e alla navigazione.`}},"browser%2EexecutablePath":{label:{"v1-nxumpk-n":`Percorso dell'eseguibile del browser`},help:{"v1-1plb4ki-6i":`Percorso esplicito dell'eseguibile del browser quando il rilevamento automatico non è sufficiente per l'ambiente host. Usa un percorso assoluto stabile oppure un percorso che inizi con ~ per la directory home del sistema operativo, in modo che il comportamento all'avvio rimanga deterministico tra i riavvii.`}},"browser%2EextensionRelay":{label:{"v1-1fifm3z-n":`Relay dell'estensione del browser`},help:{"v1-6ywlwr-4e":`Impostazioni di compatibilità per l'autenticazione del relay dell'estensione Chrome. Mantieni il periodo di compatibilità con i metodi precedenti solo finché le estensioni associate meno recenti o i client CDP esterni ne hanno ancora bisogno.`}},"browser%2EextensionRelay%2EallowLegacyAuth":{label:{"v1-2qob0y-v":`Consenti l'autenticazione legacy del relay del browser`},help:{"v1-pj2e90-63":`Accetta temporaneamente i metodi di autenticazione legacy del relay: Bearer, Basic e tramite token nel sottoprotocollo. Valore predefinito: true per un periodo di migrazione. Imposta false quando tutte le estensioni e tutti i client CDP esterni usano Browser Relay Authentication v2.`}},"browser%2Eheadless":{label:{"v1-1ksb99t-l":`Modalità headless del browser`},help:{"v1-1rswq8j-5a":`Forza l'avvio del browser in modalità headless quando il programma di avvio locale avvia istanze del browser. Mantieni la modalità headless abilitata negli ambienti server e disabilitala solo quando il debug richiede un'interfaccia visibile.`}},"browser%2EnoSandbox":{label:{"v1-nx4cbr-n":`Modalità browser senza sandbox`},help:{"v1-slntux-4w":`Disabilita i flag di isolamento sandbox di Chromium negli ambienti in cui la sandbox non funziona durante l'esecuzione. Mantieni questa opzione disattivata quando possibile, poiché riduce le protezioni di isolamento dei processi.`}},"browser%2Eprofiles":{label:{"v1-fih34f-g":`Profili del browser`},help:{"v1-1x8lf05-51":`Mappa delle connessioni dei profili browser denominati, usata per l'instradamento esplicito verso porte o URL CDP con metadati facoltativi. Mantieni coerenti i nomi dei profili ed evita definizioni di endpoint sovrapposte.`}},"browser%2Eprofiles%2E*%2EattachOnly":{label:{"v1-32uv4v-w":`Modalità di sola connessione del profilo browser`},help:{"v1-2b5zs0-5a":`Impostazione di sola connessione specifica per profilo che evita l'avvio del browser locale e si connette soltanto a un endpoint CDP esistente. Utile quando un profilo è gestito esternamente, mentre gli altri vengono avviati localmente.`}},"browser%2Eprofiles%2E*%2EcdpPort":{label:{"v1-1avgh1q-o":`Porta CDP del profilo browser`},help:{"v1-gx1yiq-49":`Porta CDP locale specifica per profilo, usata per connettersi alle istanze del browser tramite porta anziché URL. Usa porte univoche per ciascun profilo per evitare conflitti di connessione.`}},"browser%2Eprofiles%2E*%2EcdpUrl":{label:{"v1-elwsl2-n":`URL CDP del profilo browser`},help:{"v1-x491r0-64":`URL dell'endpoint CDP/DevTools specifico per profilo, usato per l'instradamento esplicito del browser in base al nome del profilo. Usalo per host CDP remoti, tunnel o profili con sessioni esistenti che devono connettersi tramite un endpoint Chrome DevTools in esecuzione.`}},"browser%2Eprofiles%2E*%2Edriver":{label:{"v1-1j1f8vg-m":`Driver del profilo browser`},help:{"v1-17byyx6-5r":`Modalità del driver del browser per ciascun profilo. Usa "openclaw" (o il precedente "clawd") per i profili basati su CDP, "existing-session" per il collegamento tramite Chrome DevTools MCP oppure "extension" per il relay autenticato dell'estensione Chrome.`}},"browser%2Eprofiles%2E*%2EexecutablePath":{label:{"v1-154onzh-v":`Percorso dell'eseguibile del profilo browser`},help:{"v1-29azyv-4w":`Percorso dell'eseguibile del browser per ciascun profilo browser gestito avviato localmente. Sovrascrive browser.executablePath e accetta percorsi che iniziano con ~ per la directory home del sistema operativo.`}},"browser%2Eprofiles%2E*%2Eheadless":{label:{"v1-1dkezh4-t":`Modalità senza interfaccia grafica del profilo browser`},help:{"v1-p4jtgv-4u":`Impostazione specifica per profilo della modalità senza interfaccia grafica per le istanze del browser avviate localmente. Usala quando un profilo deve rimanere senza interfaccia grafica senza imporre browser.headless a tutti gli altri profili.`}},"browser%2Eprofiles%2E*%2EmcpArgs":{label:{"v1-1l3gwbt-v":`Argomenti Chrome MCP del profilo browser`},help:{"v1-rc45ke-5g":`Argomenti aggiuntivi di Chrome DevTools MCP per ciascun profilo per il collegamento existing-session, ad esempio --no-usage-statistics. Gli argomenti dell'endpoint specificati qui hanno la precedenza sulla connessione automatica integrata o sulla selezione dell'URL del browser.`}},"browser%2Eprofiles%2E*%2EmcpCommand":{label:{"v1-fncq59-y":`Comando Chrome MCP del profilo browser`},help:{"v1-1xpty8o-2h":`Comando Chrome DevTools MCP per ciascun profilo per il collegamento existing-session. Il valore predefinito è npx.`}},"browser%2Eprofiles%2E*%2EuserDataDir":{label:{"v1-if29w-t":`Directory dei dati utente del profilo browser`},help:{"v1-5xvgex-9h":`Directory dei dati utente di Chromium per ciascun profilo, usata per collegarsi a una sessione esistente tramite Chrome DevTools MCP. Usala per Brave, Edge, Chromium o profili Chrome non predefiniti quando la procedura di connessione automatica integrata selezionerebbe la directory dei dati del browser errata sull'host o sul nodo browser selezionato. Nei percorsi che iniziano con ~, il simbolo viene espanso nella directory home del sistema operativo.`}},"browser%2EsnapshotDefaults":{label:{"v1-1svdjip-p":`Impostazioni predefinite delle istantanee del browser`},help:{"v1-v19wdy-4y":`Configurazione predefinita per l'acquisizione delle istantanee, usata quando i chiamanti non forniscono opzioni esplicite. Regolala per ottenere un comportamento di acquisizione coerente tra i canali e i percorsi di automazione.`}},"browser%2EsnapshotDefaults%2Emode":{label:{"v1-hishns-l":`Modalità delle istantanee del browser`},help:{"v1-joeyxp-5c":`Modalità predefinita di estrazione delle istantanee che controlla come il contenuto della pagina viene trasformato per l'utilizzo da parte dell'agente. Scegli la modalità che bilancia leggibilità, fedeltà e consumo di token per i tuoi flussi di lavoro.`}},"browser%2EssrfPolicy":{label:{"v1-18gkqpb-j":`Criteri SSRF del browser`},help:{"v1-1qbp9im-5e":`Impostazioni di protezione contro la falsificazione delle richieste lato server per i percorsi di recupero tramite browser o rete che potrebbero raggiungere host interni. Mantieni impostazioni predefinite restrittive in produzione e consenti l'accesso solo a destinazioni esplicitamente approvate.`}},"browser%2EssrfPolicy%2EallowedHostnames":{label:{"v1-198z5mx-p":`Nomi host consentiti per il browser`},help:{"v1-1rng39-2k":`Nomi host esatti o indirizzi IP letterali consentiti dai controlli dei criteri SSRF del browser. Mantieni l'elenco il più ridotto possibile.`}},"browser%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1phaujk-11":`Consenti l'intervallo locale univoco IPv6 per il browser`},help:{"v1-1glx5cy-2c":`Consenti gli indirizzi locali univoci IPv6 (fc00::/7) per ambienti proxy fake-IP attendibili.`}},"browser%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-1tpn2sq-12":`Consenti l'intervallo di benchmark RFC 2544 nel browser`},help:{"v1-10ateu3-2i":`Consenti gli IP dell'intervallo di benchmark RFC 2544 (198.18.0.0/15) per ambienti proxy attendibili con IP fittizi.`}},"browser%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1iun7q1-p":`Nomi host bloccati nel browser`},help:{"v1-nug0we-6k":`Modelli di nomi host bloccati prima della risoluzione DNS e delle regole di autorizzazione, anche con l'accesso alla rete privata abilitato. Supporta host esatti e "*.example.com" solo per i sottodomini; aggiungi "example.com" separatamente per bloccare il dominio radice. Se vuoto o non impostato, non aggiunge alcun blocco.`}},"browser%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1cr58dw-15":`Consenti l'accesso alla rete privata nel browser (pericoloso)`},help:{"v1-17103pi-4m":`Consente l'accesso agli intervalli di indirizzi della rete privata dagli strumenti del browser. Se non impostato, è disabilitato per impostazione predefinita; abilita solo per destinazioni della rete privata esplicitamente attendibili.`}},"browser%2EtabCleanup":{label:{"v1-gn8gk0-j":`Pulizia delle schede del browser`},help:{"v1-1ctwaad-4y":`Criterio di pulizia, per quanto possibile, delle schede del browser aperte dalle sessioni dell'agente principale. Mantienilo abilitato per evitare l'accumulo di schede obsolete della sandbox o del browser gestito nei gateway attivi a lungo.`}},"browser%2EtabCleanup%2Eenabled":{label:{"v1-1blo8gh-r":`Pulizia delle schede del browser abilitata`},help:{"v1-4sv97p-3u":`Abilita la pulizia delle schede del browser monitorate e inattive per le sessioni dell'agente principale. Disabilita solo quando strumenti esterni gestiscono interamente il ciclo di vita delle schede.`}},channels:{label:{"v1-1ju93md-8":`Canali`},help:{"v1-12yv6ma-5n":`Configurazioni dei fornitori di canali e impostazioni predefinite condivise che controllano i criteri di accesso, la visibilità dei segnali periodici di attività e il comportamento per ciascuna interfaccia. Mantieni centralizzate le impostazioni predefinite e personalizzale per ciascun fornitore solo dove necessario.`}},"channels%2Edefaults":{label:{"v1-1wd3bq-g":`Impostazioni predefinite dei canali`},help:{"v1-uz6veb-4p":`Comportamento predefinito dei canali applicato a tutti i provider quando non sono definite impostazioni specifiche per provider. Usalo per applicare criteri di base coerenti prima di personalizzare le impostazioni di ciascun provider.`}},"channels%2Edefaults%2EbotLoopProtection":{label:{"v1-8f25je-r":`Protezione predefinita dai loop tra bot`},help:{"v1-1lpznyk-4w":`Impostazioni predefinite di protezione dai loop per coppia per i provider di canali che supportano protezioni dai loop tra bot. Usa impostazioni specifiche per provider solo quando un canale richiede un limite diverso.`}},"channels%2Edefaults%2EbotLoopProtection%2EcooldownSeconds":{label:{"v1-wfzv79-x":`Secondi di pausa predefiniti per i loop tra bot`},help:{"v1-1yl5ird-2z":`Secondi di pausa applicati a una coppia dopo il superamento del limite di eventi del loop. Il valore predefinito per i canali che supportano questa funzione è 60.`}},"channels%2Edefaults%2EbotLoopProtection%2Eenabled":{label:{"v1-1245lyz-z":`Protezione predefinita dai loop tra bot abilitata`},help:{"v1-3ruik-4r":`Abilita per impostazione predefinita la protezione dai loop per coppia sui canali che la supportano, quando i messaggi generati dai bot possono essere inoltrati. I provider possono comunque disabilitare la protezione quando i bot vengono ignorati.`}},"channels%2Edefaults%2EbotLoopProtection%2EmaxEventsPerWindow":{label:{"v1-i8sfy1-y":`Eventi predefiniti per finestra per i loop tra bot`},help:{"v1-1u0mdjc-41":`Numero massimo di eventi che una coppia mittente/destinatario può scambiare nella finestra configurata prima che inizi il blocco. Il valore predefinito per i canali che supportano questa funzione è 20.`}},"channels%2Edefaults%2EbotLoopProtection%2EwindowSeconds":{label:{"v1-vkrwg4-v":`Durata predefinita della finestra dei loop tra bot in secondi`},help:{"v1-12xpmen-2m":`Durata della finestra mobile in secondi per i limiti dei cicli tra coppie. Il valore predefinito per i canali che supportano questa funzionalità è 60.`}},"channels%2Edefaults%2EcontextVisibility":{label:{"v1-xrgozf-q":`Visibilità predefinita del contesto`},help:{"v1-1hze3g1-5o":`Visibilità predefinita del contesto supplementare per i contenuti recuperati da citazioni, thread e cronologia: "all" (mantieni tutto il contesto), "allowlist" (solo mittenti nell'elenco consentiti) o "allowlist_quote" (elenco consentiti + mantieni le citazioni esplicite).`}},"channels%2Edefaults%2EgroupPolicy":{label:{"v1-1tib8bt-k":`Criterio predefinito per i gruppi`},help:{"v1-ntl9m4-4n":`Criterio predefinito per i gruppi su tutti i canali: "open", "disabled" o "allowlist". Mantieni "allowlist" per configurazioni di produzione più sicure, a meno che non si desideri una partecipazione estesa ai gruppi.`}},"channels%2Edefaults%2EheartbeatVisibility":{label:{"v1-knuq96-s":`Visibilità predefinita degli heartbeat`},help:{"v1-49bw75-4v":`Impostazioni predefinite di visibilità degli heartbeat per i messaggi di stato emessi da provider e canali. Regolale globalmente per ridurre gli aggiornamenti superflui sul corretto funzionamento, mantenendo visibili gli avvisi.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowAlerts":{label:{"v1-8z6943-l":`Mostra avvisi heartbeat`},help:{"v1-8dk8zx-4g":`Se impostato su true, mostra gli avvisi heartbeat relativi a stati degradati o errori, in modo che i canali degli operatori segnalino tempestivamente i problemi. Mantieni l'opzione abilitata in produzione per rendere visibili i malfunzionamenti dei canali.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowOk":{label:{"v1-z25yzy-h":`Mostra heartbeat OK`},help:{"v1-17tg3mk-4z":`Mostra le voci di stato regolare/OK dell'heartbeat negli output di stato dei canali quando è impostato su true. Mantieni false negli ambienti con molte notifiche e abilita l'opzione solo quando gli operatori necessitano di conferme esplicite del corretto funzionamento.`}},"channels%2Edefaults%2EheartbeatVisibility%2EuseIndicator":{label:{"v1-16d7e6t-n":`Usa indicatore heartbeat`},help:{"v1-1w12cs2-4m":`Abilita una visualizzazione sintetica dell'heartbeat tramite indicatori anziché testo di stato dettagliato, dove supportato. Usa la modalità indicatore per dashboard dense con molti canali attivi.`}},"channels%2Edefaults%2EimplicitMentions":{label:{"v1-1xvvux0-p":`Menzioni implicite predefinite`},help:{"v1-4gtdyv-48":`Criterio predefinito che determina se le risposte al bot, le citazioni del bot e la partecipazione del bot a una discussione attivano i canali di messaggistica compatibili senza una menzione esplicita.`}},"channels%2Edefaults%2EimplicitMentions%2EquotedBot":{label:{"v1-190ozts-10":`Menzioni implicite predefinite per citazioni del bot`},help:{"v1-va1u5v-2v":`Considera per impostazione predefinita i messaggi citati del bot come menzioni implicite. Il valore predefinito è true per garantire la compatibilità con le versioni precedenti.`}},"channels%2Edefaults%2EimplicitMentions%2EreplyToBot":{label:{"v1-1y8bnfy-12":`Menzioni implicite predefinite per risposte al bot`},help:{"v1-lm44c3-39":`Considera per impostazione predefinita le risposte ai messaggi del bot stesso come menzioni implicite. Il valore predefinito è true per garantire la compatibilità con le versioni precedenti.`}},"channels%2Edefaults%2EimplicitMentions%2EthreadParticipation":{label:{"v1-lsf3e8-1a":`Menzioni implicite predefinite per partecipazione alle discussioni`},help:{"v1-160205h-3o":`Considera per impostazione predefinita i messaggi successivi nelle discussioni a cui il bot ha partecipato come menzioni implicite. Il valore predefinito è true per garantire la compatibilità con le versioni precedenti.`}},"channels%2EmodelByChannel":{label:{"v1-k5b3gw-n":`Override del modello per canale`},help:{"v1-1b01spx-2p":`Mappatura fornitore -> ID del canale / ID dell'interlocutore nei messaggi diretti -> override del modello (i valori sono provider/model o alias).`}},cli:{label:{"v1-mb8vjd-3":`CLI`}},cloudWorkers:{label:{"v1-1un3411-d":`Worker cloud`},help:{"v1-10carc4-5v":`Profili worker cloud ad attivazione facoltativa per ambienti remoti temporanei. Se questa sezione viene omessa o non contiene profili, la creazione di worker cloud rimane non disponibile e il comportamento esistente dello stato del Gateway/nodo resta invariato.`}},"cloudWorkers%2Edesktop":{label:{"v1-11xu2ur-r":`Desktop dei worker cloud (Labs)`},help:{"v1-vllayc-3n":`Abilita l'interfaccia sperimentale worker.desktop.observe e il pannello Desktop della Control UI per gli ambienti worker cloud con supporto desktop.`}},"cloudWorkers%2EpreparedPool":{label:{"v1-s34lt5-q":`Pool di worker cloud predisposti`},help:{"v1-rw51o5-6b":`Limiti per i worker cloud predisposti e mantenuti pronti per le sessioni successive. Le risorse di riserva comportano costi per le macchine in esecuzione fino al completamento della pulizia da parte del provider; la loro scadenza fissa dipende dalla domanda effettiva del progetto e dalla politica di inattività già in vigore presso il provider.`}},"cloudWorkers%2EpreparedPool%2EmaxTotal":{label:{"v1-c8ff5f-u":`Limite della riserva di worker cloud pronti`},help:{"v1-1mpd1dt-7u":`Limite complessivo del Gateway per i worker cloud preparati e non assegnati, condiviso tra progetti e profili (valore predefinito: 4). Nel conteggio rientrano i worker in preparazione e le riserve la cui rimozione non è ancora confermata. Imposta 0 per svuotare le riserve non assegnate e disabilitarne il reintegro, mantenendo il riutilizzo degli snapshot e le sessioni attive.`}},"cloudWorkers%2Eprofiles":{label:{"v1-xctezy-l":`Profili worker cloud`},help:{"v1-eii67l-3j":`Profili worker cloud con nome. Ogni profilo seleziona un fornitore di worker registrato da un plugin e contiene le impostazioni gestite dal fornitore.`}},"cloudWorkers%2Eprofiles%2E*":{label:{"v1-lsdort-k":`Profilo worker cloud`},help:{"v1-1v2w7jl-4u":`Un profilo worker cloud selezionato per nome durante la creazione di un ambiente. Conserva le credenziali del fornitore nei riferimenti supportati anziché incorporare dati segreti in questo blocco.`}},"cloudWorkers%2Eprofiles%2E*%2Einstall":{label:{"v1-1y9aivk-r":`Metodo di installazione del worker cloud`},help:{"v1-blrtbf-74":`Metodo di installazione del worker: "bundle" (predefinito) trasferisce la build installata del Gateway, identificata dall'hash del contenuto, e supporta versioni rilasciate, di sviluppo e non ancora rilasciate; "npm" installa la versione esatta del Gateway ed è disponibile solo quando tale versione è stata rilasciata.`}},"cloudWorkers%2Eprofiles%2E*%2Eprovider":{label:{"v1-v7eu21-l":`Fornitore di worker cloud`},help:{"v1-1p4s4c1-44":`ID del provider di worker registrato da un plugin. Il plugin configurato deve esporre questo ID prima che il gateway possa creare ambienti dal profilo.`}},"cloudWorkers%2Eprofiles%2E*%2EreadyWorkers":{label:{"v1-g69eog-x":`Obiettivo della riserva di worker cloud pronti`},help:{"v1-1nwve9s-7w":`Numero desiderato di worker preparati e non assegnati per ciascun progetto idoneo che utilizza questo profilo (valore predefinito: 1), nel rispetto del limite complessivo del pool di worker preparati del Gateway. Imposta 0 per disabilitare le riserve di questo profilo, mantenendo il riutilizzo degli snapshot. Nel conteggio rientrano i worker in preparazione e le riserve la cui rimozione non è ancora confermata.`}},"cloudWorkers%2Eprofiles%2E*%2Esettings":{label:{"v1-p040za-u":`Impostazioni del provider di worker cloud`},help:{"v1-mq7u32-4j":`Impostazioni gestite dal provider e convalidate dal plugin selezionato. Usa oggetti SecretRef per i valori contenenti segreti; le impostazioni opache non beneficiano della risoluzione automatica dei segreti.`}},"cloudWorkers%2Eprofiles%2E*%2EsuspendAfter":{label:{"v1-2izlgm-y":`Tempo di inattività prima della sospensione del worker cloud`},help:{"v1-1keuwgh-4w":`Libera automaticamente le risorse di un worker cloud inattivo dopo questa durata, ad esempio 45m o 2h; il messaggio successivo ne crea uno sostitutivo. Minimo: 1m. Lascia non impostato per mantenere i worker in esecuzione.`}},"cloudWorkers%2EprojectProfiles":{label:{"v1-10hp68d-t":`Profili di worker cloud per progetto`},help:{"v1-1kkfrif-46":`Nomi dei profili di worker cloud predefiniti, indicizzati per identità del repository normalizzata in minuscolo (host/owner/repo). Gli ID di profilo specificati esplicitamente per l'invio hanno la precedenza.`}},"cloudWorkers%2EprojectProfiles%2E*":{label:{"v1-17lr59o-s":`Profilo di worker cloud per progetto`},help:{"v1-1mux5u0-30":`Nome del profilo di worker cloud usato per impostazione predefinita quando l'origine del worktree di una sessione corrisponde a questa identità del repository.`}},commands:{label:{"v1-15x4mpf-8":`Comandi`},help:{"v1-1gi0dr2-5a":`Controlla le interfacce dei comandi in chat, le restrizioni riservate al proprietario e il comportamento dell'accesso con privilegi elevati ai comandi tra i provider. Mantieni le impostazioni predefinite, a meno che non servano controlli più rigorosi per gli operatori o una disponibilità più ampia dei comandi.`}},"commands%2EallowFrom":{label:{"v1-axacxh-t":`Regole di accesso con privilegi elevati ai comandi`},help:{"v1-7azkw-5g":`Definisce le regole di autorizzazione dei comandi con privilegi elevati per canale e mittente nelle interfacce di comando a livello di proprietario. Usa identità specifiche del provider con ambito ristretto, in modo che i comandi privilegiati non siano esposti a un pubblico ampio nelle chat.`}},"commands%2Ebash":{label:{"v1-1nbpj93-n":`Consenti il comando Bash in chat`},help:{"v1-83ah7w-36":"Consente al comando bash in chat (`!`; alias `/bash`) di eseguire comandi della shell sull'host (valore predefinito: false; richiede tools.elevated)."}},"commands%2EbashForegroundMs":{label:{"v1-1vfppjv-r":`Durata di Bash in primo piano (ms)`},help:{"v1-1o0o4dw-2c":`Tempo di attesa di bash prima di passare in background (valore predefinito: 2000; 0 passa immediatamente in background).`}},"commands%2Econfig":{label:{"v1-14wzjd5-d":`Consenti /config`},help:{"v1-151bb7c-21":`Consente al comando /config in chat di leggere e scrivere la configurazione su disco (valore predefinito: false).`}},"commands%2Edebug":{label:{"v1-12w2s6q-c":`Consenti /debug`},help:{"v1-y1lc3j-1y":`Consente l'uso del comando /debug in chat per applicare modifiche valide solo durante l'esecuzione (valore predefinito: false).`}},"commands%2Emcp":{label:{"v1-16ynh2x-a":`Consenti /mcp`},help:{"v1-1rtwcgd-2o":`Consente al comando /mcp in chat di gestire la configurazione dei server MCP di OpenClaw in mcp.servers (valore predefinito: false).`}},"commands%2Enative":{label:{"v1-11r5pqs-f":`Comandi nativi`},help:{"v1-dighr2-5n":`Registra comandi nativi slash o di menu nei canali che supportano la registrazione dei comandi (Discord, Slack, Telegram). Mantieni l'opzione abilitata per facilitare l'individuazione dei comandi, a meno che tu non scelga intenzionalmente flussi di lavoro con comandi solo testuali.`}},"commands%2EnativeSkills":{label:{"v1-hpi0k3-l":`Comandi nativi delle skill`},help:{"v1-19gtqci-5h":`Registra comandi nativi delle skill in modo che gli utenti possano richiamarle direttamente dai menu dei comandi del provider, ove supportato. Mantieni l'impostazione coerente con i criteri per le skill, in modo che i comandi esposti corrispondano alle aspettative degli operatori.`}},"commands%2EownerAllowFrom":{label:{"v1-1bc6u1a-e":`Proprietari dei comandi`},help:{"v1-1di38gv-3y":`Elenco esplicito dei proprietari autorizzati a usare i comandi riservati ai proprietari. Usa gli ID nativi del canale (facoltativamente con un prefisso come "whatsapp:+15551234567"). '*' viene ignorato.`}},"commands%2Eplugins":{label:{"v1-culv09-e":`Consenti /plugins`},help:{"v1-akwy9y-33":`Consente al comando di chat /plugins di elencare i plugin rilevati e di attivarli o disattivarli nella configurazione (valore predefinito: false).`}},"commands%2Erestart":{label:{"v1-d0qh1l-d":`Consenti riavvio`},help:{"v1-m32fv2-27":`Consenti /restart, /update e le richieste esterne di riavvio SIGUSR2 (valore predefinito: true).`}},"commands%2Etext":{label:{"v1-5g1c88-d":`Comandi testuali`},help:{"v1-1utu76s-5j":`Abilita l'analisi dei comandi testuali immessi in chat, oltre alle interfacce dei comandi nativi, ove disponibili. Mantieni attiva questa opzione per garantire la compatibilità con i canali che non supportano la registrazione dei comandi nativi.`}},cron:{label:{"v1-1qlte4b-b":`Automazioni`},help:{"v1-4md8ic-5u":`Impostazioni globali dello scheduler per le automazioni memorizzate, le esecuzioni simultanee, i meccanismi alternativi di consegna e la conservazione delle sessioni di esecuzione. Mantieni i valori predefiniti, a meno che tu non stia aumentando il volume delle automazioni o integrando destinatari di webhook esterni.`}},"cron%2Eenabled":{label:{"v1-1amdki2-j":`Automazioni abilitate`},help:{"v1-y8otx6-5i":`Abilita l'esecuzione delle automazioni per le pianificazioni memorizzate gestite dal Gateway. Mantieni attiva questa opzione per i normali flussi di promemoria e automazione e disattivala solo per sospendere tutte le esecuzioni delle automazioni senza eliminare le attività.`}},"cron%2EsessionRetention":{label:{"v1-1cvkclx-t":`Conservazione delle sessioni delle automazioni`},help:{"v1-4wagu6-7e":"Controlla per quanto tempo vengono conservate le sessioni delle esecuzioni di automazione completate prima della rimozione (`24h`, `7d`, `1h30m` oppure `false` per disabilitare la rimozione; anche una durata pari a zero, come `0h`, la disabilita; valore predefinito: `24h`). Usa un periodo di conservazione più breve per ridurre la crescita dello spazio occupato in caso di pianificazioni ad alta frequenza."}},"cron%2EskipMissedJobs":{label:{"v1-1wkngn0-x":`Salta le automazioni ricorrenti non eseguite`},help:{"v1-w9wfmo-66":`All'avvio del Gateway, salta le esecuzioni ricorrenti cron/every non effettuate e pianifica la loro prossima occorrenza futura anziché recuperarle. Valore predefinito: false. Abilita questa opzione per evitare promemoria obsoleti dopo un periodo di inattività; le attività singole di tipo at vengono comunque recuperate.`}},"cron%2EwebhookSsrfPolicy":{label:{"v1-xrkjiu-v":`Criterio SSRF dei webhook delle automazioni`},help:{"v1-1xlfqnu-5h":`Criterio SSRF applicato a ogni webhook in uscita delle automazioni. Le destinazioni private, di loopback, link-local e interne restano bloccate a meno che questo criterio non le consenta esplicitamente. Lascia non impostato per applicare restrizioni rigorose all'invio.`}},"cron%2EwebhookSsrfPolicy%2EallowedHostnames":{label:{"v1-w1bhls-11":`Nomi host consentiti per i webhook delle automazioni`},help:{"v1-1i94hyz-3n":`Nomi host esatti o indirizzi IP letterali consentiti per l'invio dei webhook delle automazioni, incluse le destinazioni altrimenti bloccate. Mantieni l'elenco il più ridotto possibile.`}},"cron%2EwebhookSsrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1p9upj5-1d":`Consenti l'intervallo IPv6 locale univoco per i webhook delle automazioni`},help:{"v1-rke0oj-3b":`Consente l'invio dei webhook delle automazioni a indirizzi IPv6 locali univoci (fc00::/7). Usa questa opzione solo con ambienti proxy fake-IP attendibili.`}},"cron%2EwebhookSsrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-y1ryjx-1e":`Consenti l'intervallo di benchmark RFC 2544 per i webhook delle automazioni`},help:{"v1-x1usg4-3h":`Consente i webhook delle automazioni verso gli IP dell'intervallo di benchmark RFC 2544 (198.18.0.0/15). Usare solo in ambienti proxy con IP fittizi attendibili.`}},"cron%2EwebhookSsrfPolicy%2EblockedHostnames":{label:{"v1-6c1248-11":`Nomi host bloccati per i webhook delle automazioni`},help:{"v1-16cv1ic-6a":`Modelli di nomi host bloccati prima della risoluzione DNS e delle regole di autorizzazione per l'invio dei webhook delle automazioni. Supporta host esatti e "*.example.com" solo per i sottodomini; aggiungere "example.com" separatamente per bloccare il dominio radice. Se vuoto o non impostato, non aggiunge alcun blocco.`}},"cron%2EwebhookSsrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-o4lenl-1h":`Consenti rete privata per i webhook delle automazioni (pericoloso)`},help:{"v1-1n9710c-3t":`Consente i webhook delle automazioni verso destinazioni di rete private e interne. Lasciare disabilitato a meno che tutte le destinazioni webhook configurate siano attendibili.`}},"cron%2EwebhookToken":{label:{"v1-18ivgo6-w":`Token Bearer dei webhook delle automazioni`},help:{"v1-1l90hxg-5l":`Token Bearer allegato agli invii POST dei webhook delle automazioni quando si usa la modalità webhook. Preferire la sostituzione tramite segreti o variabili d'ambiente e ruotare regolarmente questo token se gli endpoint webhook condivisi sono raggiungibili da Internet.`}},desktop:{label:{"v1-rs698z-7":`Desktop`}},"desktop%2Ehost":{label:{"v1-rh14ls-d":`Desktop locale`},help:{"v1-99weio-30":`Osservazione del desktop per i nodi associati o per la sorgente sperimentale dell'host Gateway, basata su un server VNC locale.`}},"desktop%2Ehost%2Eenabled":{label:{"v1-10wailb-f":`Condivisione del desktop`},help:{"v1-m9lbcj-83":`Abilita la sorgente desktop di questo computer. I nodi macOS, Windows e Linux associati sono abilitati per impostazione predefinita; una preferenza di condivisione esplicita nell'app desktop ha la precedenza. La sorgente Labs dell'host Gateway è disabilitata per impostazione predefinita e applica le modifiche in tempo reale. Riavvia un nodo associato dopo averne modificato la configurazione desktop.`}},"desktop%2Ehost%2Emanaged":{label:{"v1-3hgdsm-q":`Desktop gestito dell'host Linux`},help:{"v1-1r7n22m-49":`Esegue e supervisiona su Linux un desktop TigerVNC/XFCE headless accessibile solo tramite loopback. Una porta esplicita o un server VNC esistente sulla porta predefinita ha comunque la precedenza.`}},"desktop%2Ehost%2EpasswordFile":{label:{"v1-pdfkek-n":`File della password VNC locale`},help:{"v1-1m5lsox-37":`Percorso assoluto del file della password VNC. Omettilo su macOS per inserire le credenziali dell'account all'apertura del visualizzatore desktop.`}},"desktop%2Ehost%2Eport":{label:{"v1-1bci0ps-e":`Porta VNC locale`},help:{"v1-1ku4w9b-2b":`Porta RFB di loopback di un server VNC già in esecuzione su questa macchina (valore predefinito: 5900).`}},diagnostics:{label:{"v1-1stxhg7-b":`Diagnostica`},help:{"v1-1d5rnym-5p":`Controlli diagnostici per il tracciamento mirato, l'esportazione della telemetria e l'ispezione della cache durante il debug. In produzione, mantenere al minimo la diagnostica di base e abilitare segnali più dettagliati solo durante l'analisi dei problemi.`}},"diagnostics%2EcacheTrace":{label:{"v1-d7o58-b":`Tracciamento della cache`},help:{"v1-10523zm-5b":`Impostazioni di registrazione del tracciamento della cache per osservare le decisioni della cache e il contesto del payload nelle esecuzioni integrate. Abilitare temporaneamente questa funzione per il debug e disabilitarla al termine per ridurre la quantità di dati sensibili nei log.`}},"diagnostics%2EcacheTrace%2Eenabled":{label:{"v1-u2445x-j":`Tracciamento della cache abilitato`},help:{"v1-2c1umi-1v":`Registra istantanee del tracciamento della cache per le esecuzioni dell'agente integrato (predefinito: false).`}},"diagnostics%2Eenabled":{label:{"v1-17k9ppq-j":`Diagnostica abilitata`},help:{"v1-a46pxt-4h":`Interruttore generale per l'output della strumentazione diagnostica nei log e nei percorsi di integrazione della telemetria. Abilitato per impostazione predefinita; impostare su false solo in ambienti con vincoli molto rigidi.`}},"diagnostics%2Eflags":{label:{"v1-x05x98-h":`Flag di diagnostica`},help:{"v1-x4w5ok-33":`Abilita log diagnostici mirati tramite flag (ad es. ["telegram.http"]). Supporta caratteri jolly come "telegram.*" o "*".`}},"diagnostics%2Eotel":{label:{"v1-wfx8h0-d":`OpenTelemetry`},help:{"v1-isgk7l-5b":`Impostazioni di esportazione OpenTelemetry per tracce, metriche e log emessi dai componenti del Gateway. Usa queste impostazioni per l'integrazione con backend di osservabilità centralizzati e pipeline di tracciamento distribuito.`}},"diagnostics%2Eotel%2EcaptureContent":{label:{"v1-1xxk57n-t":`Acquisizione dei contenuti OpenTelemetry`},help:{"v1-19tid4t-2t":`Acquisizione dei contenuti degli span OTEL su attivazione esplicita. Disattivata per impostazione predefinita; true acquisisce il contenuto dei messaggi non di sistema e degli strumenti.`}},"diagnostics%2Eotel%2Eenabled":{label:{"v1-bh3lp-l":`OpenTelemetry abilitato`},help:{"v1-193bm0-5b":`Abilita la pipeline di esportazione OpenTelemetry per tracce, metriche e log in base alle impostazioni configurate per endpoint e protocollo. Mantieni l'opzione disabilitata finché l'endpoint del collector e l'autenticazione non sono completamente configurati.`}},"diagnostics%2Eotel%2Eendpoint":{label:{"v1-mpv6hp-m":`Endpoint OpenTelemetry`},help:{"v1-4rrd1x-4y":`URL dell'endpoint del collector usato per il trasporto dei dati esportati da OpenTelemetry, inclusi schema e porta. Usa un endpoint del collector raggiungibile e attendibile e monitora gli errori di acquisizione dopo la messa in produzione.`}},"diagnostics%2Eotel%2EflushIntervalMs":{label:{"v1-1rqdzae-x":`Intervallo di invio OpenTelemetry (ms)`},help:{"v1-1moqogc-53":`Intervallo in millisecondi per l'invio periodico dei dati di telemetria dai buffer al collector. Aumentalo per ridurre la frequenza delle esportazioni o diminuiscilo per ottenere una visibilità più rapida durante la gestione attiva degli incidenti.`}},"diagnostics%2Eotel%2Eheaders":{label:{"v1-kknm0u-l":`Intestazioni OpenTelemetry`},help:{"v1-s26t2a-52":`Intestazioni HTTP aggiuntive inviate con le richieste di esportazione OpenTelemetry, spesso usate per l'autenticazione del tenant o l'instradamento. Conserva i segreti in valori ricavati da variabili d'ambiente ed evita la proliferazione di intestazioni non necessarie.`}},"diagnostics%2Eotel%2Elogs":{label:{"v1-1o5ymv2-q":`Log OpenTelemetry abilitati`},help:{"v1-12wo6rv-4k":`Abilita l'esportazione dei segnali di log tramite OpenTelemetry, oltre alle destinazioni di registrazione locali. Usa questa opzione quando è necessaria una correlazione centralizzata dei log tra servizi e agenti.`}},"diagnostics%2Eotel%2ElogsEndpoint":{label:{"v1-7bltwc-r":`Endpoint dei log OpenTelemetry`},help:{"v1-1vgzldu-40":`Endpoint OTLP/HTTP specifico per i segnali di log. Se impostato, sostituisce diagnostics.otel.endpoint e OTEL_EXPORTER_OTLP_ENDPOINT solo per l'esportazione dei log.`}},"diagnostics%2Eotel%2ElogsExporter":{label:{"v1-16nvfm8-r":`Esportatore dei log OpenTelemetry`},help:{"v1-9bzywd-5q":`Destinazione di esportazione dei log per diagnostics.otel.logs. Usa "otlp" per l'endpoint dei log OTLP configurato, "stdout" per un record JSON per ogni riga di stdout nelle pipeline dei log dei container e "both" quando sono necessarie entrambe le destinazioni.`}},"diagnostics%2Eotel%2EmetricNamePrefix":{label:{"v1-hrys5-w":`Prefisso dei nomi delle metriche OpenTelemetry`},help:{"v1-1epdpi9-b2":`Sostituisce il prefisso predefinito "openclaw." nei nomi delle metriche di OpenClaw. Usa una stringa vuota per rimuovere il prefisso, oppure una stringa di massimo 128 caratteri tra lettere ASCII, cifre, trattini bassi, punti, trattini e barre, che inizi con una lettera. Includi gli eventuali separatori necessari, ad esempio "acme."; i nomi delle metriche standard gen_ai.* restano invariati. La modifica di questo valore richiede l'aggiornamento delle dashboard e degli avvisi che eseguono query sui vecchi nomi.`}},"diagnostics%2Eotel%2Emetrics":{label:{"v1-1o16jew-t":`Metriche OpenTelemetry abilitate`},help:{"v1-13r4cf4-4x":`Abilita l'esportazione dei segnali delle metriche verso l'endpoint del collector OpenTelemetry configurato. Mantieni l'opzione abilitata per le dashboard sullo stato di salute in fase di esecuzione e disabilitala solo se è necessario ridurre al minimo il volume delle metriche.`}},"diagnostics%2Eotel%2EmetricsEndpoint":{label:{"v1-ahl7w6-u":`Endpoint delle metriche OpenTelemetry`},help:{"v1-qlfh7x-47":`Endpoint OTLP/HTTP specifico per il segnale delle metriche. Se impostato, sostituisce diagnostics.otel.endpoint e OTEL_EXPORTER_OTLP_ENDPOINT solo per l'esportazione delle metriche.`}},"diagnostics%2Eotel%2Eprotocol":{label:{"v1-4ikcpk-m":`Protocollo OpenTelemetry`},help:{"v1-17ine8s-5e":`Protocollo di trasporto OTel per l'esportazione della telemetria. È accettato solo "http/protobuf"; esegui "openclaw doctor --fix" per correggere un valore legacy "grpc" salvato o ottenere istruzioni di modifica manuale specifiche per l'origine.`}},"diagnostics%2Eotel%2EsampleRate":{label:{"v1-1qd4hmt-v":`Tasso di campionamento delle tracce OpenTelemetry`},help:{"v1-brcwep-50":`Tasso di campionamento delle tracce (0-1) che controlla la quantità di traffico delle tracce esportata verso i backend di osservabilità. Tassi più bassi riducono il sovraccarico e i costi, mentre tassi più alti migliorano la precisione del debug.`}},"diagnostics%2Eotel%2EserviceName":{label:{"v1-1b6j4ku-q":`Nome del servizio OpenTelemetry`},help:{"v1-1hpiqon-5d":`Nome del servizio riportato negli attributi della risorsa di telemetria per identificare questa istanza del gateway nei backend di osservabilità. Usa nomi stabili affinché dashboard e avvisi rimangano coerenti tra le distribuzioni.`}},"diagnostics%2Eotel%2Etraces":{label:{"v1-ypycsr-s":`Tracce OpenTelemetry abilitate`},help:{"v1-j7zrrp-4s":`Abilita l'esportazione dei segnali delle tracce verso l'endpoint del collector OpenTelemetry configurato. Mantieni l'opzione abilitata quando è necessario il tracciamento per l'analisi della latenza o il debug e disabilitala se desideri solo metriche e log.`}},"diagnostics%2Eotel%2EtracesEndpoint":{label:{"v1-1m2hzmb-t":`Endpoint delle tracce OpenTelemetry`},help:{"v1-8yw5p1-43":`Endpoint delle tracce OTLP/HTTP specifico per il tipo di segnale. Se impostato, sostituisce diagnostics.otel.endpoint e OTEL_EXPORTER_OTLP_ENDPOINT solo per l'esportazione delle tracce.`}},discovery:{label:{"v1-l2sr05-9":`Individuazione`},help:{"v1-1sqleij-4w":`Impostazioni di individuazione dei servizi per l'annuncio mDNS locale e la segnalazione facoltativa della presenza su reti geografiche. Limita l'individuazione alle reti previste per evitare la divulgazione dei metadati dei servizi.`}},"discovery%2Emdns":{label:{"v1-1sefhx1-e":`Individuazione mDNS`},help:{"v1-vtbyyq-4w":`Gruppo di configurazione dell'individuazione mDNS per l'annuncio sulla rete locale e la regolazione del comportamento di individuazione. Mantieni la modalità minima per la normale individuazione nella LAN, a meno che non siano necessari metadati aggiuntivi.`}},"discovery%2Emdns%2Emode":{label:{"v1-ybee7c-j":`Modalità di individuazione mDNS`},help:{"v1-1p28pd5-2m":`Modalità di trasmissione mDNS ("minimal" è l'impostazione predefinita, "full" include cliPath/sshPort, "off" disabilita mDNS).`}},"discovery%2EwideArea":{label:{"v1-1u2kx7q-j":`Individuazione su reti geografiche`},help:{"v1-1akkqjm-53":`Gruppo di configurazione dell'individuazione su reti geografiche per esporre i segnali di individuazione oltre l'ambito del collegamento locale. Abilita questa funzione solo nelle distribuzioni che aggregano intenzionalmente la presenza dei gateway tra più sedi.`}},"discovery%2EwideArea%2Edomain":{label:{"v1-1uxd2qe-q":`Dominio di individuazione su reti geografiche`},help:{"v1-rxrygo-4m":`Dominio DNS-SD unicast facoltativo per l'individuazione su reti geografiche, come openclaw.internal. Usalo quando pubblichi intenzionalmente le informazioni di individuazione del gateway oltre l'ambito mDNS locale.`}},env:{label:{"v1-1zc80q-b":`Ambiente`},help:{"v1-1ao5po6-55":`Impostazioni di importazione e sovrascrittura dell'ambiente utilizzate per fornire variabili di runtime al processo gateway. Usa questa sezione per controllare il caricamento dell'ambiente della shell e l'inserimento esplicito delle variabili.`}},"env%2EshellEnv":{label:{"v1-hd6v1l-o":`Importazione dell'ambiente della shell`},help:{"v1-1gw487t-4y":`Controlli di importazione dell'ambiente della shell per caricare le variabili dalla shell di login durante l'avvio. Mantieni abilitata questa opzione se dipendi da segreti definiti nel profilo o da personalizzazioni di PATH.`}},"env%2EshellEnv%2Eenabled":{label:{"v1-9bbyvk-w":`Importazione dell'ambiente della shell abilitata`},help:{"v1-5tiuup-5u":`Abilita il caricamento delle variabili d'ambiente dal profilo della shell dell'utente durante l'inizializzazione all'avvio. Mantieni abilitata questa opzione sulle macchine di sviluppo oppure disabilitala negli ambienti di servizio con restrizioni di sicurezza e gestione esplicita delle variabili d'ambiente.`}},"env%2EshellEnv%2EtimeoutMs":{label:{"v1-g0i751-11":`Timeout di importazione dell'ambiente della shell (ms)`},help:{"v1-nsk2yf-5c":`Tempo massimo in millisecondi consentito per la risoluzione dell'ambiente della shell prima che venga applicato il comportamento di ripiego. Usa timeout più brevi per un avvio più rapido oppure aumentali se l'inizializzazione della shell richiede molte risorse.`}},"env%2Evars":{label:{"v1-grhbhj-u":`Sovrascritture delle variabili d'ambiente`},help:{"v1-yxc3z7-5n":`Sovrascritture esplicite delle variabili d'ambiente in formato chiave/valore, integrate nell'ambiente del processo di OpenClaw in esecuzione. Usa questa opzione per una configurazione deterministica dell'ambiente, anziché affidarti solo agli effetti indiretti del profilo della shell.`}},gateway:{label:{"v1-7gz34p-7":`Gateway`},help:{"v1-19p5env-5v":`Impostazioni di esecuzione del Gateway per modalità di associazione, autenticazione, Control UI, trasporto remoto e controlli di sicurezza operativa. Mantieni valori predefiniti prudenti, a meno che tu non intenda esporre il Gateway oltre le interfacce locali attendibili.`}},"gateway%2EallowRealIpFallback":{label:{"v1-1xoyrfn-w":`Consenti il ripiego su x-real-ip per il Gateway`},help:{"v1-1wr3qmw-4c":`Abilita il ripiego su x-real-ip quando x-forwarded-for è assente negli scenari con proxy. Mantieni disabilitata questa opzione, a meno che la tua infrastruttura di ingresso non richieda questo comportamento di compatibilità.`}},"gateway%2Eauth":{label:{"v1-1uh91et-c":`Autenticazione del Gateway`},help:{"v1-70b6ni-50":`Criteri di autenticazione per l’accesso HTTP/WebSocket al Gateway, inclusi modalità, credenziali, comportamento dei proxy attendibili e limitazione della frequenza. Mantieni l’autenticazione abilitata per ogni distribuzione non limitata al loopback.`}},"gateway%2Eauth%2EallowTailscale":{label:{"v1-fyw82a-11":`Consenti identità Tailscale per l’autenticazione del Gateway`},help:{"v1-vqtmgw-53":`Consente ai percorsi di identità Tailscale attendibili di soddisfare i controlli di autenticazione del Gateway, se configurati. Usa questa opzione solo se la gestione delle identità della tua tailnet è sicura e i flussi di lavoro degli operatori ne dipendono.`}},"gateway%2Eauth%2EidentityScopes":{label:{"v1-1y4ivis-t":`Concessioni di ambiti alle identità del Gateway`},help:{"v1-1h0zxy7-5n":`Associa le identità verificate tramite proxy attendibile o Tailscale a concessioni di ambiti operatore valide solo per la connessione. Le chiavi email vengono confrontate senza distinzione tra maiuscole e minuscole; le concessioni ampliano gli ambiti del dispositivo prima che venga applicato il limite agli ambiti della connessione.`}},"gateway%2Eauth%2Emode":{label:{"v1-av63g8-h":`Modalità di autenticazione del Gateway`},help:{"v1-j8rodq-9t":`Modalità di autenticazione del Gateway: "none", "token", "password" o "trusted-proxy", a seconda dell’architettura perimetrale. La modalità token/password seleziona il segreto configurato (gateway.auth.token o gateway.auth.password); i client possono inviarlo in uno qualsiasi dei due campi di autenticazione della connessione. Usa token/password per l’esposizione diretta e trusted-proxy solo dietro proxy con misure di sicurezza rafforzate e gestione delle identità.`}},"gateway%2Eauth%2Epassword":{label:{"v1-1b8jhsq-g":`Password del Gateway`},help:{"v1-1ndt0u2-4g":`Segreto condiviso selezionato da gateway.auth.mode=password. I client possono inviarlo in auth.token o auth.password. La modalità password è obbligatoria per Tailscale Funnel.`}},"gateway%2Eauth%2ErateLimit":{label:{"v1-cb86oa-n":`Limite di frequenza dell’autenticazione del Gateway`},help:{"v1-1kstr42-54":`Controlli di limitazione dei tentativi di accesso e autenticazione per ridurre il rischio di attacchi di forza bruta alle credenziali al perimetro del gateway. Mantienili abilitati negli ambienti esposti e regola le soglie in base al traffico abituale.`}},"gateway%2Eauth%2Etoken":{label:{"v1-nq7dbs-d":`Token del Gateway`},help:{"v1-16i7cxs-5q":`Segreto condiviso selezionato da gateway.auth.mode=token, l'impostazione predefinita per le nuove configurazioni iniziali locali. I client possono inviarlo tramite auth.token o auth.password. Il binding a indirizzi non di loopback richiede una modalità di autenticazione abilitata.`}},"gateway%2Eauth%2EtrustedProxy":{label:{"v1-17f14p4-q":`Autenticazione del Gateway tramite proxy attendibile`},help:{"v1-12fsi5d-58":`Mappatura delle intestazioni di autenticazione tramite proxy attendibile per i provider di identità a monte che inseriscono attestazioni sull'utente. Usa questa funzionalità solo con CIDR di proxy noti ed elenchi rigorosi di intestazioni consentite per impedire la falsificazione delle intestazioni di identità.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc":{label:{"v1-1hiowhq-12":`Identità GitHub tramite Cloudflare Access OIDC`},help:{"v1-1puth4k-6t":`Identità GitHub verificata facoltativa da un provider OIDC di Cloudflare Access selezionato. Richiede le intestazioni standard di Access per email e asserzione. In assenza di claim, i profili restano basati solo sull’email; i ruoli dei profili esistenti e le preferenze di coautoria vengono mantenuti.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EgithubAccountIdClaim":{label:{"v1-appie6-n":`Claim dell’ID account GitHub`},help:{"v1-pcaaw7-57":`Claim OIDC inoltrato esatto il cui valore è un ID account GitHub verificato, espresso come stringa decimale positiva. Configura Access per inoltrarlo in oidc_fields; non usare mai un claim non verificato modificabile dall’utente.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2Eissuer":{label:{"v1-8flf1b-o":`Emittente Cloudflare Access`},help:{"v1-gykv03-56":`Origine HTTPS esatta del team Cloudflare Access attendibile, ad esempio https://example.cloudflareaccess.com, senza barra finale. Le attestazioni di altri emittenti non forniscono l'identità GitHub.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EproviderId":{label:{"v1-1vne6sn-y":`ID del provider OIDC di Cloudflare Access`},help:{"v1-kbyo5w-44":`ID esatto del provider di identità di Access per l'integrazione OIDC attendibile. Il solo nome visualizzato di un provider o il solo nome corrispondente di un'attestazione non sono sufficienti a stabilire l'attendibilità.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove":{label:{"v1-19sx4ub-y":`Approvazione automatica dei dispositivi tramite proxy attendibile`},help:{"v1-uh32ha-6z":`Criterio facoltativo per approvare automaticamente i nuovi dispositivi degli operatori che usano il browser o l'interfaccia nativa e le estensioni degli ambiti di autorizzazione per la stessa chiave dopo l'autenticazione tramite proxy attendibile. Le autorizzazioni concesse sono limitate da deviceAutoApprove.scopes e dall'intestazione x-openclaw-scopes del proxy, se presente.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Eenabled":{label:{"v1-1hdecc2-16":`Approvazione automatica dei dispositivi tramite proxy attendibile abilitata`},help:{"v1-1nntwls-78":`Approva automaticamente i nuovi dispositivi degli operatori che usano il browser o l'interfaccia nativa e le estensioni degli ambiti di autorizzazione per la stessa chiave dopo che il proxy inverso ha autenticato un utente autorizzato. Valore predefinito: false. Abilita questa opzione solo quando il perimetro di sicurezza dell'identità del proxy è sufficientemente solido da sostituire l'associazione manuale dei dispositivi.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Escopes":{label:{"v1-erslbw-15":`Ambiti di autorizzazione per l'approvazione automatica dei dispositivi tramite proxy attendibile`},help:{"v1-raeila-g3":`Ambiti di autorizzazione massimi concessi ai dispositivi operatore approvati automaticamente. I valori predefiniti sono operator.read, operator.write, operator.approvals e operator.questions. Gli ambiti richiesti sono limitati a questo elenco; alle richieste senza ambiti viene assegnato questo elenco. Se non impostato, l'approvazione automatica aggiunge anche operator.questions per i client UI meno recenti; un elenco esplicito non viene mai ampliato. Includere esplicitamente operator.admin consente a ogni utente autenticato tramite proxy di ottenere automaticamente l'approvazione per i privilegi amministrativi completi e fa sì che le richieste senza ambiti ricevano automaticamente tali privilegi; inoltre, genera un rilievo critico nell'audit di sicurezza e un avviso all'avvio del Gateway.`}},"gateway%2Ebind":{label:{"v1-1g0dmdr-h":`Modalità di associazione del Gateway`},help:{"v1-1unqude-4y":`Profilo di associazione di rete: "auto", "lan", "loopback", "custom" o "tailnet" per controllare l'esposizione delle interfacce. Mantieni "loopback" per il funzionamento solo in locale; "auto" può esporre tutte le interfacce.`}},"gateway%2EcliAgents":{label:{"v1-1noo169-a":`Agenti CLI`},help:{"v1-1qqo8m2-5a":`Rilevamento nella Control UI dei motori di sessione CLI esterni esposti dal catalogo delle sessioni del Gateway. Attivato per impostazione predefinita; disattivalo per impedire l'avvio di tali motori dal selettore del modello per le nuove sessioni.`}},"gateway%2EcliAgents%2Eenabled":{label:{"v1-11gsfq0-i":`Agenti CLI abilitati`},help:{"v1-ufu7fx-8p":`Se impostato su true, mostra gli agenti CLI presenti nel catalogo nel selettore del modello per le nuove sessioni della Control UI (valore predefinito: true). Imposta false per disabilitare gli agenti CLI e la creazione di sessioni CLI native. Vengono elencati solo i cataloghi che dichiarano il supporto alla creazione di sessioni e il selettore rimane nascosto quando il Gateway non dichiara il supporto al catalogo delle sessioni.`}},"gateway%2EcontrolUi":{label:{"v1-1cl7zto-a":`Control UI`},help:{"v1-bkw4g1-5i":`Impostazioni di hosting della Control UI, tra cui abilitazione, percorsi e misure di sicurezza per origini del browser e autenticazione. Limita al minimo l'esposizione dell'interfaccia e adotta controlli di autenticazione robusti prima di renderla accessibile da Internet.`}},"gateway%2EcontrolUi%2EallowedOrigins":{label:{"v1-11jcj2v-q":`Origini consentite per la Control UI`},help:{"v1-1stgitk-9i":`Origini del browser consentite per le connessioni WebSocket della Control UI/WebChat (solo origini complete, ad es. https://control.example.com). Obbligatorie per le distribuzioni della Control UI su indirizzi diversi da loopback, a meno che non sia esplicitamente abilitato il pericoloso fallback basato sull'header Host. L'impostazione ["*"] consente qualsiasi origine del browser e va evitata al di fuori di test locali strettamente controllati.`}},"gateway%2EcontrolUi%2EallowExternalEmbedUrls":{label:{"v1-1flu103-10":`Consenti URL esterni per gli incorporamenti nella Control UI`},help:{"v1-obwpfg-6s":`Opzione PERICOLOSA che consente agli incorporamenti ospitati di caricare URL http(s) esterni assoluti. Lasciala disattivata a meno che la Control UI non incorpori intenzionalmente pagine di terze parti attendibili; i documenti ospitati /__openclaw__/canvas e /__openclaw__/a2ui non ne hanno bisogno.`}},"gateway%2EcontrolUi%2EautomaticallyFetchFavicons":{label:{"v1-spcu6r-x":`Recupera automaticamente le favicon dei link`},help:{"v1-bn9u34-ag":`Recupera le favicon dei link e le anteprime social delle schede del browser tramite il Gateway (attivo per impostazione predefinita). I riquadri delle schede del browser caricano i metadati delle pagine pubbliche e le immagini dichiarate senza cookie del browser né credenziali dei siti. Tutte le richieste sono sottoposte a rigorosi controlli SSRF e a un'elaborazione di HTML e immagini con limiti definiti. Imposta su false per disabilitare il recupero automatico sia delle favicon sia delle anteprime delle pagine; gli screenshot del browser in tempo reale non sono interessati.`}},"gateway%2EcontrolUi%2EbasePath":{label:{"v1-qnzlec-k":`Percorso di base della Control UI`},help:{"v1-1dx68ar-1w":`Prefisso URL facoltativo da cui viene servita la Control UI (ad es. /openclaw).`}},"gateway%2EcontrolUi%2EcommunityInvite":{label:{"v1-1j7cpqc-v":`Invito alla community nella Control UI`},help:{"v1-1rz3zsx-73":`Mostra l'invito alla community Discord nella Control UI servita da questo Gateway (attivo per impostazione predefinita). Imposta su false per nasconderlo in tutti i browser che utilizzano questa distribuzione dell'interfaccia. Le modifiche vengono applicate dopo l'aggiornamento della pagina o la riconnessione del browser; la riattivazione mantiene le preferenze di chiusura salvate localmente nel browser.`}},"gateway%2EcontrolUi%2EdangerouslyAllowHostHeaderOriginFallback":{label:{"v1-vvl359-19":`Consenti il fallback dell'origine basato sull'header Host (pericoloso)`},help:{"v1-1t1qi4c-7v":`Opzione PERICOLOSA che abilita il fallback dell'origine basato sull'header Host per i controlli WebSocket di Control UI/WebChat. Questa modalità è supportata quando la distribuzione si basa intenzionalmente su un criterio di origine che utilizza l'header Host; l'impostazione esplicita di gateway.controlUi.allowedOrigins rimane la configurazione predefinita consigliata per una maggiore sicurezza.`}},"gateway%2EcontrolUi%2EembedSandbox":{label:{"v1-1hknvfl-t":`Modalità sandbox per i contenuti incorporati nella Control UI`},help:{"v1-d54l3a-7c":`Criterio sandbox degli iframe per i contenuti incorporati ospitati nella Control UI. "strict" disabilita gli script, "scripts" consente contenuti incorporati interattivi mantenendo l'isolamento dell'origine (impostazione predefinita) e "trusted" aggiunge \`allow-same-origin\` per i documenti dello stesso sito che richiedono intenzionalmente privilegi maggiori.`}},"gateway%2EcontrolUi%2Eenabled":{label:{"v1-1jokhv9-i":`Control UI abilitata`},help:{"v1-1hhyymc-4w":`Quando impostato su true, abilita la pubblicazione della Control UI del gateway tramite il processo HTTP del gateway. Mantieni l'opzione abilitata per l'amministrazione locale e disabilitala quando viene sostituita da un'interfaccia di controllo esterna.`}},"gateway%2EcontrolUi%2Eenvironment":{label:{"v1-tmefut-m":`Ambiente della Control UI`},help:{"v1-paarso-4n":`Identità pubblica facoltativa dell'ambiente, mostrata nella fascia della Control UI, nell'avatar dell'agente, nelle etichette a pillola, nel titolo del browser e nella favicon. Ometterla per mantenere l'aspetto predefinito.`}},"gateway%2EcontrolUi%2Eenvironment%2Ecolor":{label:{"v1-vy6f72-s":`Colore dell'ambiente della Control UI`},help:{"v1-mp6cta-2i":`Scala cromatica dell'ambiente identificata per nome: teal, amber, purple, coral, pink, blue, green, red o gray.`}},"gateway%2EcontrolUi%2Eenvironment%2Elabel":{label:{"v1-1yr90xz-s":`Etichetta dell'ambiente della Control UI`},help:{"v1-1njve3z-3z":`Etichetta dell'ambiente visualizzata nella Control UI e nella scheda del browser; gli spazi iniziali e finali vengono rimossi e l'etichetta deve contenere da 1 a 24 caratteri.`}},"gateway%2EcontrolUi%2Eexperimental":{label:{"v1-10uccgr-w":`Funzionalità sperimentali della Control UI`},help:{"v1-1qobi2m-3g":`Funzionalità sperimentali della Control UI ad attivazione facoltativa. Queste funzionalità possono cambiare tra una versione e l'altra e rimangono disabilitate se non vengono abilitate esplicitamente.`}},"gateway%2EcontrolUi%2Eexperimental%2EcustomPlugins":{label:{"v1-1gaae1x-g":`Interfaccia dei plugin personalizzati`},help:{"v1-108u6ts-9e":`Consenti ai plugin installati dall'utente di eseguire JavaScript nativo nella Control UI (valore predefinito: false). Le viste dei plugin inclusi rimangono disponibili. L'interfaccia personalizzata condivide le autorizzazioni del Gateway dell'operatore che ha effettuato l'accesso; abilitala solo per i plugin attendibili. Le modifiche si applicano senza riavviare il Gateway. Ricarica le pagine aperte della Control UI per rimuovere il codice dei plugin caricato in precedenza.`}},"gateway%2EcontrolUi%2Egithub%2Etoken":{label:{"v1-1036yk1-10":`Credenziale del servizio GitHub della Control UI`},help:{"v1-1p31phh-d6":`Credenziale di servizio basata su SecretRef per l'individuazione dei progetti nella Control UI e le anteprime di GitHub al passaggio del puntatore in assenza di un'identità gestita. Le anteprime al passaggio del puntatore preferiscono l'identità GitHub configurata per l'agente selezionato, ereditando l'identità di sistema quando non è presente una configurazione specifica. Preferire una configurazione esplicita per attribuire chiaramente la responsabilità del servizio. Ometterla per mantenere il fallback su GH_TOKEN/GITHUB_TOKEN dall'ambiente condiviso del processo Gateway. Una credenziale configurata esplicitamente ma non disponibile impedisce l'accesso.`}},"gateway%2EcontrolUi%2Eroot":{label:{"v1-t5p3aj-m":`Directory radice delle risorse della Control UI`},help:{"v1-elck04-25":`Directory radice facoltativa nel file system per le risorse della Control UI (valore predefinito: dist/control-ui).`}},"gateway%2EcontrolUi%2EsessionObserver":{label:{"v1-tjwi96-r":`Osservatore delle sessioni della Control UI`},help:{"v1-1ahs80-8a":`Genera riepiloghi in tempo reale dello stato delle sessioni per i client della Control UI iscritti, utilizzando il modello di utilità di ciascun agente (attivo per impostazione predefinita). Impostare false per disabilitare le chiamate al modello dell'osservatore in tutto il Gateway; impostare agents.defaults.utilityModel su una stringa vuota disabilita l'osservazione tramite il modello di utilità per gli agenti che non ne sostituiscono il valore.`}},"gateway%2EcustomBindHost":{label:{"v1-upmb47-o":`Host di associazione personalizzato del Gateway`},help:{"v1-lwjcyo-4d":`Indirizzo IPv4 utilizzato per un'associazione personalizzata. Gli indirizzi IPv4 specifici richiedono anche la stessa porta del Gateway su 127.0.0.1; evitare 0.0.0.0 a meno che non sia necessaria l'esposizione su tutte le interfacce.`}},"gateway%2Ehttp":{label:{"v1-1dyy3ff-g":`API HTTP del Gateway`},help:{"v1-ebtex7-4j":`Configurazione dell'API HTTP del Gateway che raggruppa le opzioni di attivazione degli endpoint e i controlli di esposizione dell'API a livello di trasporto. Mantenere abilitati solo gli endpoint necessari per ridurre la superficie di attacco.`}},"gateway%2Ehttp%2Eendpoints":{label:{"v1-1hyy5m9-m":`Endpoint HTTP del Gateway`},help:{"v1-1a0r104-55":`Opzioni di attivazione degli endpoint HTTP esposti dall'API del gateway per le route di compatibilità e le integrazioni facoltative. Abilita gli endpoint in modo consapevole e monitora le modalità di accesso dopo il rilascio.`}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eenabled":{label:{"v1-1lv2qyt-w":`Endpoint OpenAI Chat Completions`},help:{"v1-1271mpb-2b":"Abilita l'endpoint `POST /v1/chat/completions` compatibile con OpenAI (valore predefinito: false)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages":{label:{"v1-9q1ao7-10":`Limiti delle immagini per OpenAI Chat Completions`},help:{"v1-xgscw1-20":"Controlli di recupero e convalida delle immagini per le parti `image_url` compatibili con OpenAI."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowedMimes":{label:{"v1-1acpvsy-18":`Elenco dei tipi MIME consentiti per le immagini di OpenAI Chat Completions`},help:{"v1-1guijf3-1t":"Tipi MIME consentiti per le parti `image_url` (elenco senza distinzione tra maiuscole e minuscole)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowUrl":{label:{"v1-ivns2a-14":`Consenti URL delle immagini per OpenAI Chat Completions`},help:{"v1-55cb3n-47":"Consenti il recupero da URL lato server per le parti `image_url` (valore predefinito: false; gli URI data restano supportati). Imposta su `false` per disabilitare completamente il recupero da URL."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxBytes":{label:{"v1-1aakvdk-13":`Numero massimo di byte per immagine per OpenAI Chat Completions`},help:{"v1-d920yx-1s":"Numero massimo di byte per ogni immagine `image_url` recuperata o decodificata (valore predefinito: 10MB)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxRedirects":{label:{"v1-gi6vbe-17":`Numero massimo di reindirizzamenti per le immagini di OpenAI Chat Completions`},help:{"v1-1enujsk-1z":"Numero massimo di reindirizzamenti HTTP consentiti durante il recupero degli URL `image_url` (valore predefinito: 3)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EtimeoutMs":{label:{"v1-rg0i4t-16":`Timeout delle immagini di OpenAI Chat Completions (ms)`},help:{"v1-89w2b9-1x":"Timeout in millisecondi per il recupero degli URL `image_url` (valore predefinito: 10000)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EurlAllowlist":{label:{"v1-1sb0si1-17":`Elenco degli URL consentiti per le immagini di OpenAI Chat Completions`},help:{"v1-n4hlt1-4r":"Elenco facoltativo dei nomi host consentiti per il recupero degli URL `image_url`; supporta nomi host esatti e caratteri jolly come `*.example.com`. Gli elenchi vuoti o omessi non impongono alcuna restrizione sui nomi host."}},"gateway%2Ehttp%2EsecurityHeaders":{label:{"v1-5g4go1-t":`Intestazioni di sicurezza HTTP del Gateway`},help:{"v1-n8z1hb-44":`Intestazioni di sicurezza delle risposte HTTP facoltative, applicate direttamente dal processo Gateway. È preferibile impostarle sul proxy inverso se TLS termina lì.`}},"gateway%2Ehttp%2EsecurityHeaders%2EstrictTransportSecurity":{label:{"v1-16ryvji-w":`Intestazione Strict Transport Security`},help:{"v1-1buwhc3-3v":`Valore dell'intestazione di risposta Strict-Transport-Security. Impostalo solo per origini HTTPS di cui hai il pieno controllo; usa false per disabilitarlo esplicitamente.`}},"gateway%2Emode":{label:{"v1-1f0xa2s-c":`Modalità del Gateway`},help:{"v1-nfjirv-5m":`Modalità operativa del Gateway: "local" esegue i canali e il runtime dell'agente su questo host, mentre "remote" si connette tramite trasporto remoto. Mantieni "local" a meno che tu non intenda usare una topologia con Gateway remoto separato.`}},"gateway%2Enodes%2EallowSkills":{label:{"v1-bnyeyy-r":`Skills dei nodi del Gateway abilitate`},help:{"v1-1xwu6at-3g":`Accetta le Skills pubblicate dai nodi associati mentre sono connessi (valore predefinito: true). Imposta false per ignorare le Skills pubblicate dai nodi.`}},"gateway%2Enodes%2Ebrowser%2Emode":{label:{"v1-no31im-p":`Modalità browser dei nodi del Gateway`},help:{"v1-oeu1nc-69":`Instradamento del browser tramite nodi ("auto" = preferisce il browser dell’host e usa un singolo nodo browser connesso quando la funzionalità locale non è disponibile; "manual" = richiede la selezione esplicita di un nodo o un’associazione configurata a un nodo specifico; "off" = disabilita l’instradamento tramite nodi).`}},"gateway%2Enodes%2Ebrowser%2Enode":{label:{"v1-1fqwdc0-o":`Nodo fisso per il browser del Gateway`},help:{"v1-1cykty2-1p":`Vincola l'instradamento del browser a un nodo specifico tramite ID o nome (facoltativo).`}},"gateway%2Enodes%2Ecommands%2Eallow":{label:{"v1-9snt7h-13":`Lista dei comandi consentiti per i nodi del Gateway (comandi aggiuntivi)`},help:{"v1-6l4otb-5m":"Comandi node.invoke aggiuntivi da consentire oltre a quelli predefiniti del Gateway (array di stringhe di comando). Abilitare qui comandi pericolosi costituisce una deroga rilevante per la sicurezza e viene segnalato da `openclaw security audit`."}},"gateway%2Enodes%2Ecommands%2Edeny":{label:{"v1-vauwib-l":`Lista dei comandi bloccati per i nodi del Gateway`},help:{"v1-u7c8wx-53":"Nomi dei comandi dei nodi da bloccare anche se presenti nelle dichiarazioni del nodo o nella lista predefinita dei comandi consentiti (solo corrispondenza esatta del nome del comando, ad es. `system.run`; non esamina il testo della shell all'interno di quel comando)."}},"gateway%2Enodes%2Epairing":{label:{"v1-1skp3xv-k":`Associazione dei nodi del Gateway`},help:{"v1-gldsi2-4s":`Impostazioni dei criteri di associazione dei nodi. L'approvazione automatica con verifica SSH è abilitata per impostazione predefinita; l'approvazione automatica tramite CIDR resta disabilitata a meno che non siano configurati elenchi espliciti di CIDR/IP attendibili consentiti.`}},"gateway%2Enodes%2Epairing%2EautoApproveCidrs":{label:{"v1-11ih0u1-13":`CIDR per l'approvazione automatica dell'associazione dei nodi del Gateway`},help:{"v1-1m6jsxj-6x":`Elenco facoltativo di CIDR/IP consentiti per approvare automaticamente la prima associazione di dispositivi con ruolo di nodo senza ambiti richiesti. Disabilitato se non impostato. Le associazioni di operatori, browser e Control UI, nonché qualsiasi associazione che comporti un ampliamento di ruoli o ambiti, un aggiornamento dei metadati o una modifica della chiave pubblica, richiedono comunque l'approvazione manuale.`}},"gateway%2Enodes%2Epairing%2EautoApproveLocal":{label:{"v1-178lial-13":`Approvazione automatica locale dell'associazione dei nodi del Gateway`},help:{"v1-glzm36-41":`Approva senza notifiche le associazioni locali attendibili e gli ampliamenti dell'accesso (valore predefinito: true); imposta false per rinunciare alla comodità e richiedere l'approvazione esplicita di ogni dispositivo.`}},"gateway%2Enodes%2Epairing%2EsshVerify":{label:{"v1-muqemo-11":`Verifica SSH per l'associazione dei nodi del Gateway`},help:{"v1-1e4da92-ct":"Approvazione automatica con verifica SSH per la prima associazione di dispositivi con ruolo di nodo (abilitata per impostazione predefinita). Il gateway si connette tramite SSH all'host che richiede l'associazione (BatchMode, verifica rigorosa delle chiavi host) e approva solo quando l'output remoto di `openclaw node identity` corrisponde alla chiave del dispositivo in attesa. Imposta false per disabilitare la verifica SSH (indipendente da autoApproveCidrs, che resta attivo); per consentire solo l'associazione manuale, rimuovi anche l'impostazione autoApproveCidrs. Passa un oggetto per sovrascrivere user/identity/timeoutMs/cidrs."}},"gateway%2Enodes%2EpluginTools":{label:{"v1-1cgl9u5-p":`Strumenti dei plugin dei nodi del Gateway`},help:{"v1-1c24iq3-28":`Controlla se i nodi associati possono pubblicare descrittori degli strumenti dei plugin visibili agli agenti.`}},"gateway%2Enodes%2EpluginTools%2Eenabled":{label:{"v1-1osj3kc-x":`Strumenti dei plugin dei nodi del Gateway abilitati`},help:{"v1-14lgfu6-47":`Accetta i descrittori degli strumenti dei plugin visibili agli agenti pubblicati dai nodi abbinati (valore predefinito: true). Imposta false per ignorare e rimuovere tutti gli strumenti dei plugin pubblicati dai nodi.`}},"gateway%2Eport":{label:{"v1-sqxdfo-c":`Porta del Gateway`},help:{"v1-for8t5-54":`Porta TCP usata dal listener del Gateway per l'API, la Control UI e i percorsi di ingresso per i canali. Usa una porta dedicata ed evita conflitti con proxy inversi o servizi di sviluppo locali.`}},"gateway%2Eportals":{label:{"v1-zf0m5q-f":`Portali del Gateway`},help:{"v1-1v2lkw9-1c":`Impostazioni di pubblicazione dei portali e di ingresso privato.`}},"gateway%2Eportals%2Eingress":{label:{"v1-1cafvtp-m":`Ingresso privato dei portali`},help:{"v1-20w4gq-69":`Proxy inverso HTTPS wildcard privato facoltativo, gestito dall'operatore. Inoltra l'Host originale, i percorsi e gli upgrade WebSocket al listener di loopback dedicato. L'autenticazione bearer del portale rimane obbligatoria. Richiede il riavvio del Gateway.`}},"gateway%2Eportals%2Eingress%2Edomain":{label:{"v1-iitxfx-m":`Dominio wildcard dei portali`},help:{"v1-1ipbfad-53":`Dominio DNS senza prefissi per sottodomini casuali dei portali (ad esempio previews.example.net). Configura DNS wildcard e HTTPS in modo privato; non condividere lo spazio dei nomi host del Gateway o della Control UI.`}},"gateway%2Eportals%2Eingress%2Eport":{label:{"v1-1o3yr58-s":`Porta di loopback per l'ingresso dei portali`},help:{"v1-1mb98cv-4g":`Porta HTTP di loopback dedicata che riceve il traffico dal proxy HTTPS privato con wildcard. Deve essere diversa dalla porta del Gateway. Questa è la porta del backend, non la porta HTTPS pubblica.`}},"gateway%2EpublicOrigin":{label:{"v1-b3jhw4-l":`Origine pubblica del Gateway`},help:{"v1-17vekvx-87":`Origine HTTPS del Gateway raggiungibile dall'esterno. HTTP è consentito solo per localhost, 127.0.0.1 o [::1]. L'autenticazione OAuth MCP per ciascun richiedente la usa per costruire l'URL di callback in /oauth/mcp/callback; i link alle sessioni dei canali e i link di visualizzazione generati dai plugin la usano per raggiungere la Control UI e le route del Gateway.`}},"gateway%2Epush":{label:{"v1-1o9y10t-l":`Invio di notifiche push del Gateway`},help:{"v1-h23oz7-5s":`Impostazioni di invio delle notifiche push usate dal Gateway quando deve riattivare i dispositivi abbinati o inviare loro notifiche. Configura qui APNs tramite relay per le build iOS ufficiali; l'autenticazione APNs diretta resta basata sulle variabili d'ambiente per le build locali o manuali.`}},"gateway%2Epush%2Eapns":{label:{"v1-gd06d3-l":`Invio tramite APNs del Gateway`},help:{"v1-4bbafr-4e":`Impostazioni di invio tramite APNs per i dispositivi iOS abbinati a questo Gateway. Usa le impostazioni del relay per le build ufficiali dell'App Store che si registrano tramite il relay push esterno.`}},"gateway%2Epush%2Eapns%2Erelay":{label:{"v1-4sjqkk-i":`Relay APNs del Gateway`},help:{"v1-7glbel-6x":`Impostazioni del relay esterno per gli invii APNs tramite relay. Il gateway usa per impostazione predefinita il relay OpenClaw ospitato, oppure questo relay personalizzato per push.test, gli impulsi di risveglio e i risvegli per la riconnessione, dopo che una build iOS ufficiale abbinata pubblica una registrazione basata su relay.`}},"gateway%2Epush%2Eapns%2Erelay%2EbaseUrl":{label:{"v1-m977u4-r":`URL di base del relay APNs del Gateway`},help:{"v1-1o8mgnq-69":`URL HTTPS di base personalizzato facoltativo per il servizio relay APNs esterno utilizzato dalle build iOS ufficiali dell'App Store. Mantienilo allineato all'URL del relay incorporato nella build iOS, in modo che il traffico di registrazione e di invio raggiunga la stessa distribuzione.`}},"gateway%2Epush%2Eapns%2Erelay%2EtimeoutMs":{label:{"v1-1s3crai-v":`Timeout del relay APNs del Gateway (ms)`},help:{"v1-a0jkb1-4z":`Timeout in millisecondi per le richieste di invio dal gateway al relay APNs (valore predefinito: 10000). Aumentalo per relay o reti più lenti, oppure riducilo per interrompere prima i tentativi di risveglio non riusciti.`}},"gateway%2Ereload":{label:{"v1-vobbcc-d":`Ricaricamento della configurazione`},help:{"v1-d02mvq-4w":`Criterio di ricaricamento della configurazione in tempo reale che determina come vengono applicate le modifiche e quando vengono attivati i riavvii completi. Mantieni il comportamento ibrido per aggiornamenti operativi più sicuri, salvo quando esegui il debug dei meccanismi interni di ricaricamento.`}},"gateway%2Ereload%2Emode":{label:{"v1-1qw6ix3-i":`Modalità di ricaricamento della configurazione`},help:{"v1-1q1etcf-3m":`Controlla come vengono applicate le modifiche alla configurazione: "off" ignora le modifiche in tempo reale e "hybrid" applica le modifiche sicure a caldo, quindi riavvia quando necessario.`}},"gateway%2Eremote":{label:{"v1-aaj9cl-e":`Gateway remoto`},help:{"v1-6xv7gd-5a":`Impostazioni di connessione al gateway remoto tramite trasporto diretto o SSH quando questa istanza funge da proxy verso un altro host di esecuzione. Usa la modalità remota solo quando il funzionamento su host separati è configurato intenzionalmente.`}},"gateway%2Eremote%2EedgeAuth":{label:{"v1-5c8ezy-w":`Intestazioni di autenticazione edge del Gateway remoto`},help:{"v1-jg9p7d-5o":`Intestazioni HTTP basate su segreti presentate a un proxy con verifica dell'identità posto davanti al Gateway remoto configurato. Le intestazioni vengono inviate solo all'origine esatta di gateway.remote.url tramite WSS e non seguono mai i reindirizzamenti.`}},"gateway%2Eremote%2Epassword":{label:{"v1-xfnwjq-n":`Password del Gateway remoto`},help:{"v1-16jc0yx-7y":`Segreto condiviso inviato nel campo password per autenticare questo client presso un gateway remoto. L'impostazione gateway.auth.mode del server seleziona il segreto configurato; viene accettato sia il campo token sia il campo password del client. Mantieni questo segreto gestito esternamente ed evita valori in chiaro nella configurazione salvata nel repository.`}},"gateway%2Eremote%2EsshHostKeyPolicy":{label:{"v1-3hl9l5-y":`Criterio per la chiave host SSH del Gateway remoto`},help:{"v1-7qoxtb-49":`Criterio di verifica della chiave host SSH su macOS. "strict" richiede una chiave host già attendibile; "openssh" delega esplicitamente alla configurazione effettiva di OpenSSH.`}},"gateway%2Eremote%2EsshIdentity":{label:{"v1-1rgof8r-r":`Identità SSH del Gateway remoto`},help:{"v1-hz2hsm-1f":`Percorso facoltativo del file di identità SSH (passato a ssh -i).`}},"gateway%2Eremote%2EsshTarget":{label:{"v1-nvjmc8-p":`Destinazione SSH del Gateway remoto`},help:{"v1-85w39w-2t":`Gateway remoto tramite SSH (crea un tunnel dalla porta del gateway a localhost). Formato: user@host o user@host:port.`}},"gateway%2Eremote%2EtlsFingerprint":{label:{"v1-akxcgg-u":`Impronta TLS del Gateway remoto`},help:{"v1-1ri16lk-23":`Impronta TLS sha256 prevista per il gateway remoto (da fissare per evitare attacchi MITM).`}},"gateway%2Eremote%2Etoken":{label:{"v1-kw3r38-k":`Token del Gateway remoto`},help:{"v1-1pb9q8w-7v":`Segreto condiviso inviato nel campo token per autenticare questo client presso un gateway remoto. Il parametro gateway.auth.mode del server seleziona il segreto configurato; sono accettati sia il campo token sia il campo password del client. Archivialo tramite sostituzione di segreti o variabili d'ambiente e ruotalo in concomitanza con le modifiche all'autenticazione del gateway remoto.`}},"gateway%2Eremote%2Etransport":{label:{"v1-hn4r18-o":`Trasporto del Gateway remoto`},help:{"v1-1acfs7m-54":`Trasporto della connessione remota: "direct" utilizza la connessione all'URL configurato, mentre "ssh" crea un tunnel tramite SSH. Usa SSH quando hai bisogno di un tunnel crittografato senza esporre porte remote.`}},"gateway%2Eremote%2Eurl":{label:{"v1-1i53o94-i":`URL del Gateway remoto`},help:{"v1-va7exe-1b":`URL WebSocket del Gateway remoto (ws:// o wss://).`}},"gateway%2Eroles":{label:{"v1-189p1ru-m":`Ruoli operatore del Gateway`},help:{"v1-b59sc5-6w":`Ruoli operatore facoltativi associati ai profili per i Gateway dei team. Ogni ruolo denominato controlla l'accesso alle sessioni altrui, l'isolamento della sandbox, gli agenti delle sessioni e delle esecuzioni e gli ambiti di autorizzazione concessi agli operatori; omettendo questa sezione, il comportamento attuale degli operatori rimane invariato.`}},"gateway%2Eroles%2Edefault":{label:{"v1-1ykt1qe-l":`Ruolo operatore predefinito`},help:{"v1-1v8add8-4u":`Ruolo obbligatorio assegnato ai profili autenticati privi di un'assegnazione esplicita valida quando sono configurati i ruoli operatore. Il suo nome deve corrispondere a una definizione di ruolo configurata.`}},"gateway%2Eroles%2Edefinitions":{label:{"v1-sw4idp-p":`Definizioni dei ruoli operatore`},help:{"v1-uv91an-53":`Definizioni di ruolo non vuote, denominate dall'amministratore, che raggruppano le politiche a insieme chiuso per la condivisione delle sessioni, l'isolamento della sandbox, l'accesso agli agenti e gli ambiti di autorizzazione degli operatori applicate ai profili utente autenticati.`}},"gateway%2Eroles%2Edefinitions%2E*":{label:{"v1-irzm3w-o":`Definizione del ruolo operatore`},help:{"v1-p8tfws-6q":`Un ruolo operatore con un nome. Ogni definizione deve specificare esplicitamente i criteri di condivisione delle sessioni, gli agenti consentiti per sessioni ed esecuzioni e il limite massimo dell'ambito operatore; può inoltre richiedere l'isolamento in sandbox per le nuove sessioni e criteri di accesso forniti da un plugin.`}},"gateway%2Eroles%2Edefinitions%2E*%2EaccessPolicyPlugin":{label:{"v1-yhsyhu-y":`Plugin dei criteri di accesso del ruolo operatore`},help:{"v1-1gq4q08-9n":`ID esatto facoltativo di un plugin i cui criteri di accesso al Gateway devono autorizzare questo ruolo. L'accesso viene negato se il plugin è assente, disabilitato, non viene caricato correttamente o non fornisce un'autorità attualmente valida. Gli ID dei plugin non disponibili restano validi nella configurazione, in modo che i ruoli indipendenti del personale e il proprietario del Gateway possano ripristinare l'accesso. Omettere questo campo non aggiunge alcuna dipendenza da plugin.`}},"gateway%2Eroles%2Edefinitions%2E*%2Eagents":{label:{"v1-1u0v1av-s":`Agenti consentiti per il ruolo operatore`},help:{"v1-fvun18-4v":`Agenti disponibili quando questo ruolo crea sessioni o avvia esecuzioni: imposta "*" per consentire tutti gli agenti, elenca gli ID degli agenti per consentire solo quelli indicati oppure usa un elenco vuoto per disabilitare entrambe le operazioni.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esandbox":{label:{"v1-1h433k8-v":`Isolamento in sandbox del ruolo operatore`},help:{"v1-sknx21-66":`Isolamento dell'esecuzione per le nuove sessioni: "inherit" (predefinito) usa i criteri dell'agente; "required" impone in modo permanente l'uso di una sandbox, anche quando la modalità sandbox dell'agente è disattivata, e blocca l'esecuzione se il backend non è disponibile.`}},"gateway%2Eroles%2Edefinitions%2E*%2Escopes":{label:{"v1-1qejq9c-r":`Limite massimo degli ambiti di autorizzazione del ruolo operatore`},help:{"v1-1selr2i-4s":`Elenco chiuso degli ambiti di autorizzazione dell'operatore concessi come autorità massima di connessione per questo ruolo. Gli ambiti richiesti, associati, concessi tramite identità ed estesi vengono limitati a quelli presenti in questo elenco.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions":{label:{"v1-1t2w5en-s":`Accesso alle sessioni del ruolo operatore`},help:{"v1-hsoiop-45":`Autorizzazioni di condivisione delle sessioni concesse a questo ruolo per le sessioni create da altre persone autenticate; le sessioni personali restano accessibili al rispettivo proprietario.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions%2Eothers":{label:{"v1-lcjhtz-12":`Accesso del ruolo operatore alle altre sessioni`},help:{"v1-vf8umx-5r":`Accesso alle sessioni di altre persone: "none" le nasconde, "view" consente la lettura, "suggest" consente il flusso di suggerimenti e "write" consente la partecipazione. L'appartenenza esplicita a una sessione può concedere ulteriori autorizzazioni di accesso.`}},"gateway%2Etailscale":{label:{"v1-1gi7nvp-h":`Tailscale del Gateway`},help:{"v1-6ar9o-4x":`Impostazioni di integrazione con Tailscale per l'esposizione tramite Serve/Funnel e la gestione del ciclo di vita all'avvio e alla chiusura del Gateway. Lasciare disattivato a meno che la distribuzione non utilizzi intenzionalmente Tailscale per il traffico in ingresso.`}},"gateway%2Etailscale%2Emode":{label:{"v1-n7wv5k-m":`Modalità Tailscale del Gateway`},help:{"v1-6l2099-5a":`Modalità di pubblicazione Tailscale: "off", "serve" o "funnel" per l'esposizione privata o pubblica. Usare "serve" per l'accesso limitato alla tailnet e "funnel" solo quando è richiesta la raggiungibilità da Internet.`}},"gateway%2Etailscale%2EpreserveFunnel":{label:{"v1-h174rt-1d":`Protezione per la migrazione del Funnel esterno Tailscale del Gateway`},help:{"v1-1mntkor-7q":`Protezione per la migrazione deprecata per mode='serve'. Se un Funnel esterno punta ancora al listener ordinario del Gateway, OpenClaw lascia invariata l'esposizione e avvisa che solo i webhook autenticati tramite plugin restano utilizzabili finché non viene configurata l'autenticazione tramite password e la modalità non viene migrata a 'funnel'.`}},"gateway%2Eterminal":{label:{"v1-11obn6j-h":`Terminale operatore`},help:{"v1-18f5rgm-8b":`Terminale operatore fornito a Control UI e ai client mobili: una shell basata su PTY sull'host del Gateway, limitata alle sessioni operatore con ambito amministratore. Si avvia nell'area di lavoro dell'agente di destinazione e viene negato per gli agenti completamente isolati in sandbox (sandbox.mode 'all'), anziché fornire una shell host senza restrizioni.`}},"gateway%2Eterminal%2EdetachedSessionTimeoutSeconds":{label:{"v1-g247t4-16":`Timeout della sessione scollegata del terminale operatore`},help:{"v1-k6qbgr-9e":`Numero di secondi per cui una sessione del terminale rimane attiva dopo la perdita della connessione (sospensione del portatile, ricaricamento della pagina), consentendo di ricollegarsi tramite terminal.attach e visualizzare nuovamente l'output recente. Imposta 0 per terminare le sessioni non appena la connessione si interrompe. Valore predefinito: 300 (5 minuti). Le sessioni scollegate continuano a eseguire i propri comandi, quindi riduci questo valore sugli host condivisi o esposti.`}},"gateway%2Eterminal%2Eenabled":{label:{"v1-6xiiwa-p":`Terminale operatore abilitato`},help:{"v1-1nez06v-7p":`Abilita il terminale operatore per i client con ambito amministratore (valore predefinito: true). Espone una shell accessibile da browser o dispositivo mobile con l'ambiente del processo gateway; imposta false per disabilitarla nelle distribuzioni in cui gli operatori amministratori non devono avere accesso a una shell dell'host. Le modifiche vengono applicate senza riavviare il Gateway.`}},"gateway%2Eterminal%2Eshell":{label:{"v1-1qte0r1-n":`Shell del terminale operatore`},help:{"v1-19mfe6t-5i":`Eseguibile della shell avviato dal terminale operatore. Lascia il campo non impostato per usare la shell di accesso dell'host ($SHELL su Unix, %ComSpec% su Windows), oppure specifica un interprete per garantire un ambiente operatore uniforme.`}},"gateway%2Etls":{label:{"v1-103eqog-b":`TLS del Gateway`},help:{"v1-1dx77dq-4z":`Impostazioni del certificato e della chiave TLS per la terminazione HTTPS direttamente nel processo Gateway. Usa certificati espliciti in produzione ed evita l'esposizione di traffico in chiaro su reti non attendibili.`}},"gateway%2Etls%2EautoGenerate":{label:{"v1-17g0gmx-u":`Generazione automatica del certificato TLS del Gateway`},help:{"v1-1ld6uiu-4w":`Genera automaticamente una coppia locale di certificato e chiave TLS quando non sono configurati file espliciti. Usa questa opzione solo per configurazioni locali o di sviluppo e sostituisci la coppia con certificati reali per il traffico di produzione.`}},"gateway%2Etls%2EcaPath":{label:{"v1-h9qtpb-j":`Percorso CA TLS del Gateway`},help:{"v1-andqlu-52":`Percorso facoltativo del bundle CA per la verifica dei client o per requisiti di catene di attendibilità personalizzate al perimetro del Gateway. Usalo quando la distribuzione include una PKI privata o catene di certificati personalizzate.`}},"gateway%2Etls%2EcertPath":{label:{"v1-160lhdi-s":`Percorso del certificato TLS del Gateway`},help:{"v1-1wznaof-4q":`Percorso nel file system del file del certificato TLS usato dal Gateway quando TLS è abilitato. Usa percorsi di certificati gestiti e mantieni l'automazione del rinnovo allineata a questa posizione.`}},"gateway%2Etls%2Eenabled":{label:{"v1-1hdsowh-j":`TLS del Gateway abilitato`},help:{"v1-ykhwp0-4o":`Abilita la terminazione TLS sul listener del Gateway, consentendo ai client di connettersi direttamente tramite HTTPS/WSS. Mantieni questa opzione abilitata in caso di esposizione diretta a Internet o su qualsiasi confine con reti non attendibili.`}},"gateway%2Etls%2EkeyPath":{label:{"v1-1a645em-k":`Percorso della chiave TLS del Gateway`},help:{"v1-15knri0-4i":`Percorso nel file system del file della chiave privata TLS usata dal Gateway quando TLS è abilitato. Limita le autorizzazioni di accesso a questo file ed esegui la rotazione della chiave secondo i criteri di sicurezza adottati.`}},"gateway%2Etools":{label:{"v1-1b7s1vg-s":`Criteri di esposizione degli strumenti del Gateway`},help:{"v1-1ffol26-5a":`Criteri di autorizzazione e blocco dell'esposizione degli strumenti a livello di Gateway, che possono limitarne la disponibilità durante l'esecuzione indipendentemente dai profili degli agenti o degli strumenti. Usali per controlli di emergenza generali e per rafforzare la sicurezza in produzione.`}},"gateway%2Etools%2Eallow":{label:{"v1-tfn15c-m":`Elenco degli strumenti consentiti del Gateway`},help:{"v1-163khb1-4y":`Elenco esplicito degli strumenti consentiti a livello di Gateway, per rendere disponibile solo un insieme ristretto di strumenti durante l'esecuzione. Usalo in ambienti con restrizioni rigide, dove l'ambito degli strumenti deve essere controllato rigorosamente.`}},"gateway%2Etools%2Edeny":{label:{"v1-1a8nr3t-l":`Elenco degli strumenti bloccati del Gateway`},help:{"v1-1lhssnf-4o":`Elenco esplicito degli strumenti vietati a livello di Gateway per bloccare gli strumenti rischiosi anche se le policy di livello inferiore li consentono. Usa le regole di divieto per rispondere alle emergenze e rafforzare la difesa in profondità.`}},"gateway%2EtrustedProxies":{label:{"v1-8g5i45-r":`CIDR dei proxy attendibili del Gateway`},help:{"v1-n5zcvf-4f":`Elenco di CIDR/IP dei proxy a monte autorizzati a fornire intestazioni di inoltro dell'identità del client. Mantieni questo elenco ristretto per impedire ai nodi intermedi non attendibili di impersonare gli utenti.`}},hooks:{label:{"v1-j9ywl7-5":`Hook`},help:{"v1-1mzh0ry-5v":`Interfaccia di automazione dei webhook in ingresso per mappare gli eventi esterni ad azioni di risveglio o degli agenti in OpenClaw. Proteggila con controlli espliciti su token, sessioni e agenti prima di esporla al di fuori delle reti attendibili.`}},"hooks%2EallowedAgentIds":{label:{"v1-1dan5ok-n":`ID agente consentiti per gli hook`},help:{"v1-hree88-7c":`Elenco degli ID effettivi degli agenti che le richieste e le mappature degli hook possono usare come destinazione, incluso l'instradamento all'agente predefinito quando agentId è omesso. Usalo per limitare gli eventi di automazione ad agenti di servizio dedicati e ridurre l'impatto di un'eventuale esposizione di un token degli hook.`}},"hooks%2EallowedSessionKeyPrefixes":{label:{"v1-4rmaac-y":`Prefissi delle chiavi di sessione consentiti per gli hook`},help:{"v1-b346oh-4r":`Elenco dei prefissi delle chiavi di sessione accettati per le richieste di hook in ingresso quando sono abilitate le chiavi fornite dal chiamante. Usa prefissi restrittivi per impedire l'iniezione di chiavi di sessione arbitrarie.`}},"hooks%2EallowRequestSessionKey":{label:{"v1-u7mvac-v":`Consenti la chiave di sessione nelle richieste degli hook`},help:{"v1-11n9ps-52":`Se impostato su true, consente ai chiamanti di fornire una chiave di sessione nelle richieste degli hook, permettendo loro di controllare l'instradamento. Mantieni false a meno che gli integratori attendibili non abbiano esplicitamente bisogno di un raggruppamento personalizzato delle sessioni.`}},"hooks%2EdefaultSessionKey":{label:{"v1-bn0nb9-p":`Chiave di sessione predefinita degli hook`},help:{"v1-bzdgkn-57":`Chiave di sessione di ripiego usata per le consegne degli hook quando una richiesta non ne fornisce una tramite i canali consentiti. Usa una chiave stabile ma con ambito circoscritto per evitare di mescolare conversazioni di automazione non correlate.`}},"hooks%2Eenabled":{label:{"v1-1gty8ga-d":`Hook abilitati`},help:{"v1-1mixmjf-4n":`Abilita l'endpoint degli hook e la pipeline di esecuzione delle mappature per le richieste webhook in ingresso. Mantieni l'opzione disabilitata a meno che tu non stia instradando attivamente eventi esterni nel gateway.`}},"hooks%2Egmail":{label:{"v1-o8tl94-a":`Hook Gmail`},help:{"v1-4cibmt-4r":`Impostazioni di integrazione push di Gmail usate per le notifiche Pub/Sub e la gestione locale facoltativa dei callback. Ove possibile, limita questa integrazione ad account Gmail dedicati all'automazione.`}},"hooks%2Egmail%2Eaccount":{label:{"v1-11iw2zb-i":`Account dell'hook Gmail`},help:{"v1-12l1h96-4v":`Identificativo dell'account Google usato per le operazioni di monitoraggio e sottoscrizione di Gmail in questa integrazione hook. Usa un account di posta dedicato all'automazione per isolare le autorizzazioni operative.`}},"hooks%2Egmail%2EallowUnsafeExternalContent":{label:{"v1-6617w5-14":`Consenti contenuti esterni non sicuri nell'hook Gmail`},help:{"v1-1w3gdvs-55":`Se abilitata, consente l'elaborazione di contenuti esterni di Gmail sottoposti a una sanitizzazione meno rigorosa. Mantieni l'opzione disabilitata per impostazioni predefinite più sicure e abilitala solo per flussi di posta attendibili con trasformazioni controllate.`}},"hooks%2Egmail%2EhookUrl":{label:{"v1-1xypore-n":`URL di callback dell'hook Gmail`},help:{"v1-19fhn6q-4z":`URL di callback pubblico che Gmail o gli intermediari richiamano per inviare notifiche a questa pipeline hook. Proteggi questo URL con la convalida dei token e un'esposizione di rete limitata.`}},"hooks%2Egmail%2EincludeBody":{label:{"v1-x6h6eo-n":`Includi il corpo del messaggio nell'hook Gmail`},help:{"v1-14cf1c3-52":`Se true, recupera e include il contenuto del corpo delle email per la mappatura o l'elaborazione successiva da parte dell'agente. Mantieni false a meno che il testo del corpo non sia necessario, poiché questa opzione aumenta le dimensioni del payload e la sensibilità dei dati.`}},"hooks%2Egmail%2Elabel":{label:{"v1-75v7g6-g":`Etichetta dell'hook Gmail`},help:{"v1-9zpdg8-4g":`Filtro facoltativo per etichetta Gmail che limita i messaggi etichettati che attivano eventi hook. Mantieni i filtri restrittivi per evitare di sovraccaricare le automazioni con messaggi in arrivo non pertinenti.`}},"hooks%2Egmail%2EmaxBytes":{label:{"v1-nk9y9t-p":`Dimensione massima del corpo in byte per l'hook Gmail`},help:{"v1-2aaxx1-4b":`Numero massimo di byte del payload Gmail elaborati per evento quando includeBody è abilitato. Mantieni limiti contenuti per ridurre i costi e i rischi dell'elaborazione di messaggi di dimensioni eccessive.`}},"hooks%2Egmail%2Emodel":{label:{"v1-15jx1vj-p":`Modello alternativo per l'hook Gmail`},help:{"v1-1var65t-59":`Modello alternativo facoltativo per le esecuzioni attivate da Gmail, quando le automazioni della casella di posta richiedono un comportamento specifico del modello. Lascia non impostato per ereditare le impostazioni predefinite dell'agente, a meno che le attività della casella di posta non richiedano una specializzazione.`}},"hooks%2Egmail%2EpushToken":{label:{"v1-1u1u1rl-l":`Token push dell'hook Gmail`},help:{"v1-h1vx01-4o":`Token segreto condiviso richiesto nelle callback dell'hook push di Gmail prima di elaborare le notifiche. Usa la sostituzione tramite variabili d'ambiente e ruota il token se gli endpoint di callback sono esposti all'esterno.`}},"hooks%2Egmail%2ErenewEveryMinutes":{label:{"v1-bcw0nt-v":`Intervallo di rinnovo dell'hook Gmail (min)`},help:{"v1-pr1z9-49":`Frequenza di rinnovo in minuti delle sottoscrizioni di monitoraggio Gmail per impedirne la scadenza. Imposta un intervallo inferiore ai tempi di scadenza del provider e monitora gli errori di rinnovo nei log.`}},"hooks%2Egmail%2Eserve":{label:{"v1-djm9vi-n":`Server locale dell'hook Gmail`},help:{"v1-hom4wq-54":`Blocco di impostazioni del server di callback locale per ricevere direttamente le notifiche Gmail senza un livello di ingresso separato. Abilita solo quando questo processo deve gestire direttamente il traffico webhook in ingresso.`}},"hooks%2Egmail%2Eserve%2Ebind":{label:{"v1-1f9dlu6-u":`Indirizzo di ascolto del server hook Gmail`},help:{"v1-55bieu-4d":`Indirizzo di ascolto del server HTTP di callback Gmail locale utilizzato per gestire direttamente gli hook. Limita l'ascolto al loopback, a meno che non sia esplicitamente richiesto un ingresso esterno.`}},"hooks%2Egmail%2Eserve%2Epath":{label:{"v1-1fmz9ci-m":`Percorso del server hook Gmail`},help:{"v1-1jqhcw4-4h":`Percorso HTTP sul server di callback Gmail locale che accetta le notifiche push. Mantienilo coerente con la configurazione della sottoscrizione per evitare la perdita di eventi.`}},"hooks%2Egmail%2Eserve%2Eport":{label:{"v1-hvr7cq-m":`Porta del server hook Gmail`},help:{"v1-1yku7dz-43":`Porta del server HTTP di callback Gmail locale quando la modalità serve è abilitata. Usa una porta dedicata per evitare conflitti con le interfacce del gateway o di controllo.`}},"hooks%2Egmail%2Esubscription":{label:{"v1-19s0hm9-n":`Sottoscrizione hook Gmail`},help:{"v1-127h8vg-5b":`Sottoscrizione Pub/Sub utilizzata dal gateway per ricevere notifiche di modifica di Gmail dal topic configurato. Definisci chiaramente la responsabilità della sottoscrizione per evitare che più consumer entrino in competizione in modo imprevisto.`}},"hooks%2Egmail%2Etailscale":{label:{"v1-gxsxe8-k":`Tailscale per gli hook Gmail`},help:{"v1-7jzidp-4l":`Blocco di configurazione dell'esposizione tramite Tailscale per pubblicare i callback Gmail attraverso le route Serve/Funnel. Usa le modalità tailnet private prima di abilitare qualsiasi percorso di ingresso pubblico.`}},"hooks%2Egmail%2Etailscale%2Emode":{label:{"v1-1jsc22r-p":`Modalità Tailscale per gli hook Gmail`},help:{"v1-vhm395-4u":`Modalità di esposizione Tailscale per i callback di Gmail: "off", "serve" o "funnel". Usa "serve" per la consegna privata tramite tailnet e "funnel" solo quando è richiesto l'accesso in ingresso da Internet pubblico.`}},"hooks%2Egmail%2Etailscale%2Epath":{label:{"v1-1nkowt3-p":`Percorso Tailscale dell'hook Gmail`},help:{"v1-fr8qi-4m":`Percorso pubblicato da Tailscale Serve/Funnel per l'inoltro dei callback di Gmail, quando abilitato. Mantienilo allineato alla configurazione del webhook Gmail affinché le richieste raggiungano il gestore previsto.`}},"hooks%2Egmail%2Etailscale%2Etarget":{label:{"v1-1u75uvt-r":`Destinazione Tailscale dell'hook Gmail`},help:{"v1-1twwxge-47":`Destinazione del servizio locale verso cui Tailscale Serve/Funnel inoltra le richieste (ad esempio http://127.0.0.1:8787). Usa destinazioni di loopback esplicite per evitare ambiguità nell'instradamento.`}},"hooks%2Egmail%2Ethinking":{label:{"v1-rxxhgo-s":`Override del ragionamento per l'hook Gmail`},help:{"v1-17owk9q-4z":`Override del livello di ragionamento per le esecuzioni dell'agente attivate da Gmail: "off", "minimal", "low", "medium" o "high". Mantieni valori predefiniti contenuti per le automazioni ordinarie della posta in arrivo, per limitare costi e latenza.`}},"hooks%2Egmail%2Etopic":{label:{"v1-1n1wncx-o":`Topic Pub/Sub dell'hook Gmail`},help:{"v1-iled0e-4p":`Nome del topic Google Pub/Sub usato dal monitoraggio di Gmail per pubblicare notifiche di modifica per questo account. Assicurati che le autorizzazioni IAM del topic consentano a Gmail di pubblicare prima di abilitare il monitoraggio.`}},"hooks%2Einternal":{label:{"v1-1hsfqas-e":`Hook interni`},help:{"v1-piq9k-4v":`Impostazioni di esecuzione degli hook interni per i gestori di eventi integrati o personalizzati caricati dai percorsi dei moduli. Usale per automazioni affidabili eseguite nello stesso processo e limita rigorosamente l'ambito di caricamento dei gestori.`}},"hooks%2Einternal%2Eenabled":{label:{"v1-1kouv99-m":`Hook interni abilitati`},help:{"v1-1wv0289-4c":`Abilita l'elaborazione degli hook interni e delle voci configurate nel runtime degli hook interni. Lasciare disabilitato, a meno che gli hook interni non siano stati configurati intenzionalmente.`}},"hooks%2Einternal%2Eentries":{label:{"v1-1coawdn-l":`Voci degli hook interni`},help:{"v1-1ovi38l-4o":`Record delle voci degli hook interni configurati, usati per registrare gestori concreti nel runtime e metadati. Mantenere le voci esplicite e sotto controllo di versione per rendere verificabile il comportamento in produzione.`}},"hooks%2Einternal%2Eload":{label:{"v1-e71kzu-k":`Caricatore degli hook interni`},help:{"v1-11re5ph-4p":`Impostazioni del caricatore degli hook interni che controllano dove vengono individuati i moduli dei gestori all'avvio. Limitare le directory radice di caricamento per ridurre conflitti accidentali tra moduli o l'occultamento di un modulo da parte di un altro.`}},"hooks%2Einternal%2Eload%2EextraDirs":{label:{"v1-1oj9uqa-v":`Directory aggiuntive degli hook interni`},help:{"v1-1xfdqxg-4c":`Directory aggiuntive in cui cercare i moduli degli hook interni oltre ai percorsi di caricamento predefiniti. Mantenerne il numero al minimo e sotto controllo per ridurre l'occultamento accidentale di un modulo da parte di un altro.`}},"hooks%2Emappings":{label:{"v1-16wwkft-d":`Mappature degli hook`},help:{"v1-frhp3v-5i":`Regole di mappatura ordinate che identificano le richieste hook in ingresso corrispondenti e scelgono azioni di risveglio o dell'agente, con instradamento della consegna facoltativo. Inserire prima le mappature specifiche per evitare che regole con criteri troppo ampi intercettino tutto.`}},"hooks%2Emappings%5B%5D%2Eaction":{label:{"v1-bvm5m2-j":`Azione della mappatura hook`},help:{"v1-1r5zt5f-5f":`Tipo di azione della mappatura: "wake" avvia il flusso di risveglio dell'agente, mentre "agent" invia direttamente all'agente per l'elaborazione. Usare "agent" per l'esecuzione immediata e "wake" quando si preferisce l'elaborazione basata sul battito periodico.`}},"hooks%2Emappings%5B%5D%2EagentId":{label:{"v1-r93mi6-l":`ID agente della mappatura hook`},help:{"v1-l0uioz-4y":`ID dell'agente di destinazione per l'esecuzione della mappatura quando l'instradamento delle azioni non deve usare i valori predefiniti. Usa agenti di automazione dedicati per isolare il comportamento dei webhook dalle sessioni interattive degli operatori.`}},"hooks%2Emappings%5B%5D%2EallowUnsafeExternalContent":{label:{"v1-1nlag5p-16":`Consenti contenuti esterni non sicuri nella mappatura dell'hook`},help:{"v1-1np9426-57":`Se impostato su true, il contenuto della mappatura può includere nei messaggi generati dati di payload esterni sottoposti a una sanitizzazione meno rigorosa. Mantieni false come valore predefinito e abilita l'opzione solo per fonti attendibili con logica di trasformazione verificata.`}},"hooks%2Emappings%5B%5D%2Echannel":{label:{"v1-f719ab-t":`Canale di consegna della mappatura dell'hook`},help:{"v1-oz7pu5-5s":`Sostituzione del canale di consegna per gli output della mappatura (ad esempio "last", "telegram", "discord", "slack", "signal", "imessage" o "msteams"). Specifica esplicitamente le sostituzioni del canale per evitare invii accidentali su altri canali.`}},"hooks%2Emappings%5B%5D%2Edeliver":{label:{"v1-2h4axx-q":`Consegna la risposta della mappatura dell'hook`},help:{"v1-12tbbam-5o":`Controlla se i risultati dell'esecuzione della mappatura vengono inviati a una destinazione del canale oppure elaborati senza notifica. Disabilita la consegna per le automazioni in background che non devono pubblicare output visibili agli utenti.`}},"hooks%2Emappings%5B%5D%2EforEach":{label:{"v1-fzd0ar-o":`Chiave di distribuzione della mappatura dell'hook`},help:{"v1-1d593op-7e":`Chiave dell'array al livello principale del payload su cui la mappatura distribuisce le azioni: ogni elemento attiva una propria azione e i modelli o le trasformazioni ricevono un payload il cui array contiene solo l'elemento corrente. La preimpostazione Gmail usa forEach: messages, così gli invii push in batch attivano un'esecuzione per ogni email.`}},"hooks%2Emappings%5B%5D%2Eid":{label:{"v1-1nctnx-f":`ID della mappatura dell'hook`},help:{"v1-q1t4zw-57":`Identificatore stabile facoltativo per una voce di mappatura degli hook, utilizzato per audit, risoluzione dei problemi e aggiornamenti mirati. Usa ID univoci affinché i log e le differenze di configurazione possano fare riferimento alle mappature senza ambiguità.`}},"hooks%2Emappings%5B%5D%2Ematch":{label:{"v1-rbsioh-i":`Corrispondenza della mappatura degli hook`},help:{"v1-6u73k2-5a":`Oggetto che raggruppa i predicati di corrispondenza della mappatura, come percorso e origine, prima che venga applicato l'instradamento delle azioni. Mantieni specifici i criteri di corrispondenza per evitare che il traffico webhook non pertinente attivi le automazioni.`}},"hooks%2Emappings%5B%5D%2Ematch%2Epath":{label:{"v1-mc6fc4-n":`Percorso di corrispondenza della mappatura degli hook`},help:{"v1-1d7dc5j-4k":`Condizione di corrispondenza del percorso per una mappatura degli hook, solitamente confrontata con il percorso della richiesta in ingresso. Usala per differenziare il comportamento delle automazioni in base alle famiglie di percorsi degli endpoint webhook.`}},"hooks%2Emappings%5B%5D%2Ematch%2Esource":{label:{"v1-1mx72t2-p":`Origine di corrispondenza della mappatura degli hook`},help:{"v1-177zgy7-52":`Condizione di corrispondenza dell'origine per una mappatura degli hook, in genere impostata da metadati attendibili a monte o dalla logica dell'adattatore. Usa identificatori di origine stabili affinché l'instradamento rimanga deterministico anche nei tentativi successivi.`}},"hooks%2Emappings%5B%5D%2EmessageTemplate":{label:{"v1-1h1bgln-t":`Modello di messaggio della mappatura degli hook`},help:{"v1-ggqszl-5c":`Modello per trasformare i dati strutturati in ingresso della mappatura nel contenuto finale del messaggio inviato al percorso dell'azione di destinazione. Mantieni i modelli deterministici affinché l'analisi e il comportamento a valle rimangano stabili.`}},"hooks%2Emappings%5B%5D%2Emodel":{label:{"v1-17bx393-r":`Sostituzione del modello della mappatura degli hook`},help:{"v1-10qyo4j-5e":`Sostituzione facoltativa del modello per le esecuzioni attivate dalla mappatura, quando l'automazione deve usare un modello diverso da quello predefinito dell'agente. Usala con moderazione per mantenere prevedibile il comportamento nelle varie esecuzioni della mappatura.`}},"hooks%2Emappings%5B%5D%2Ename":{label:{"v1-gos70z-h":`Nome della mappatura dell'hook`},help:{"v1-zrd9tn-4v":`Nome visualizzato della mappatura, leggibile dall'utente, usato nella diagnostica e nelle interfacce di configurazione per gli operatori. Usa nomi concisi e descrittivi per rendere chiaro lo scopo dell'instradamento durante l'analisi degli incidenti.`}},"hooks%2Emappings%5B%5D%2EsessionKey":{label:{"v1-1g7byfn-o":`Chiave di sessione della mappatura dell'hook`},help:{"v1-lfnt1n-58":`Sostituzione esplicita della chiave di sessione per i messaggi recapitati tramite la mappatura, per controllare la continuità del thread. Usa chiavi stabili con un ambito definito per correlare gli eventi ripetuti senza coinvolgere conversazioni non pertinenti.`}},"hooks%2Emappings%5B%5D%2EsessionMode":{label:{"v1-p4nrxz-p":`Modalità di sessione della mappatura dell'hook`},help:{"v1-1ggtdze-5k":`Controlla la continuità della sessione della mappatura: "isolated" avvia una nuova sessione di esecuzione, mentre "persistent" riutilizza la sessionKey risolta. Mantieni isolated a meno che l'integrazione non richieda intenzionalmente un contesto persistente.`}},"hooks%2Emappings%5B%5D%2EtextTemplate":{label:{"v1-1jch0ob-q":`Modello di testo della mappatura dell'hook`},help:{"v1-1rg732b-4y":`Modello alternativo di solo testo usato quando la visualizzazione avanzata del payload non è desiderata o supportata. Usalo per fornire una stringa di riepilogo concisa e coerente per le interfacce di recapito in chat.`}},"hooks%2Emappings%5B%5D%2Ethinking":{label:{"v1-omlp34-u":`Sostituzione del ragionamento della mappatura dell'hook`},help:{"v1-17hq8me-57":`Override facoltativo dell'impegno di ragionamento per le esecuzioni attivate dalla mappatura, per bilanciare latenza e profondità di ragionamento. Mantieni un livello basso o minimo per gli hook ad alto volume, a meno che non sia chiaramente necessario un ragionamento più approfondito.`}},"hooks%2Emappings%5B%5D%2EtimeoutSeconds":{label:{"v1-9tp4s7-q":`Timeout della mappatura hook (sec)`},help:{"v1-1r44ox2-4i":`Durata massima consentita per l'esecuzione dell'azione di mappatura prima che intervenga la gestione del timeout. Usa limiti più restrittivi per le sorgenti webhook ad alto volume per evitare accumuli in coda.`}},"hooks%2Emappings%5B%5D%2Eto":{label:{"v1-hpcs3s-x":`Destinazione di consegna della mappatura hook`},help:{"v1-1p7928e-55":`Identificatore della destinazione all'interno del canale selezionato, quando le risposte della mappatura devono essere instradate verso una destinazione fissa. Verifica i formati di destinazione specifici del provider prima di abilitare le mappature in produzione.`}},"hooks%2Emappings%5B%5D%2Etransform":{label:{"v1-yiku9o-m":`Trasformazione della mappatura hook`},help:{"v1-14igxpm-5m":`Blocco di configurazione della trasformazione che definisce la preelaborazione tramite modulo/export prima della gestione dell'azione di mappatura. Usa trasformazioni solo da percorsi di codice sottoposti a revisione e mantieni un comportamento deterministico per un'automazione ripetibile.`}},"hooks%2Emappings%5B%5D%2Etransform%2Eexport":{label:{"v1-10vpr1c-l":`Export della trasformazione hook`},help:{"v1-atn8v-4b":`Export denominato da richiamare dal modulo di trasformazione; se omesso, viene usato l'export predefinito del modulo. Impostalo quando un file contiene più gestori di trasformazione.`}},"hooks%2Emappings%5B%5D%2Etransform%2Emodule":{label:{"v1-qukz8e-l":`Modulo di trasformazione hook`},help:{"v1-56futq-4v":`Percorso relativo del modulo di trasformazione caricato da hooks.transformsDir per riscrivere i payload in ingresso prima della consegna. Mantieni i moduli locali, revisionati e privi di sequenze di attraversamento dei percorsi.`}},"hooks%2Emappings%5B%5D%2EwakeMode":{label:{"v1-vk3gk3-m":`Modalità di risveglio della mappatura hook`},help:{"v1-1dzqfnw-59":`Modalità di pianificazione del risveglio: "now" attiva il risveglio immediatamente, mentre "next-heartbeat" lo rimanda al ciclo heartbeat successivo. Usa la modalità differita per le automazioni a priorità inferiore che possono tollerare un lieve ritardo.`}},"hooks%2Epath":{label:{"v1-1uhbsf3-j":`Percorso dell'endpoint degli hook`},help:{"v1-1l9ijzv-4u":"Percorso HTTP usato dall'endpoint degli hook (ad esempio `/hooks`) sul server di controllo del gateway. Usa un percorso non facilmente indovinabile e abbinalo alla convalida del token per una difesa a più livelli."}},"hooks%2Epresets":{label:{"v1-4shxcz-d":`Preimpostazioni degli hook`},help:{"v1-dp8m0l-4v":`Pacchetti di preimpostazioni degli hook con nome, applicati al caricamento per inizializzare le mappature standard e i comportamenti predefiniti. Mantieni esplicito l'uso delle preimpostazioni, così gli operatori possono verificare quali automazioni sono attive.`}},"hooks%2Etoken":{label:{"v1-1uqdexy-g":`Token di autenticazione degli hook`},help:{"v1-1ihf6mv-82":`Token bearer condiviso verificato dal punto di ingresso degli hook per autenticare le richieste prima dell'esecuzione delle mappature. Considera i possessori del token come chiamanti pienamente attendibili per l'interfaccia di ingresso degli hook, non come un ruolo separato da quello del proprietario. Usa la sostituzione tramite variabili d'ambiente e ruota il token regolarmente quando gli endpoint webhook sono accessibili da Internet.`}},"hooks%2EtransformsDir":{label:{"v1-1sc7ulb-q":`Directory delle trasformazioni degli hook`},help:{"v1-1ayj9p0-4t":`Directory di base per i moduli di trasformazione degli hook a cui fanno riferimento i percorsi transform.module delle mappature. Usa una directory di un repository controllato, così le importazioni dinamiche rimangono verificabili e prevedibili.`}},logging:{label:{"v1-rq08xq-7":`Registrazione dei log`},help:{"v1-11an9pb-5e":`Controlli del comportamento di logging per gravità, destinazioni di output, formattazione e oscuramento dei dati sensibili. Mantieni livelli e oscuramento sufficientemente rigorosi per l'ambiente di produzione, preservando al contempo informazioni diagnostiche utili.`}},"logging%2Eaudit":{label:{"v1-7v96zt-c":`Registro di audit`},help:{"v1-1lauvy2-6w":`Cronologia di audit limitata ai soli metadati e con limiti di conservazione, consultabile dagli operatori. I record delle esecuzioni e degli strumenti sono abilitati per impostazione predefinita; i metadati del ciclo di vita dei messaggi richiedono un'attivazione separata e hanno implicazioni per la privacy. La scrittura in background avviene secondo il principio del massimo sforzo e non costituisce un archivio di conformità senza perdite.`}},"logging%2Eaudit%2Eenabled":{label:{"v1-pxk7dc-k":`Registro di audit abilitato`},help:{"v1-snknxb-4v":`Registra i nuovi eventi di audit relativi a esecuzioni, strumenti e messaggi abilitati. Valore predefinito: true. Le modifiche si applicano immediatamente; le scritture accettate vengono completate e le righe conservate restano consultabili fino alla scadenza.`}},"logging%2Eaudit%2EexecutionIdentity":{label:{"v1-163ujga-o":`Audit dell'identità di esecuzione`},help:{"v1-1ucirwv-5b":`Conserva entro limiti definiti i dati di attribuzione dell'identità di esecuzione per l'ispezione di una specifica esecuzione. Valore predefinito: false. Richiede logging.audit.enabled e si applica alle nuove esecuzioni ammesse; i contesti esistenti restano invariati.`}},"logging%2Eaudit%2Emessages":{label:{"v1-1bguzvj-j":`Ambito di audit dei messaggi`},help:{"v1-1yg4lc3-76":`Controlla i record del ciclo di vita dei messaggi, privi di contenuto: "off" (valore predefinito), "direct" solo per le conversazioni dirette note oppure "all" per le conversazioni dirette, di gruppo, di canale e di tipo sconosciuto. Richiede logging.audit.enabled. Le modifiche si applicano agli eventi successivi del ciclo di vita.`}},"logging%2EconsoleLevel":{label:{"v1-1mambfm-h":`Livello di log della console`},help:{"v1-16badbd-5u":`Soglia di log specifica per la console: "silent", "fatal", "error", "warn", "info", "debug" o "trace" per controllare l'output del terminale. Usala per ridurre i messaggi nella console locale mantenendo, se necessario, log più dettagliati su file.`}},"logging%2EconsoleStyle":{label:{"v1-1buy3td-h":`Stile dei log della console`},help:{"v1-d7u0iq-3q":`Stile del formato di output della console: "pretty" o "json". Usa json per le pipeline di analisi automatica e pretty per i flussi di lavoro nel terminale orientati alla lettura umana.`}},"logging%2Efile":{label:{"v1-1o25uj4-d":`Percorso del file di log`},help:{"v1-16gaitv-4w":`Percorso facoltativo del file in cui salvare i log, in aggiunta o in alternativa ai log della console. Usa un percorso gestito e scrivibile e allinea la conservazione e la rotazione dei log ai tuoi criteri operativi.`}},"logging%2Elevel":{label:{"v1-1vskr8z-9":`Livello di log`},help:{"v1-1r5yku0-5o":`Soglia principale del livello di log per l'output del logger in fase di esecuzione: "silent", "fatal", "error", "warn", "info", "debug" o "trace". Mantieni "info" o "warn" in produzione e usa debug/trace solo durante le indagini.`}},"logging%2EredactPatterns":{label:{"v1-17ykioa-p":`Pattern di oscuramento personalizzati`},help:{"v1-1esa6eg-7k":`Le stringhe regex personalizzate sostituiscono l'elenco di stringhe predefinito per l'output di log e trascrizioni e integrano le regole di sicurezza per interfaccia utente, strumenti e diagnostica. Le protezioni integrate per il corpo dei moduli, i dati di autenticazione strutturati e le chiavi AWS isolate si applicano sempre. Usa questa opzione per mascherare token e identificatori specifici della distribuzione.`}},mcp:{label:{"v1-4jhiv7-3":`MCP`},help:{"v1-cyzwkt-51":`Definizioni globali dei server MCP gestite da OpenClaw. OpenClaw incorporato e altri adattatori di runtime possono utilizzare questi server senza salvarli nelle impostazioni di progetto gestite dal runtime.`}},"mcp%2Eapps":{label:{"v1-1p7rgdd-8":`App MCP`},help:{"v1-amyd91-38":`Supporto dell'interfaccia di MCP Apps. Quando è abilitato, i server MCP configurati possono fornire viste HTML interattive per i risultati dei loro strumenti.`}},"mcp%2Eapps%2Eenabled":{label:{"v1-15iqtvs-g":`MCP Apps abilitato`},help:{"v1-ghqy98-3w":`Rendering di MCP Apps e bridge tra app e server, attivabili su richiesta. Mantieni questa opzione disabilitata a meno che tu non ritenga affidabili i server MCP configurati che forniscono risorse per l'interfaccia delle app.`}},"mcp%2Eapps%2EsandboxOrigin":{label:{"v1-es3gf8-n":`Origine della sandbox di MCP Apps`},help:{"v1-1sxv3mf-6v":`Origine HTTP(S) pubblica dedicata opzionale per MCP Apps. Usala dietro un proxy inverso o un terminatore TLS e inoltra il traffico esclusivamente alla porta configurata per la sandbox di MCP Apps. Deve essere diversa dall'origine di Control UI e non deve fornire contenuti che richiedono autenticazione.`}},"mcp%2Eapps%2EsandboxPort":{label:{"v1-15qo425-l":`Porta della sandbox di MCP Apps`},help:{"v1-1b8n71l-4p":`Porta di ascolto dedicata alla sandbox di MCP Apps. Per impostazione predefinita, corrisponde alla porta del Gateway incrementata di uno. Imposta una porta libera se un altro servizio locale o profilo Gateway utilizza già quella porta.`}},"mcp%2Eservers":{label:{"v1-1mnexav-b":`Server MCP`},help:{"v1-157ozoz-42":`Definizioni dei server MCP con nome. OpenClaw le memorizza nella propria configurazione e gli adattatori di runtime decidono quali trasporti sono supportati al momento dell'esecuzione.`}},"mcp%2Eservers%2E*%2Eauth":{label:{"v1-4i7ar4-f":`Autenticazione del server MCP`}},"mcp%2Eservers%2E*%2Eclient_cert":{label:{"v1-8xj19d-m":`Certificato client MCP`}},"mcp%2Eservers%2E*%2Eclient_key":{label:{"v1-14y3g3x-e":`Chiave client MCP`}},"mcp%2Eservers%2E*%2EclientCert":{label:{"v1-8xj19d-m":`Certificato client MCP`}},"mcp%2Eservers%2E*%2EclientKey":{label:{"v1-14y3g3x-e":`Chiave client MCP`}},"mcp%2Eservers%2E*%2Ecodex":{label:{"v1-1abejxp-k":`Proiezione MCP di Codex`},help:{"v1-slcmq1-6x":`Metadati di proiezione OpenClaw solo per i thread app-server di Codex. Non influiscono sulle sessioni ACP né sulla configurazione generica dell'harness di Codex. Ometti questo blocco per mantenere il server disponibile a tutti gli agenti app-server di Codex con il comportamento di approvazione MCP predefinito di Codex.`}},"mcp%2Eservers%2E*%2Ecodex%2Eagents":{label:{"v1-tu0z1y-g":`Agenti MCP di Codex`},help:{"v1-8q98n8-67":`ID facoltativi e non vuoti degli agenti OpenClaw che devono ricevere questo server MCP nella configurazione dei thread app-server di Codex. Gli elenchi vuoti, contenenti solo spazi o non validi bloccano l'accesso per sicurezza; se l'elenco viene omesso, il server viene proiettato per tutti gli agenti app-server di Codex.`}},"mcp%2Eservers%2E*%2Ecodex%2Edefault_tools_approval_mode":{label:{"v1-uwmd-n":`Approvazione degli strumenti MCP di Codex`},help:{"v1-1xql0qr-3d":`Nome nativo di Codex per la stessa modalità di approvazione degli strumenti MCP per server. Preferisci defaultToolsApprovalMode nella configurazione di OpenClaw.`}},"mcp%2Eservers%2E*%2Ecodex%2EdefaultToolsApprovalMode":{label:{"v1-uwmd-n":`Approvazione degli strumenti MCP di Codex`},help:{"v1-y5vsqq-3s":`Modalità facoltativa di approvazione degli strumenti MCP di Codex per questo server: "auto", "prompt" o "approve". Usala solo per i server MCP che consideri esplicitamente attendibili.`}},"mcp%2Eservers%2E*%2EconnectionTimeoutMs":{label:{"v1-1ofxxy1-o":`Timeout di connessione MCP (ms)`}},"mcp%2Eservers%2E*%2Eenabled":{label:{"v1-hkfmxj-i":`Server MCP abilitato`}},"mcp%2Eservers%2E*%2Eoauth":{label:{"v1-j06h60-9":`OAuth MCP`}},"mcp%2Eservers%2E*%2Eoauth%2EauthProfileId":{label:{"v1-1xxlhb-m":`Profilo di autenticazione OAuth MCP`},help:{"v1-fcrb4u-5z":`ID del profilo di autenticazione con supporto al rinnovo, usato per inserire il token bearer corrente in questo server MCP remoto. Se impostato, OpenClaw risolve e rinnova il profilo in fase di esecuzione e non trasmette a valle i dati necessari al rinnovo.`}},"mcp%2Eservers%2E*%2Eoauth%2EclientMetadataUrl":{label:{"v1-1d7wndt-t":`URL dei metadati del client OAuth MCP`}},"mcp%2Eservers%2E*%2Eoauth%2Eidentity":{label:{"v1-1l48ph6-i":`Identità OAuth MCP`},help:{"v1-1ie6ys7-59":`Titolarità delle credenziali OAuth per questo server. Ometti questo campo o usa "shared" per le credenziali gestite dall'operatore; usa "per-requester" per consentire a ogni mittente autenticato di collegare il proprio account.`}},"mcp%2Eservers%2E*%2Eoauth%2EredirectUrl":{label:{"v1-1yf3yu9-m":`URL di reindirizzamento OAuth MCP`}},"mcp%2Eservers%2E*%2Eoauth%2Escope":{label:{"v1-xvnbwc-f":`Ambito OAuth MCP`}},"mcp%2Eservers%2E*%2ErequestTimeoutMs":{label:{"v1-7skvfk-o":`Timeout delle richieste MCP (ms)`}},"mcp%2Eservers%2E*%2Essl_verify":{label:{"v1-16l2l8l-k":`Verifica TLS MCP`}},"mcp%2Eservers%2E*%2EsslVerify":{label:{"v1-16l2l8l-k":`Verifica TLS MCP`}},"mcp%2Eservers%2E*%2Esupports_parallel_tool_calls":{label:{"v1-14b32qt-n":`Chiamate parallele agli strumenti MCP`}},"mcp%2Eservers%2E*%2EsupportsParallelToolCalls":{label:{"v1-14b32qt-n":`Chiamate parallele agli strumenti MCP`}},"mcp%2Eservers%2E*%2EtoolFilter":{label:{"v1-m19ao9-i":`Selezione degli strumenti MCP`},help:{"v1-10poyzb-4v":`Selezione degli strumenti MCP per ciascun server. Usa include per esporre solo gli strumenti MCP con i nomi selezionati, oppure exclude per nasconderli. Le voci accettano nomi esatti e semplici pattern glob con '*'.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Eexclude":{label:{"v1-bikffc-i":`Strumenti MCP esclusi`},help:{"v1-ijrc5y-1u":`Nomi esatti degli strumenti MCP o semplici pattern glob con '*' da nascondere da questo server.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Einclude":{label:{"v1-qa5hua-i":`Strumenti MCP inclusi`},help:{"v1-89fdfq-3o":`Nomi esatti degli strumenti MCP o semplici pattern glob con '*' da esporre da questo server. Se omesso, tutti gli strumenti del server restano disponibili, salvo quelli esclusi.`}},"mcp%2EsessionIdleTtlMs":{label:{"v1-1teh0v2-p":`TTL di inattività della sessione MCP (ms)`},help:{"v1-j9si74-87":`Rimozione facoltativa per inattività dei runtime MCP delle sessioni OpenClaw, in millisecondi. Se non impostato o pari a 0, mantiene attivi i runtime fino alla pulizia della sessione o all'arresto del Gateway. I valori positivi vengono arrotondati per difetto; i lease attivi e le acquisizioni in sospeso impediscono la rimozione. I runtime associati a un'esecuzione vengono comunque dismessi al termine della relativa esecuzione singola.`}},memory:{label:{"v1-oopaku-6":`Memoria`},help:{"v1-1wlx40m-13":`Configurazione della memoria integrata (globale).`}},"memory%2Ecitations":{label:{"v1-1cdo86v-l":`Modalità citazioni della memoria`},help:{"v1-1q6dxr5-4u":`Controlla la visibilità delle citazioni nelle risposte: "auto" mostra le citazioni quando sono utili, "on" le mostra sempre e "off" le nasconde. Mantieni "auto" come impostazione predefinita per un rapporto segnale-rumore equilibrato.`}},"memory%2Esearch":{label:{"v1-dvkpxe-d":`Ricerca nella memoria`},help:{"v1-1ukbud1-25":`Ricerca vettoriale in MEMORY.md e memory/*.md (sono supportate impostazioni specifiche per agente).`}},"memory%2Esearch%2Ecache%2Eenabled":{label:{"v1-kv1t3d-t":`Cache degli embedding per la ricerca nella memoria`},help:{"v1-d8h2e4-5b":`Memorizza nella cache SQLite gli embedding calcolati dei segmenti per velocizzare la reindicizzazione e gli aggiornamenti incrementali (valore predefinito: true). Mantieni questa opzione abilitata, salvo quando verifichi la correttezza della cache o vuoi ridurre al minimo l'uso del disco.`}},"memory%2Esearch%2EdocumentInputType":{label:{"v1-mmpk8t-x":`Tipo di input dei documenti per la ricerca nella memoria`},help:{"v1-1ui33sv-5f":"Valore `input_type` facoltativo e specifico del provider per gli embedding della memoria relativi ai documenti e all'indicizzazione. Usalo con endpoint di embedding asimmetrici compatibili con OpenAI che richiedono un'etichetta per un passaggio o un documento."}},"memory%2Esearch%2Eenabled":{label:{"v1-ed34tb-k":`Abilita la ricerca nella memoria`},help:{"v1-14f11b9-4t":`Interruttore principale per l'indicizzazione e il recupero dei contenuti tramite la ricerca nella memoria in questo profilo agente. Mantienilo abilitato per il richiamo semantico e disabilitalo quando desideri risposte completamente prive di stato.`}},"memory%2Esearch%2Eexperimental%2EsessionMemory":{label:{"v1-1jhaosz-16":`Indice delle sessioni per la ricerca nella memoria (sperimentale)`},help:{"v1-qvhv8z-3i":`Indicizza le trascrizioni delle sessioni per la ricerca nella memoria. Mantieni questa impostazione avanzata di override quando l'ereditarietà del richiamo differisce tra il livello radice e quello dei singoli agenti.`}},"memory%2Esearch%2EextraPaths":{label:{"v1-1ommwo8-i":`Percorsi aggiuntivi della memoria`},help:{"v1-ojqokq-7i":`Aggiunge directory o file .md all'indice della memoria, oltre ai file di memoria predefiniti. Le voci possono essere stringhe di percorso oppure oggetti con un pattern glob relativo alla radice. Quando la memoria multimodale è abilitata, anche i file immagine/audio corrispondenti in questi percorsi possono essere indicizzati.`}},"memory%2Esearch%2EextraPaths%2E*%2Epath":{label:{"v1-1htq423-h":`Percorso aggiuntivo della memoria`},help:{"v1-b9mbq8-3m":`Imposta la directory o il file aggiuntivo della memoria. I percorsi relativi vengono risolti a partire dall'area di lavoro dell'agente; le voci che indicano direttamente un file vengono indicizzate esattamente come specificato.`}},"memory%2Esearch%2EextraPaths%2E*%2Epattern":{label:{"v1-eunp4t-p":`Pattern del percorso aggiuntivo della memoria`},help:{"v1-j8br1v-4e":`Limita una voce di directory ai file supportati che corrispondono a questo glob relativo alla radice, ad esempio "runbooks/**/*.md". Omettilo per cercare ricorsivamente tutti i file supportati.`}},"memory%2Esearch%2Efallback":{label:{"v1-nj3gc-m":`Fallback della ricerca in memoria`},help:{"v1-1r6368w-6p":`Provider di riserva utilizzato quando gli embedding primari non riescono: "openai", "gemini", "voyage", "mistral", "bedrock", "lmstudio", "ollama", "local" o "none". Imposta un fallback effettivo per garantire l'affidabilità in produzione; usa "none" solo se preferisci errori espliciti.`}},"memory%2Esearch%2EinputType":{label:{"v1-aslwem-o":`Tipo di input della ricerca in memoria`},help:{"v1-26vbwe-5u":"Usa questo valore facoltativo `input_type`, specifico del provider, solo quando la stessa etichetta deve essere applicata alle richieste di embedding sia delle query sia dei documenti. Per i provider asimmetrici, preferisci queryInputType e documentInputType."}},"memory%2Esearch%2Elocal%2EmodelPath":{label:{"v1-1jkif8j-q":`Percorso del modello di embedding locale`},help:{"v1-13ymbnt-5q":"Specifica l'origine del modello di embedding locale per la ricerca in memoria locale, ad esempio il percorso di un file GGUF o un URI `hf:`. Usa questa opzione solo quando provider è `local` e verifica la compatibilità del modello prima di ricostruire indici di grandi dimensioni."}},"memory%2Esearch%2Emodel":{label:{"v1-1sfre8j-j":`Modello della ricerca in memoria`},help:{"v1-11pohrl-59":`Modello di embedding alternativo utilizzato dal provider di memoria selezionato quando è richiesto un modello diverso da quello predefinito. Impostalo solo se devi regolare esplicitamente la qualità del recupero o i costi rispetto alle impostazioni predefinite del provider.`}},"memory%2Esearch%2Emultimodal":{label:{"v1-1lnhiq0-o":`Ricerca in memoria multimodale`},help:{"v1-1jn02s-9e":'Impostazioni facoltative della memoria multimodale per indicizzare file immagine e audio dai percorsi aggiuntivi configurati. Mantieni questa opzione disattivata a meno che il modello di embedding non supporti esplicitamente gli embedding tra modalità diverse e imposta `memory.search.fallback` su "none" mentre è attiva. I file corrispondenti vengono caricati sul provider di embedding remoto configurato durante l\'indicizzazione.'}},"memory%2Esearch%2Emultimodal%2Eenabled":{label:{"v1-vp9cgj-v":`Abilita la ricerca multimodale nella memoria`},help:{"v1-1dk5d7o-7e":`Abilita l'indicizzazione di immagini e audio nella memoria da extraPaths. Attualmente richiede Gemini embedding-2, mantiene le directory radice predefinite della memoria limitate ai soli file Markdown, disabilita i provider di fallback per la ricerca nella memoria e carica i contenuti binari corrispondenti sul provider remoto di embedding configurato.`}},"memory%2Esearch%2Emultimodal%2EmaxFileBytes":{label:{"v1-ewn32n-13":`Dimensione massima in byte dei file multimodali per la ricerca nella memoria`},help:{"v1-1mmdrvk-5d":`Imposta il numero massimo di byte consentiti per ciascun file multimodale, oltre il quale il file viene ignorato durante l'indicizzazione della memoria. Usa questo limite per contenere i costi di caricamento e la latenza di indicizzazione, oppure aumentalo per brevi clip audio di alta qualità.`}},"memory%2Esearch%2Emultimodal%2Emodalities":{label:{"v1-ako4xr-z":`Modalità multimodali per la ricerca nella memoria`},help:{"v1-alp4vh-4l":`Seleziona i tipi di file multimodali da indicizzare da extraPaths: "image", "audio" o "all". Limita la selezione per evitare di indicizzare involontariamente grandi raccolte di file binari.`}},"memory%2Esearch%2EoutputDimensionality":{label:{"v1-9cim9y-z":`Dimensionalità di output per la ricerca nella memoria`},help:{"v1-1f7zu53-93":`Sovrascrive la dimensione del vettore di output per gli embedding della memoria in base al provider. I modelli Gemini supportano da 128 a 3072 dimensioni e consigliano 768, 1536 o 3072; le famiglie Bedrock come Titan V2, Cohere V4 e Nova prevedono dimensioni consentite proprie. La modifica comporta una reindicizzazione completa, poiché le dimensioni dei vettori memorizzati devono rimanere coerenti.`}},"memory%2Esearch%2Eprovider":{label:{"v1-1i03ysj-m":`Provider di ricerca nella memoria`},help:{"v1-5evseb-71":`Seleziona il backend di embedding usato per creare e interrogare i vettori di memoria. Il valore predefinito è "openai"; imposta "openai-compatible", "gemini", "voyage", "mistral", "bedrock", "deepinfra", "github-copilot", "lmstudio", "ollama" o "local" per usare un backend diverso.`}},"memory%2Esearch%2Equery%2EmaxResults":{label:{"v1-5g82o6-p":`Numero massimo di risultati della ricerca in memoria`},help:{"v1-13ekath-4x":`Numero massimo di risultati in memoria restituiti dalla ricerca prima del successivo riordinamento e dell'inserimento nel prompt. Aumentalo per recuperare più risultati oppure riducilo per ottenere prompt più compatti e risposte più rapide.`}},"memory%2Esearch%2Equery%2EminScore":{label:{"v1-1hsndok-n":`Punteggio minimo della ricerca in memoria`},help:{"v1-1ww231l-4v":`Soglia minima del punteggio di pertinenza per includere i risultati in memoria nell'output finale del recupero. Aumentala per ridurre le corrispondenze deboli o poco pertinenti oppure abbassala per un recupero meno restrittivo.`}},"memory%2Esearch%2EqueryInputType":{label:{"v1-ita7p2-u":`Tipo di input delle query di ricerca in memoria`},help:{"v1-831yrv-4q":"Valore facoltativo di `input_type`, specifico del provider, per gli embedding di memoria al momento della query. Usalo con endpoint di embedding asimmetrici compatibili con OpenAI che richiedono un'etichetta per la query."}},"memory%2Esearch%2ErememberAcrossConversations":{label:{"v1-1iqw2nv-t":`Ricorda tra le conversazioni`},help:{"v1-k1itm8-7y":`Usa il contesto pertinente delle altre conversazioni private di questo agente tramite il recupero protetto delle trascrizioni. È attivo per impostazione predefinita solo quando il valore globale di session.dmScope non è impostato o è "main" e nessuna associazione sovrascrive l'ambito dei messaggi diretti; qualsiasi isolamento configurato per i messaggi diretti lo disattiva per impostazione predefinita. Un valore esplicito true o false ha sempre la precedenza.`}},"memory%2Esearch%2Eremote%2EapiKey":{label:{"v1-3ejsqh-o":`Chiave API per gli embedding remoti`},help:{"v1-nfuuu-62":`Fornisce una chiave API dedicata per le chiamate remote di embedding usate per l'indicizzazione della memoria e la generazione di embedding al momento della ricerca. Usa questa opzione quando gli embedding della memoria devono utilizzare credenziali diverse da quelle predefinite globali o dalle variabili d'ambiente.`}},"memory%2Esearch%2Eremote%2EbaseUrl":{label:{"v1-pd1jie-p":`URL di base per gli embedding remoti`},help:{"v1-1ugvqgt-5p":`Sovrascrive l'endpoint dell'API di embedding, ad esempio con un proxy compatibile con OpenAI o un URL di base personalizzato per Gemini. Usa questa opzione solo per instradare le richieste attraverso il tuo gateway o un endpoint del fornitore; altrimenti mantieni le impostazioni predefinite del provider.`}},"memory%2Esearch%2Eremote%2Ebatch%2Eenabled":{label:{"v1-av398b-u":`Embedding remoti in batch abilitati`},help:{"v1-1fehqi-5x":`Abilita le API batch del provider per i processi di embedding, se supportate (OpenAI/Gemini), migliorando la velocità di elaborazione nelle indicizzazioni più estese. Mantieni questa opzione abilitata, tranne quando devi diagnosticare errori nei batch del provider o eseguire carichi di lavoro molto ridotti.`}},"memory%2Esearch%2Eremote%2Eheaders":{label:{"v1-13jt5eg-o":`Intestazioni per gli embedding remoti`},help:{"v1-1uic0kd-5i":`Aggiunge intestazioni HTTP personalizzate alle richieste remote di embedding, combinandole con quelle predefinite del provider. Usa questa opzione per le intestazioni di autenticazione del proxy e di instradamento dei tenant e limita i valori al minimo per evitare la divulgazione di metadati sensibili.`}},"memory%2Esearch%2Esources":{label:{"v1-po677s-l":`Fonti per la ricerca nella memoria`},help:{"v1-btxtzg-57":`Sceglie quali fonti indicizzare: "memory" legge MEMORY.md e i file della memoria, mentre "sessions" include la cronologia delle trascrizioni. Mantieni ["memory"], a meno che tu non debba recuperare informazioni dalle trascrizioni delle chat precedenti.`}},"memory%2Esearch%2Estore%2Evector%2Eenabled":{label:{"v1-17q1dz1-q":`Indice vettoriale per la ricerca nella memoria`},help:{"v1-fbybkj-37":`Controlla l'indice semantico sqlite-vec. Mantieni questa impostazione avanzata quando i criteri vettoriali globali e quelli per singolo agente differiscono.`}},"memory%2Esearch%2Estore%2Evector%2EextensionPath":{label:{"v1-1w275c7-z":`Percorso dell'estensione vettoriale per la ricerca in memoria`},help:{"v1-1hysv5q-58":"Sostituisce il percorso della libreria dell'estensione sqlite-vec rilevato automaticamente (`.dylib`, `.so` o `.dll`). Usa questa opzione quando l'ambiente di esecuzione non riesce a trovare sqlite-vec automaticamente o per usare una build specifica di comprovata affidabilità."}},messages:{label:{"v1-1wwzqad-8":`Messaggi`},help:{"v1-i5k0iw-5k":`Infrastruttura dei messaggi e impostazioni predefinite condivise tra gli agenti. Le sezioni allo stesso livello nella radice gestiscono l'infrastruttura e le impostazioni predefinite condivise tra gli agenti; agents.defaults gestisce il comportamento del ciclo dell'agente; le voci dei singoli agenti possono sovrascrivere entrambe, ove supportato.`}},"messages%2EackReaction":{label:{"v1-qhntnj-i":`Emoji di reazione di conferma`},help:{"v1-1iip0zs-1x":`Reazione emoji usata per confermare la ricezione dei messaggi in arrivo (lascia vuoto per disabilitarla).`}},"messages%2EackReactionScope":{label:{"v1-7m6k7l-i":`Ambito delle reazioni di conferma`},help:{"v1-1jvdg5n-7s":`Quando inviare reazioni di conferma ("group-mentions", "group-all", "direct", "all", "off", "none"). "group-mentions" conferma la ricezione dei messaggi di gruppo che menzionano l'agente, indipendentemente dal fatto che il gruppo richieda menzioni; "group-all" conferma la ricezione di ogni messaggio di gruppo. "off"/"none" disabilita completamente le reazioni di conferma.`}},"messages%2EgroupChat":{label:{"v1-aqzwi1-g":`Regole delle chat di gruppo`},help:{"v1-chqsvh-4l":`Controlli per la gestione dei messaggi di gruppo, inclusi i criteri di attivazione tramite menzione e la dimensione della finestra della cronologia. Mantieni specifici i pattern di menzione per evitare che ogni messaggio nei canali di gruppo attivi l'agente.`}},"messages%2EgroupChat%2EhistoryLimit":{label:{"v1-i0bob3-j":`Limite della cronologia di gruppo`},help:{"v1-1mkbpw-9k":`Numero massimo di messaggi di gruppo precedenti caricati come contesto a ogni turno nelle sessioni di gruppo. Usa valori più alti per una maggiore continuità o valori più bassi per risposte più rapide ed economiche. La cronologia automatica del prompt è limitata a 200 messaggi. Il valore intero massimo JSON seleziona la finestra predefinita del canale (50 per la cronologia di gruppo condivisa), non una finestra illimitata.`}},"messages%2EgroupChat%2EmentionPatterns":{label:{"v1-1367gbd-m":`Pattern di menzione nei gruppi`},help:{"v1-i7h7qc-6f":`Pattern regex sicuri, senza distinzione tra maiuscole e minuscole, usati per rilevare menzioni esplicite o frasi di attivazione nelle chat di gruppo. Usa pattern precisi per ridurre i falsi positivi nei canali ad alto volume di messaggi; i pattern non validi o non sicuri con ripetizioni annidate vengono ignorati.`}},"messages%2EgroupChat%2EunmentionedInbound":{label:{"v1-1hc12l7-p":`Messaggi in arrivo nei gruppi senza menzione`},help:{"v1-17wef8h-5f":`Controlla come vengono inviati i messaggi senza menzione nei gruppi con ascolto sempre attivo. "user_request" li tratta come richieste dell'utente; "room_event" li invia come contesto silenzioso, in cui l'output visibile richiede lo strumento message.`}},"messages%2EgroupChat%2EvisibleReplies":{label:{"v1-1hqf9qu-l":`Risposte visibili nei gruppi`},help:{"v1-qa4z1s-aa":`Sovrascrive le risposte di origine generate dal modello per le conversazioni di gruppo o di canale. Il valore predefinito è "automatic" quando non è impostato alcun criterio globale per le risposte visibili. "message_tool" richiede message(action=send) per l'output normale dell'assistente e i contenuti multimediali generici degli strumenti; l'output di runtime esplicitamente gestito dall'host resta recapitabile, tranne nel caso degli eventi di contesto della stanza. "automatic" pubblica le risposte normali come prima.`}},"messages%2Einbound":{label:{"v1-10n88z1-g":`Debounce dei messaggi in arrivo`},help:{"v1-ebyu5x-4a":`Impostazioni dirette di debounce dei messaggi in arrivo, applicate prima dell'avvio dell'elaborazione della coda o del turno. Configurale per gestire, in base al provider, sequenze rapide di messaggi dallo stesso mittente.`}},"messages%2Einbound%2EbyChannel":{label:{"v1-bsp0no-w":`Debounce dei messaggi in arrivo per canale (ms)`},help:{"v1-wbz54j-4g":`Valori di debounce in ingresso, in millisecondi, specifici per canale e indicizzati per ID del provider. Utilizza questa opzione quando alcuni provider inviano frammenti di messaggi con maggiore frequenza rispetto ad altri.`}},"messages%2Einbound%2EdebounceMs":{label:{"v1-1dqihif-t":`Debounce dei messaggi in ingresso (ms)`},help:{"v1-1616yo2-7w":`Intervallo di inattività (ms) per raggruppare i messaggi in arrivo in rapida successione dallo stesso mittente. Telegram usa un valore predefinito di 300 ms quando non è impostata alcuna configurazione alternativa globale o per il canale; gli altri canali usano 0. Il valore zero disabilita il normale raggruppamento dei messaggi in rapida successione, ma Telegram continua a ricomporre i frammenti dei messaggi lunghi prossimi al limite.`}},"messages%2Equeue":{label:{"v1-yvcqg5-d":`Coda in ingresso`},help:{"v1-hm2o31-48":`Strategia di accodamento per i messaggi in ingresso che arrivano mentre è in corso un'esecuzione della sessione. Utilizza questa opzione per regolare il reindirizzamento dell'esecuzione, i messaggi successivi differiti, il raggruppamento o l'interruzione.`}},"messages%2Equeue%2EbyChannel":{label:{"v1-15qfdgr-l":`Modalità della coda per canale`},help:{"v1-4rf8z8-54":`Modalità della coda specifiche per canale, indicizzate per ID del provider (ad esempio telegram, discord, slack). Utilizza questa opzione quando il traffico di un canale richiede un comportamento diverso dalle impostazioni predefinite globali.`}},"messages%2Equeue%2Ecap":{label:{"v1-1dxqjbg-e":`Capacità della coda`},help:{"v1-16ql8c7-4j":`Numero massimo di elementi in ingresso mantenuti in coda prima che venga applicato il criterio di scarto. Il valore predefinito è 20; mantieni limiti contenuti nei canali molto attivi per garantire un utilizzo prevedibile della memoria.`}},"messages%2Equeue%2EdebounceMsByChannel":{label:{"v1-yp9b0s-13":`Debounce di ripiego della coda per canale (ms)`},help:{"v1-4tpyt7-4e":`Valori di debounce specifici per canale per il comportamento della coda, indicizzati per ID del provider. Utilizza questa opzione per regolare in modo indipendente la gestione dei picchi di messaggi nelle interfacce di chat con ritmi diversi.`}},"messages%2Equeue%2Edrop":{label:{"v1-ywb1ky-j":`Strategia di scarto della coda`},help:{"v1-ydb2rw-6m":`Strategia di eliminazione quando viene superato il limite della coda. "summarize" elimina gli elementi più vecchi ma ne conserva riepiloghi compatti; "old" elimina i più vecchi senza riepiloghi; "new" rifiuta l'elemento più recente. Usa "summarize" per le chat di lunga durata in cui il contesto è importante.`}},"messages%2Equeue%2Emode":{label:{"v1-x1nejf-a":`Modalità della coda`},help:{"v1-19k7gy1-67":`Modalità della coda per le esecuzioni attive. Usa "steer" per inserire prompt nell'esecuzione attiva, "followup" per eseguirli in seguito, "collect" per elaborare in seguito i messaggi compatibili in gruppo oppure "interrupt" per interrompere l'esecuzione attiva prima di avviare il prompt più recente.`}},"messages%2EresponsePrefix":{label:{"v1-1cwunbc-o":`Prefisso delle risposte in uscita`}},"messages%2EresponseUsage":{label:{"v1-nh6iuv-p":`Modalità predefinita del piè di pagina sull'utilizzo`},help:{"v1-l3shsx-dv":`Modalità predefinita del piè di pagina sull'utilizzo per ogni risposta ("off"|"tokens"|"full"), applicata inizialmente alle sessioni che non ne hanno scelta una tramite /usage. Accetta anche "on" come alias legacy di "tokens". Accetta una singola modalità oppure una mappa per canale con "default" come valore di ripiego. Precedenza: valore della sessione -> voce del canale -> default -> off; una scelta esplicita tramite /usage (incluso off) viene salvata e prevale sul valore predefinito. Usa /usage reset (alias: inherit, clear, default) per rimuovere l'impostazione specifica della sessione e tornare a ereditare questo valore predefinito configurato.`}},"messages%2EstatusReactions":{label:{"v1-17ysjar-g":`Reazioni di stato`},help:{"v1-193764l-3s":`Reazioni che indicano lo stato del ciclo di vita e aggiornano l'emoji sul messaggio che ha attivato l'agente man mano che procede (in coda → elaborazione → strumento → completato/errore).`}},"messages%2EstatusReactions%2Eenabled":{label:{"v1-rqjrr0-n":`Abilita le reazioni di stato`},help:{"v1-1qnmmnc-7x":`Abilita le reazioni di stato del ciclo di vita sui canali supportati. Discord considera l'opzione abilitata se non è impostata e le reazioni di conferma sono attive; Slack, Signal, Telegram e WhatsApp richiedono che sia impostata su true per utilizzare le reazioni del ciclo di vita. Per impostazione predefinita, Slack usa lo stato nativo del thread dell'assistente per indicare l'avanzamento.`}},"messages%2EusageTemplate":{label:{"v1-1pj1fhz-l":`Modello del piè di pagina sull'utilizzo`},help:{"v1-1xibc23-47":`Modello personalizzato del piè di pagina per /usage full, specificato come oggetto inline o percorso di un file JSON. Se il modello non è valido o non è disponibile, viene usata la riga di utilizzo integrata.`}},"messages%2EvisibleReplies":{label:{"v1-awhafd-f":`Risposte visibili`},help:{"v1-7yfwc2-8t":`Controlla le risposte originali generate dal modello nelle conversazioni dirette, di gruppo e nei canali. "message_tool" richiede message(action=send) per il normale output dell'assistente e i contenuti multimediali generici degli strumenti; l'output di runtime esplicitamente gestito dall'host rimane recapitabile, ad eccezione degli eventi ambientali della stanza. "automatic" pubblica le risposte normali come in precedenza.`}},meta:{label:{"v1-1xpfxac-m":`Metadati di compatibilità`},help:{"v1-1owqhgn-2w":`Metadati di compatibilità leggibili dalle versioni precedenti, conservati per consentire ai binari meno recenti di rifiutare i downgrade non sicuri della configurazione.`}},"meta%2ElastTouchedVersion":{label:{"v1-m6hgn7-r":`Versione dell'ultima modifica della configurazione`},help:{"v1-qykpv1-1i":`Versione di OpenClaw che ha scritto questa configurazione più di recente.`}},"meta%2Emigrations":{label:{"v1-1yu19k0-o":`Marcatori di migrazione della configurazione`},help:{"v1-burt8q-1q":`Marcatori di compatibilità limitati per le migrazioni della configurazione completate.`}},"meta%2Emigrations%2EmodelPolicyAllowlist":{label:{"v1-1yjkbc1-w":`Migrazione dell'elenco di modelli consentiti dai criteri`},help:{"v1-5psop1-1z":`Registra che le restrizioni della mappa dei modelli preesistente sono state preservate o valutate.`}},"meta%2Emigrations%2EutilityModelSeparation":{label:{"v1-qvzwo6-y":`Migrazione per la separazione dei modelli di utilità`},help:{"v1-vzdfqx-2t":`Registra che i modelli primari impliciti preesistenti sono stati preservati prima di separare la selezione dei modelli di utilità.`}},models:{label:{"v1-hzmwb-6":`Modelli`},help:{"v1-1h1niol-5q":`Radice del catalogo dei modelli per le definizioni dei provider, il comportamento di unione/sostituzione e l'integrazione opzionale del rilevamento Bedrock. Mantieni esplicite e convalidate le definizioni dei provider prima di affidarti ai percorsi di failover in produzione.`}},"models%2EcatalogRefresh":{label:{"v1-1v6rbia-l":`Aggiornamento del catalogo dei modelli`},help:{"v1-1hess4t-40":`Controlla gli aggiornamenti in background del catalogo dei modelli incluso. Le voci remote possono aggiornare i metadati dei modelli, ma non possono modificare gli endpoint o le intestazioni dei provider.`}},"models%2EcatalogRefresh%2Eenabled":{label:{"v1-1a5yfw3-t":`Aggiornamento del catalogo dei modelli abilitato`},help:{"v1-1fogpjj-3j":`Recupera in background gli aggiornamenti del catalogo dei modelli ospitato (valore predefinito: true). Imposta su false per disabilitare tutto il traffico remoto del catalogo dei modelli.`}},"models%2EcatalogRefresh%2Eurl":{label:{"v1-1piibdj-p":`URL di aggiornamento del catalogo dei modelli`},help:{"v1-e02ai2-44":`Sostituisce l'URL del catalogo dei modelli ospitato con quello di un mirror HTTPS autogestito (HTTP su localhost è consentito per i test). Le modifiche vengono applicate dopo un riavvio del Gateway.`}},"models%2Emode":{label:{"v1-wl6vg8-i":`Modalità del catalogo dei modelli`},help:{"v1-1ofrnsp-es":`Controlla il comportamento del catalogo dei provider: "merge" mantiene quelli integrati e vi sovrappone i provider personalizzati, mentre "replace" usa solo i provider configurati. In modalità "merge", gli ID provider corrispondenti mantengono i valori baseUrl non vuoti nel file models.json dell'agente, mentre i valori apiKey vengono mantenuti solo quando il provider non è gestito tramite SecretRef nel contesto attuale di configurazione/profilo di autenticazione; i provider gestiti tramite SecretRef aggiornano apiKey dai marcatori della sorgente attuale e, per i modelli corrispondenti, contextWindow/maxTokens usano il valore più alto tra le voci esplicite e implicite.`}},"models%2Eproviders":{label:{"v1-1y3b8o-f":`Provider di modelli`},help:{"v1-1y5jg0v-8p":`Mappa dei provider indicizzata per ID del provider, contenente le impostazioni di connessione e autenticazione e le definizioni concrete dei modelli. I provider integrati possono essere personalizzati con sovrascritture a livello di provider; i provider personalizzati devono includere baseUrl e models. Usa chiavi del provider stabili affinché i riferimenti degli agenti e degli strumenti rimangano portabili tra gli ambienti.`}},"models%2Eproviders%2E*%2EagentRuntime":{label:{"v1-3c30on-m":`Runtime del provider di modelli`},help:{"v1-1luy4fb-5o":`Criterio facoltativo di basso livello per il runtime dell'agente di questo provider. Usa un criterio di runtime a livello di provider/modello anziché vincolare il runtime per l'intero agente; se omesso o impostato sul valore predefinito, OpenClaw sceglie il runtime per il provider selezionato.`}},"models%2Eproviders%2E*%2EagentRuntime%2Eid":{label:{"v1-1myzd5c-p":`ID del runtime del provider di modelli`},help:{"v1-1gusd9s-69":`ID del runtime dell'agente del provider: "openclaw", "auto", un ID di harness di plugin registrato come "codex" oppure un alias di backend CLI supportato come "claude-cli". Se omesso, OpenAI sull'endpoint ufficiale usa per impostazione predefinita l'harness Codex.`}},"models%2Eproviders%2E*%2Eapi":{label:{"v1-13lvq34-q":`Adattatore API del provider di modelli`},help:{"v1-16c28rb-57":`Selezione dell'adattatore API del provider che controlla la gestione della compatibilità di richieste e risposte per le chiamate ai modelli. Usa l'adattatore corrispondente al protocollo del provider a monte per evitare incompatibilità tra le funzionalità.`}},"models%2Eproviders%2E*%2EapiKey":{label:{"v1-461pfc-m":`Chiave API del provider di modelli`},help:{"v1-1p84k96-54":`Credenziale del provider usata per l'autenticazione tramite chiave API quando il provider richiede l'autenticazione diretta con chiave. Usa la sostituzione tramite segreti o variabili d'ambiente ed evita di memorizzare chiavi reali nei file di configurazione inclusi nei commit.`}},"models%2Eproviders%2E*%2Eauth":{label:{"v1-5tjzpa-o":`Modalità di autenticazione del provider di modelli`},help:{"v1-1l1lwxr-5p":`Seleziona il tipo di autenticazione del provider: "api-key" per l'autenticazione con chiave API, "token" per l'autenticazione con token bearer, "oauth" per le credenziali OAuth e "aws-sdk" per la risoluzione delle credenziali AWS. Scegli in base ai requisiti del provider.`}},"models%2Eproviders%2E*%2EauthHeader":{label:{"v1-1d6ejif-z":`Intestazione Authorization del provider di modelli`},help:{"v1-1gn3lt3-59":`Se impostato su true, le credenziali vengono inviate tramite l'intestazione HTTP Authorization anche quando è possibile usare un'autenticazione alternativa. Usa questa opzione solo se il provider o il proxy richiede esplicitamente l'inoltro di Authorization.`}},"models%2Eproviders%2E*%2EbaseUrl":{label:{"v1-169qlbh-n":`URL di base del provider di modelli`},help:{"v1-1ku88v8-53":`URL di base dell'endpoint del provider utilizzato per gestire le richieste ai modelli per questa voce del provider. Usa endpoint HTTPS e, dove necessario, mantieni gli URL specifici per ciascun ambiente tramite modelli di configurazione.`}},"models%2Eproviders%2E*%2Eheaders":{label:{"v1-6e7t45-m":`Intestazioni del provider di modelli`},help:{"v1-chg59u-4x":`Intestazioni HTTP statiche aggiunte alle richieste del provider per l'instradamento dei tenant, l'autenticazione del proxy o i requisiti di gateway personalizzati. Usale con moderazione e conserva i valori sensibili delle intestazioni nei segreti.`}},"models%2Eproviders%2E*%2EinjectNumCtxForOpenAICompat":{label:{"v1-3u41lp-19":`Inserimento di num_ctx nel provider di modelli (compatibilità OpenAI)`},help:{"v1-53rmcr-6n":"Controlla se OpenClaw inserisce `options.num_ctx` per i provider Ollama configurati con l'adattatore compatibile con OpenAI (`openai-completions`). Il valore predefinito è true. Imposta false solo se il proxy o il servizio a monte rifiuta campi sconosciuti di `options` nel payload."}},"models%2Eproviders%2E*%2ElocalService":{label:{"v1-gokf3z-s":`Servizio locale del provider di modelli`},help:{"v1-19zkcow-4y":`Processo server locale dei modelli opzionale, avviato su richiesta per questo provider. OpenClaw verifica healthUrl, avvia il comando quando necessario, attende che il server sia pronto e poi invia la richiesta al modello.`}},"models%2Eproviders%2E*%2ElocalService%2Eargs":{label:{"v1-18ua8bb-12":`Argomenti del servizio locale del provider di modelli`},help:{"v1-t12wib-27":`Elenco degli argomenti passati al comando del server locale dei modelli senza espansione della shell.`}},"models%2Eproviders%2E*%2ElocalService%2Ecommand":{label:{"v1-1i9zwui-10":`Comando del servizio locale del provider di modelli`},help:{"v1-1x6hz64-4j":`Percorso assoluto dell'eseguibile per il processo server locale dei modelli. Mantieni esplicito questo percorso affinché l'avvio del provider sia deterministico e non dipenda dalla ricerca nel PATH della shell.`}},"models%2Eproviders%2E*%2ElocalService%2Ecwd":{label:{"v1-1p16qmb-1a":`Directory di lavoro del servizio locale del provider di modelli`},help:{"v1-fi3xlx-1h":`Directory di lavoro per il processo server locale dei modelli.`}},"models%2Eproviders%2E*%2ElocalService%2Eenv":{label:{"v1-txm98y-14":`Ambiente del servizio locale del provider di modelli`},help:{"v1-1lwb9k1-3k":`Variabili d'ambiente aggiuntive per il processo server locale dei modelli. I valori che sembrano segreti vengono oscurati nelle istantanee della configurazione.`}},"models%2Eproviders%2E*%2ElocalService%2EhealthUrl":{label:{"v1-2w1iqm-13":`URL di verifica dello stato del servizio locale del provider di modelli`},help:{"v1-jv7aw-35":`URL utilizzato per verificare che il server sia pronto prima delle richieste al modello. Se omesso, OpenClaw utilizza baseUrl del provider con /models aggiunto alla fine.`}},"models%2Eproviders%2E*%2ElocalService%2EidleStopMs":{label:{"v1-1ktyg8x-12":`Arresto per inattività del servizio locale del provider di modelli`},help:{"v1-1efg054-3z":`Tempo in millisecondi per cui mantenere attivo un server di modelli locale avviato da OpenClaw dopo il completamento dell’ultima richiesta. Impostare 0 per mantenerlo attivo fino alla chiusura di OpenClaw.`}},"models%2Eproviders%2E*%2ElocalService%2EreadyTimeoutMs":{label:{"v1-1hj089b-16":`Timeout di disponibilità del servizio locale del fornitore di modelli`},help:{"v1-4gp0f0-2r":`Tempo massimo in millisecondi di attesa della verifica di disponibilità del server di modelli locale dopo l’avvio del processo.`}},"models%2Eproviders%2E*%2EmaxTokens":{label:{"v1-662xo5-p":`Numero massimo di token del fornitore di modelli`},help:{"v1-fnj50y-38":`Limite massimo predefinito di token di output applicato ai modelli di questo fornitore quando la voce del modello non imposta maxTokens.`}},"models%2Eproviders%2E*%2Emodels":{label:{"v1-19fsoem-p":`Elenco dei modelli del fornitore`},help:{"v1-1vbm0gt-63":`Elenco dei modelli dichiarati per un fornitore, inclusi identificatori, metadati, parametri specifici del fornitore e indicazioni facoltative su compatibilità e costi. Mantenere gli ID esattamente uguali ai valori del catalogo del fornitore affinché la selezione e il fallback funzionino correttamente.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime":{label:{"v1-17rzml2-d":`Runtime del modello`},help:{"v1-1k70g2n-3g":`Criterio facoltativo di basso livello per il runtime dell’agente di questo specifico modello. Il criterio di runtime del modello ha la precedenza su quello del fornitore.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime%2Eid":{label:{"v1-1035lu7-g":`ID del runtime del modello`},help:{"v1-1llzv33-42":`ID del runtime dell’agente del modello: "openclaw", "auto", un ID registrato dell’infrastruttura di esecuzione di un plugin come "codex", oppure un alias di backend CLI supportato come "claude-cli".`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput":{label:{"v1-x3fby6-h":`Input multimediale del modello`},help:{"v1-wxtj8e-2x":`Metadati facoltativi sulle capacità multimediali del modello, usati dagli strumenti per scegliere impostazioni predefinite conservative per la compressione delle immagini.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage":{label:{"v1-5448tb-h":`Input immagini del modello`},help:{"v1-1nviirq-3c":`Limiti facoltativi per le immagini in ingresso per questo modello, come la lunghezza massima del lato, il numero massimo di pixel e la lunghezza del lato preferita per la compressione.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxBytes":{label:{"v1-4chdj6-l":`Byte massimi delle immagini del modello`},help:{"v1-c2469j-23":`Dimensione massima dei dati dell'immagine codificata accettata dal fornitore per questo modello.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxPixels":{label:{"v1-4hbb56-m":`Pixel massimi delle immagini del modello`},help:{"v1-9d6yqp-1u":`Numero massimo di pixel per immagine accettato dal fornitore per questo modello.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxSidePx":{label:{"v1-1otuj2k-k":`Lato massimo delle immagini del modello`},help:{"v1-1gbci08-1y":`Larghezza o altezza massima delle immagini accettata dal fornitore per questo modello.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EpreferredSidePx":{label:{"v1-1d35u85-q":`Lato preferito delle immagini del modello`},help:{"v1-1u1mpcg-2x":`Lunghezza del lato preferita per il ridimensionamento delle immagini con una compressione bilanciata. Lasciare non impostata per usare il valore predefinito conservativo di OpenClaw.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EtokenMode":{label:{"v1-1oh830x-m":`Modalità dei token immagine del modello`},help:{"v1-1oy6z7v-1z":`Metodo di conteggio dei token immagine del fornitore: "tile", "detail" o "provider".`}},"models%2Eproviders%2E*%2Eparams":{label:{"v1-tv1h1l-x":`Parametri di runtime del fornitore di modelli`},help:{"v1-464sgu-4t":`Parametri di runtime specifici del fornitore, interpretati dai relativi plugin. Mantieni le chiavi documentate dal fornitore e preferisci la sua documentazione esplicita alle ipotesi condivise formulate ad hoc.`}},"models%2Eproviders%2E*%2Eregion":{label:{"v1-9wgoh5-l":`Regione del fornitore di modelli`},help:{"v1-yq7rxk-5h":`Regione facoltativa di distribuzione/API del fornitore, interpretata dai fornitori che espongono endpoint regionali. Consulta la documentazione del fornitore per i valori supportati; le impostazioni di baseUrl hanno generalmente la precedenza quando sono impostate entrambe.`}},"models%2Eproviders%2E*%2Erequest":{label:{"v1-1yv8vnf-w":`Override delle richieste al fornitore di modelli`},help:{"v1-1lkxryk-87":`Override facoltativi per le richieste al fornitore di modelli, inclusi header aggiuntivi, override dell'autenticazione, instradamento tramite proxy, impostazioni del client TLS e l'opzione allowPrivateNetwork per endpoint attendibili ospitati autonomamente. Usali solo quando il servizio a monte o il percorso di rete aziendale richiede una personalizzazione del trasporto.`}},"models%2Eproviders%2E*%2Erequest%2EallowPrivateNetwork":{label:{"v1-1etevm-18":`Consenti rete privata per le richieste al fornitore di modelli`},help:{"v1-1nbtcjk-fo":`Se impostato su true, consente le richieste HTTP del provider di modelli verso intervalli privati, CGNAT o simili attraverso la protezione delle richieste HTTP del provider (fetchWithSsrFGuard). Gli URL di base dei provider personalizzati/locali considerano già attendibile l'origine esatta configurata, ad eccezione delle origini di metadati, link-local e NAT64 per uso locale (64:ff9b:1::/48); impostare su false per disattivare questa attendibilità. OpenAI Responses WebSocket riutilizza request per le intestazioni/TLS, ma non usa quel percorso di recupero con protezione SSRF. Usare true solo per endpoint ospitati autonomamente e controllati dall'operatore che devono raggiungere origini private esterne all'origine baseUrl configurata.`}},"models%2Eproviders%2E*%2Erequest%2Eauth":{label:{"v1-uw1fmg-10":`Personalizzazione dell'autenticazione delle richieste al provider di modelli`},help:{"v1-ucdgnf-1w":`Personalizza il comportamento di autenticazione delle richieste per questo provider.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2EheaderName":{label:{"v1-1jwzygk-13":`Nome dell'intestazione di autenticazione delle richieste al provider di modelli`},help:{"v1-1881nqr-1i":`Nome dell'intestazione di autenticazione personalizzata usato quando la modalità di autenticazione è header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Emode":{label:{"v1-1prff17-w":`Modalità di autenticazione delle richieste al provider di modelli`},help:{"v1-1lhv8hs-24":`Modalità di personalizzazione dell'autenticazione: "provider-default", "authorization-bearer" o "header".`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Eprefix":{label:{"v1-1fxbu5n-15":`Prefisso dell'intestazione di autenticazione delle richieste al provider di modelli`},help:{"v1-1rbm9lz-21":`Prefisso facoltativo anteposto a request.auth.value quando la modalità di autenticazione è header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Etoken":{label:{"v1-31rmhm-z":`Token Bearer delle richieste al provider di modelli`},help:{"v1-6rcasw-1l":`Token Bearer utilizzato quando la modalità di autenticazione è authorization-bearer.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Evalue":{label:{"v1-gx2woc-14":`Valore dell'intestazione di autenticazione delle richieste al provider di modelli`},help:{"v1-1v69ej-1j":`Valore personalizzato dell'intestazione di autenticazione utilizzato quando la modalità di autenticazione è header.`}},"models%2Eproviders%2E*%2Erequest%2Eheaders":{label:{"v1-72ia6g-u":`Intestazioni delle richieste al provider di modelli`},help:{"v1-zj3orj-2i":`Intestazioni aggiuntive integrate nelle richieste al provider dopo l'attribuzione predefinita e la risoluzione dell'autenticazione.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy":{label:{"v1-1drhe6m-s":`Proxy delle richieste al provider di modelli`},help:{"v1-md5uj8-4j":`Configurazione proxy alternativa facoltativa per le richieste al provider di modelli. Usa "env-proxy" per rispettare le impostazioni proxy dell'ambiente oppure "explicit-proxy" per instradare le richieste tramite un URL proxy specifico.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Emode":{label:{"v1-2ea1ht-x":`Modalità proxy delle richieste al provider di modelli`},help:{"v1-1dx0ozg-29":`Modalità di configurazione proxy alternativa per le richieste al provider di modelli: "env-proxy" o "explicit-proxy".`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls":{label:{"v1-y7ygtf-w":`TLS del proxy delle richieste al provider di modelli`},help:{"v1-rdx62w-1v":`Impostazioni TLS facoltative utilizzate per la connessione al proxy configurato.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Eca":{label:{"v1-xp5zz1-z":`CA TLS del proxy delle richieste al provider di modelli`},help:{"v1-11pg2fd-1s":`Pacchetto CA personalizzato utilizzato per verificare la catena di certificati TLS del proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ecert":{label:{"v1-1p0kbsn-11":`Certificato TLS del proxy delle richieste al provider di modelli`},help:{"v1-x8nk2q-22":`Certificato TLS del client presentato al proxy quando è richiesta l'autenticazione TLS reciproca.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EinsecureSkipVerify":{label:{"v1-1gmlhnv-18":`Salta verifica TLS del proxy per le richieste al fornitore di modelli`},help:{"v1-12vjdm9-2j":`Salta la verifica del certificato TLS del proxy. Utilizzare solo in ambienti di sviluppo controllati.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ekey":{label:{"v1-1rjms34-10":`Chiave TLS del proxy per le richieste al fornitore di modelli`},help:{"v1-1skyr56-1w":`Chiave privata associata a request.proxy.tls.cert per l'autenticazione TLS reciproca con il proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Epassphrase":{label:{"v1-xwzjbl-17":`Passphrase TLS del proxy per le richieste al fornitore di modelli`},help:{"v1-wjvoxd-1m":`Passphrase facoltativa utilizzata per decrittografare request.proxy.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EserverName":{label:{"v1-9wzzxd-18":`Nome del server TLS del proxy per le richieste al fornitore di modelli`},help:{"v1-b4oabu-22":`Sostituzione facoltativa del nome SNI/server utilizzata quando si stabilisce una connessione TLS al proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Eurl":{label:{"v1-1r3x1tf-w":`URL del proxy per le richieste al fornitore di modelli`},help:{"v1-kvbgou-48":`URL esplicito del proxy utilizzato quando request.proxy.mode è impostato su explicit-proxy. Le credenziali incorporate nell'URL sono trattate come dati sensibili e oscurate nelle istantanee.`}},"models%2Eproviders%2E*%2Erequest%2Etls":{label:{"v1-1xtk31n-q":`TLS per le richieste al fornitore di modelli`},help:{"v1-16u7v7h-2b":`Impostazioni TLS facoltative utilizzate per la connessione diretta all'endpoint del modello a monte.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Eca":{label:{"v1-oselmd-t":`CA TLS per le richieste al fornitore del modello`},help:{"v1-ny8y3e-1v":`Pacchetto CA personalizzato utilizzato per verificare la catena dei certificati TLS a monte.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ecert":{label:{"v1-trr9e7-v":`Certificato TLS per le richieste al fornitore del modello`},help:{"v1-1lltmhw-2e":`Certificato TLS del client presentato all'endpoint a monte quando è richiesta l'autenticazione TLS reciproca.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EinsecureSkipVerify":{label:{"v1-1dmxiab-12":`Salta la verifica TLS per le richieste al fornitore del modello`},help:{"v1-1006cuy-2m":`Salta la verifica del certificato TLS a monte. Utilizzare solo in ambienti di sviluppo controllati.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ekey":{label:{"v1-13sjm0o-u":`Chiave TLS per le richieste al fornitore del modello`},help:{"v1-w2agir-1t":`Chiave privata abbinata a request.tls.cert per l'autenticazione TLS reciproca a monte.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Epassphrase":{label:{"v1-19c5oux-11":`Frase segreta TLS per le richieste al fornitore del modello`},help:{"v1-10ds42f-1g":`Frase segreta facoltativa utilizzata per decrittografare request.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EserverName":{label:{"v1-oe4b49-12":`Nome del server TLS per le richieste al fornitore del modello`},help:{"v1-18yt7x9-1y":`Valore sostitutivo facoltativo per SNI/nome del server utilizzato quando si stabilisce la connessione TLS a monte.`}},"models%2Eproviders%2E*%2EtimeoutSeconds":{label:{"v1-itszd1-u":`Tempo limite delle richieste al fornitore del modello`},help:{"v1-t3yn8l-ih":`Timeout facoltativo in secondi per le richieste ai modelli di ciascun provider. Le impostazioni delle richieste a livello di provider si applicano alle voci dei modelli esplicitamente definiti per quel provider; non creano modelli impliciti. Per i provider personalizzati, impostalo insieme a baseUrl e models del provider. Si applica alle richieste HTTP del provider, incluse la connessione, le intestazioni, il corpo e la gestione dell'interruzione dell'intera richiesta, e innalza anche il limite del watchdog di inattività/streaming LLM per questo provider oltre il valore predefinito implicito di circa 120 s. Usalo per server di modelli locali o self-hosted lenti oppure per provider cloud che accumulano token di ragionamento senza trasmetterli (Gemini in anteprima, Claude/Opus con payload di strumenti di grandi dimensioni), anziché modificare i timeout globali degli agenti.`}},nodeHost:{label:{"v1-nb8lk1-9":`Host del nodo`},help:{"v1-8recuz-4z":`Controlli dell'host del nodo per le funzionalità esposte da questo nodo gateway ad altri nodi o client. Mantieni i valori predefiniti, a meno che tu non intenda rendere disponibili tramite proxy le funzionalità locali nella tua rete di nodi.`}},"nodeHost%2EagentRuns":{label:{"v1-s71x8m-f":`Esecuzioni degli agenti sul nodo`},help:{"v1-4uz5ur-2k":`Abilita i turni degli agenti nativi soggetti ad approvazione su questo host del nodo senza interfaccia grafica. Disabilitati per impostazione predefinita.`}},"nodeHost%2EagentRuns%2Eclaude":{label:{"v1-10xgkda-m":`Esecuzioni dell'agente Claude sul nodo`},help:{"v1-g8az5y-2l":`Controlla se questo host del nodo senza interfaccia grafica può segnalare al gateway la disponibilità dei turni dell'agente Claude CLI.`}},"nodeHost%2EagentRuns%2Eclaude%2Eenabled":{label:{"v1-15o3u53-u":`Esecuzioni dell'agente Claude sul nodo abilitate`},help:{"v1-1ke804l-44":`Segnala la disponibilità della continuazione delle sessioni Claude sul nodo associato quando il binario locale claude è disponibile (valore predefinito: false). Le esecuzioni richiedono comunque l'approvazione per l'esecuzione sul nodo.`}},"nodeHost%2EautoUpdate":{label:{"v1-fmh4qs-m":`Aggiornamenti automatici dei nodi`},help:{"v1-16xjk4e-5n":`Controlla gli aggiornamenti automatici del runtime separato per gli host di nodi senza interfaccia grafica distribuiti come pacchetti. Verifica ogni ora e attende che tutte le attività dei nodi siano terminate prima di riavviare; i riavvii automatici avvengono ad almeno 12 ore di distanza l'uno dall'altro.`}},"nodeHost%2EautoUpdate%2Eenabled":{label:{"v1-89maql-u":`Aggiornamenti automatici dei nodi abilitati`},help:{"v1-1sa0yeg-7w":`Abilita gli aggiornamenti automatici stable o beta per i nodi senza interfaccia grafica distribuiti come pacchetti e in esecuzione prolungata (valore predefinito: true). Imposta false per disattivarli. Sono disabilitati anche da update.checkOnStart=false o OPENCLAW_NO_AUTO_UPDATE=1; gli aggiornamenti non vengono applicati automaticamente a checkout del codice sorgente, app native, worker privati, dev ed extended-stable.`}},"nodeHost%2EbrowserProxy":{label:{"v1-1bm9i0h-i":`Proxy del browser del nodo`},help:{"v1-2xrew7-4f":`Raggruppa le impostazioni del proxy del browser per esporre il controllo del browser locale tramite l'instradamento del nodo. Abilita solo quando i flussi di lavoro dei nodi remoti richiedono i profili del browser locale.`}},"nodeHost%2EbrowserProxy%2EallowProfiles":{label:{"v1-cq2v55-z":`Profili consentiti del proxy del browser del nodo`},help:{"v1-1ew5dkm-8b":`Elenco facoltativo dei nomi dei profili del browser consentiti, esposti tramite l'instradamento del proxy del nodo. Lascia vuoto per mantenere l'accesso completo predefinito ai profili, incluse le route di creazione ed eliminazione. Se impostato, OpenClaw applica il principio del privilegio minimo all'accesso ai profili e blocca la creazione e l'eliminazione dei profili persistenti tramite il proxy.`}},"nodeHost%2EbrowserProxy%2Eenabled":{label:{"v1-1dlbo60-q":`Proxy del browser del nodo abilitato`},help:{"v1-pa04pd-5b":`Espone il server di controllo del browser locale tramite l'instradamento del proxy del nodo, consentendo ai client remoti di usare le funzionalità del browser di questo host. Mantieni disabilitato a meno che l'automazione remota non ne dipenda esplicitamente.`}},"nodeHost%2Emcp":{label:{"v1-4hkwkx-d":`MCP dell'host del nodo`},help:{"v1-1mdhrwl-48":`Usa come strumenti dell'agente i server MCP avviati dall'host del nodo senza interfaccia grafica e pubblicati sul Gateway associato. Riavvia l'host del nodo dopo aver modificato questa sezione.`}},"nodeHost%2Emcp%2Eservers":{label:{"v1-6lpscp-l":`Server MCP dell'host del nodo`},help:{"v1-19m002f-3x":`Definizioni con nome dei server MCP locali a questo nodo. Usa la stessa struttura dei server di mcp.servers; i server OAuth non sono supportati dall'host del nodo.`}},"nodeHost%2Eskills":{label:{"v1-1n58xs9-g":`Skills dell'host del nodo`},help:{"v1-v8txza-41":`Usa questa sezione per pubblicare le abilità installate in ~/.openclaw/skills dall'host del nodo senza interfaccia grafica. Riavvia l'host del nodo dopo aver modificato i file delle abilità.`}},"nodeHost%2Eskills%2Eenabled":{label:{"v1-uf23u8-o":`Skills dell'host del nodo abilitate`},help:{"v1-1ggpkqb-36":`Rileva e pubblica le Skills ospitate sul nodo dopo la connessione (valore predefinito: true). Imposta false per disabilitare la pubblicazione delle Skills del nodo.`}},"nodeHost%2EworkerRuns":{label:{"v1-1aab8yp-g":`Esecuzioni dei worker sul nodo`},help:{"v1-1w83rox-2p":`Abilita l'hosting completo delle sessioni worker di OpenClaw a partire dai bundle gestiti dal Gateway. Disabilitato per impostazione predefinita.`}},"nodeHost%2EworkerRuns%2Ecapacity":{label:{"v1-1tquo3g-o":`Capacità di esecuzione dei worker sul nodo`},help:{"v1-10nvk8f-3w":`Numero massimo di sessioni worker simultanee ospitate da questo nodo (valore predefinito: il numero di core CPU disponibili). Deve essere un numero intero compreso tra 1 e 1024.`}},"nodeHost%2EworkerRuns%2EcontainerImage":{label:{"v1-1fujssi-v":`Immagine del container per l'esecuzione dei worker sul nodo`},help:{"v1-1oqx50o-5t":`Immagine Node 24.16+ o 26.1+ facoltativa per i worker isolati in container (valore predefinito: "node:24.19.0-slim"). Se necessario, usa un'immagine vincolata a un digest, proveniente da un registro privato o precaricata; le immagini mancanti vengono scaricate al primo utilizzo.`}},"nodeHost%2EworkerRuns%2Eenabled":{label:{"v1-t3la2w-o":`Esecuzioni dei worker sul nodo abilitate`},help:{"v1-b3t0xp-2t":`Consenti a questo nodo associato di ospitare sessioni a partire dagli esatti bundle installati dal suo Gateway (valore predefinito: false).`}},"nodeHost%2EworkerRuns%2Eisolation":{label:{"v1-1qqd8iw-p":`Isolamento dell'esecuzione dei worker sul nodo`},help:{"v1-19i6swo-58":`Seleziona il confine di isolamento del processo delle sessioni worker: "none" esegue direttamente sull'host del nodo (valore predefinito); "container" richiede un motore compatibile con Docker funzionante e non ripiega mai sull'esecuzione sull'host.`}},plugins:{label:{"v1-10renyj-7":`Plugin`},help:{"v1-1qbev2k-5c":`Controlli del sistema di plugin per abilitare le estensioni, limitare l'ambito di caricamento, configurare le voci e monitorare le installazioni. Negli ambienti di produzione, mantieni espliciti i criteri dei plugin e applica il principio del privilegio minimo.`}},"plugins%2Eallow":{label:{"v1-19jw4yj-g":`Elenco dei plugin consentiti`},help:{"v1-pupwbe-7z":`Elenco facoltativo degli ID dei plugin consentiti; se impostato, solo i plugin elencati possono essere caricati. I canali di chat integrati configurati possono comunque attivare il proprio plugin integrato quando il canale è abilitato esplicitamente nella configurazione. Usa questo elenco per limitare le estensioni a quelle approvate negli ambienti controllati.`}},"plugins%2Edeny":{label:{"v1-arkuus-f":`Elenco dei plugin bloccati`},help:{"v1-4gyt4z-4i":`Elenco facoltativo degli ID dei plugin bloccati anche se inclusi negli elenchi dei plugin consentiti o nei percorsi. Usa le regole di blocco per i ripristini di emergenza e per bloccare in modo assoluto i plugin rischiosi.`}},"plugins%2Eenabled":{label:{"v1-461fte-e":`Abilita i plugin`},help:{"v1-pnygd7-50":`Abilita o disabilita globalmente il caricamento di plugin ed estensioni durante l'avvio e il ricaricamento della configurazione (valore predefinito: true). Mantieni questa opzione abilitata solo se le funzionalità delle estensioni sono necessarie per la tua distribuzione.`}},"plugins%2Eentries":{label:{"v1-1q3x0gu-e":`Voci dei plugin`},help:{"v1-cn74rf-54":`Impostazioni per ciascun plugin, indicizzate per ID del plugin, che includono l'abilitazione e i dati di configurazione di esecuzione specifici del plugin. Usale per regolare singoli plugin senza modificare i criteri globali di caricamento.`}},"plugins%2Eentries%2E*%2EapiKey":{label:{"v1-1c5cpg5-e":`Chiave API del plugin`},help:{"v1-ctytg2-53":`Campo facoltativo per la chiave API utilizzato dai plugin che accettano la configurazione diretta della chiave nelle impostazioni della voce. Usa la sostituzione tramite segreti o variabili d'ambiente ed evita di salvare credenziali reali nei file di configurazione sotto controllo di versione.`}},"plugins%2Eentries%2E*%2Econfig":{label:{"v1-1i42kk8-d":`Configurazione del plugin`},help:{"v1-1he672p-51":`Dati di configurazione definiti dal plugin e interpretati secondo il suo schema e le sue regole di convalida. Usa solo i campi documentati dal plugin per evitare impostazioni ignorate o non valide.`}},"plugins%2Eentries%2E*%2Eenabled":{label:{"v1-87au17-e":`Plugin abilitato`},help:{"v1-12soc0h-9a":`Override dell'abilitazione per un plugin specifico, applicato alla policy globale dei plugin. Con la modalità predefinita di ricaricamento ibrido, le modifiche ricaricano a caldo il runtime del plugin per i nuovi turni dell'agente senza riavviare il Gateway, a meno che il plugin non richieda un riavvio per questo percorso. Usa questa opzione per distribuire gradualmente i plugin nei vari ambienti.`}},"plugins%2Eentries%2E*%2Eenv":{label:{"v1-1vsubm6-s":`Variabili d'ambiente del plugin`},help:{"v1-p39pu4-52":`Mappa delle variabili d'ambiente specifiche del plugin, inserite solo nel contesto di runtime di quel plugin. Usa questa opzione per limitare le credenziali del provider a un solo plugin anziché condividere l'ambiente globale del processo.`}},"plugins%2Eentries%2E*%2Ehooks":{label:{"v1-1miceel-i":`Policy degli hook del plugin`},help:{"v1-1oslnrf-4c":`Controlli della policy degli hook tipizzati per singolo plugin, relativi ai controlli di sicurezza imposti dal nucleo del sistema. Usa questa opzione per limitare le categorie di hook ad alto impatto senza disabilitare l'intero plugin.`}},"plugins%2Eentries%2E*%2Ehooks%2EallowConversationAccess":{label:{"v1-ckd9n5-v":`Consenti gli hook di accesso alle conversazioni`},help:{"v1-xqz31z-7e":"Controlla se questo plugin può leggere il contenuto grezzo delle conversazioni tramite hook tipizzati come `before_agent_run`, `before_model_resolve`, `before_agent_reply`, `llm_input`, `llm_output`, `before_agent_finalize` e `agent_end`. I plugin non inclusi nella distribuzione devono abilitare esplicitamente questa opzione."}},"plugins%2Eentries%2E*%2Ehooks%2EallowPromptInjection":{label:{"v1-1p7f9k9-s":`Consenti gli hook di iniezione nei prompt`},help:{"v1-7y6cny-32":"Controlla se questo plugin può modificare i prompt tramite hook tipizzati. Imposta su false per bloccare `before_prompt_build`."}},"plugins%2Eentries%2E*%2Ehooks%2EtimeoutMs":{label:{"v1-zg658l-o":`Timeout degli hook del plugin (ms)`},help:{"v1-4ra6b7-74":`Timeout predefinito in millisecondi per gli hook tipizzati di questo plugin, con un limite massimo di 600000. Se non impostato, ogni hook usa il timeout dichiarato dal plugin o il criterio del Gateway per il singolo hook; non esiste un unico valore predefinito fisso. I valori per i singoli hook in hooks.timeouts hanno la precedenza.`}},"plugins%2Eentries%2E*%2Ehooks%2Etimeouts":{label:{"v1-1k80g2z-t":`Override dei timeout degli hook del plugin`},help:{"v1-yphl9b-5s":`Override dei timeout per singolo hook in millisecondi, indicizzati per nome dell'hook tipizzato, con un limite massimo di 600000. Usa override mirati per gli hook notoriamente lenti, come before_prompt_build o agent_end, anziché aumentare il timeout di tutti gli hook.`}},"plugins%2Eentries%2E*%2Ellm":{label:{"v1-tnwzbh-h":`Criteri LLM del plugin`},help:{"v1-dlca6c-4j":`Controlli di api.runtime.llm.complete per singolo plugin che regolano le autorizzazioni di override del modello e dell'agente. Lascia questa opzione non impostata, a meno che un plugin non debba indirizzare esplicitamente le chiamate di completamento gestite dall'host.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAgentIdOverride":{label:{"v1-14o9l6p-v":`Consenti l'override dell'agente LLM da parte del plugin`},help:{"v1-k8c08b-4n":`Consente esplicitamente a questo plugin di richiedere api.runtime.llm.complete con un ID agente non predefinito. Mantieni false, a meno che il plugin non sia considerato attendibile per l'accesso ai modelli di altri agenti.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAuthProfileOverride":{label:{"v1-8zsq4z-12":`Consenti l'override del profilo di autenticazione LLM da parte del plugin`},help:{"v1-9ityw9-4x":`Consente a questo plugin di selezionare un profilo di autenticazione non predefinito per i completamenti isolati del runtime dell'agente. Mantieni false, a meno che il plugin non sia considerato attendibile per l'instradamento esplicito e isolato delle credenziali.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedCompletionModels":{label:{"v1-13e4e1t-10":`Modelli di completamento LLM consentiti per il plugin`},help:{"v1-1ul08he-54":`Modelli consentiti per ogni completamento LLM del plugin, espressi come riferimenti canonici "provider/model", inclusi i valori predefiniti risolti dall'host e le sostituzioni. Usa "*" solo se intendi consentire qualsiasi modello.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedModels":{label:{"v1-1vuyyz9-p":`Modelli LLM consentiti per il plugin`},help:{"v1-154sk45-47":`Modelli sostitutivi consentiti per le chiamate LLM dei plugin attendibili, espressi come riferimenti canonici "provider/model". Usa "*" solo se intendi consentire qualsiasi sostituzione del modello.`}},"plugins%2Eentries%2E*%2Ellm%2EallowModelOverride":{label:{"v1-1wtocu9-v":`Consenti la sostituzione del modello LLM del plugin`},help:{"v1-uw4jmc-47":`Consente esplicitamente a questo plugin di richiedere sostituzioni del modello in api.runtime.llm.complete. Mantieni false a meno che il plugin non sia considerato attendibile per determinare la selezione del modello.`}},"plugins%2Eentries%2E*%2Esubagent":{label:{"v1-1dea8kh-m":`Criteri dei sottoagenti del plugin`},help:{"v1-wbf4m1-4d":`Controlli di esecuzione dei sottoagenti per ciascun plugin, relativi all'autorizzazione a sostituire il modello e agli elenchi dei modelli consentiti. Lascia questa opzione non impostata a meno che un plugin non debba determinare esplicitamente la selezione del modello dei sottoagenti.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowedModels":{label:{"v1-1axw70h-u":`Modelli consentiti per i sottoagenti del plugin`},help:{"v1-2pvkow-42":`Modelli sostitutivi consentiti per le esecuzioni dei sottoagenti dei plugin attendibili, espressi come riferimenti canonici "provider/model". Usa "*" solo se intendi consentire qualsiasi modello.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowModelOverride":{label:{"v1-1wes28b-10":`Consenti la sostituzione del modello dei sottoagenti del plugin`},help:{"v1-1r5tzm1-4g":`Consente esplicitamente a questo plugin di richiedere sostituzioni del fornitore o del modello nelle esecuzioni dei sottoagenti in background. Mantieni false a meno che il plugin non sia ritenuto affidabile per la scelta del modello.`}},"plugins%2Eload":{label:{"v1-9stn89-d":`Caricatore di plugin`},help:{"v1-1myjwbi-52":`Gruppo di configurazione del caricatore di plugin per specificare i percorsi del file system in cui vengono individuati i plugin. Mantieni i percorsi di caricamento espliciti e verificati per evitare il caricamento accidentale di estensioni non attendibili.`}},"plugins%2Eload%2Epaths":{label:{"v1-nk4cri-h":`Percorsi di caricamento dei plugin`},help:{"v1-o689p1-4z":`File o directory di plugin aggiuntivi analizzati dal caricatore oltre a quelli predefiniti integrati. Usa directory dedicate alle estensioni ed evita percorsi troppo ampi con contenuti eseguibili non pertinenti.`}},"plugins%2Eslots":{label:{"v1-oamycb-c":`Slot dei plugin`},help:{"v1-zx6crl-5f":`Seleziona i plugin a cui assegnare slot esclusivi in fase di esecuzione, come la memoria, in modo che un solo plugin fornisca ciascuna funzionalità. Assegna esplicitamente gli slot per evitare sovrapposizioni tra fornitori con comportamenti in conflitto.`}},"plugins%2Eslots%2EcontextEngine":{label:{"v1-1371nb9-l":`Plugin del motore di contesto`},help:{"v1-4v13iw-2t":`Seleziona tramite ID il plugin del motore di contesto attivo, in modo che un solo plugin gestisca l'orchestrazione del contesto.`}},"plugins%2Eslots%2Ememory":{label:{"v1-1948lbp-d":`Plugin di memoria`},help:{"v1-80ngcl-23":`Seleziona tramite ID il plugin di memoria attivo, oppure "none" per disabilitare i plugin di memoria.`}},presence:{label:{"v1-10fdwo4-8":`Presenza`}},proxy:{label:{"v1-ji57pa-d":`Proxy gestito`},help:{"v1-vui6bx-58":`Instradamento tramite proxy di inoltro gestito dall'operatore per il traffico HTTP, HTTPS, WebSocket e i percorsi di uscita diretta supportati del runtime OpenClaw. Usa questa opzione quando il controllo centralizzato del traffico in uscita rientra nel perimetro della distribuzione.`}},"proxy%2Eenabled":{label:{"v1-8i199z-l":`Proxy gestito abilitato`},help:{"v1-1456xdw-49":`Override esplicito del proxy gestito. La presenza di un URL abilita l'instradamento per impostazione predefinita; imposta false per ignorare gli URL proxy configurati o definiti nelle variabili d'ambiente senza eliminarli.`}},"proxy%2EloopbackMode":{label:{"v1-1y356w6-r":`Modalità loopback del proxy gestito`},help:{"v1-1kaiuh0-3c":`Controlla l'instradamento del piano di controllo del Gateway su loopback quando la modalità proxy gestito è attiva: "gateway-only", "proxy" o "block".`}},"proxy%2EproxyUrl":{label:{"v1-b5s3c3-h":`URL del proxy gestito`},help:{"v1-p36b5l-3v":`URL del proxy di inoltro gestito. Usa http:// per un proxy CONNECT semplice oppure https:// quando la connessione all'endpoint del proxy stesso deve usare TLS.`}},"proxy%2Etls":{label:{"v1-qr3npv-h":`TLS del proxy gestito`},help:{"v1-6i0vu-3q":`Impostazioni TLS usate per la connessione all'endpoint del proxy gestito. Queste impostazioni si applicano al TLS del proxy, non al TLS della destinazione dopo CONNECT.`}},"proxy%2Etls%2EcaFile":{label:{"v1-1mel3ux-p":`File CA TLS del proxy gestito`},help:{"v1-1ntzjia-2p":`Percorso nel file system di un bundle CA personalizzato usato per verificare il certificato di un endpoint proxy gestito HTTPS.`}},secrets:{label:{"v1-1sihgpy-7":`Segreti`},help:{"v1-jgn0o9-2l":`Provider dei riferimenti ai segreti, comportamento dell'archivio condiviso e protezione opzionale del traffico in uscita dei sottoprocessi.`}},"secrets%2EegressProxy":{label:{"v1-ni0kq4-j":`Proxy in uscita per i segreti`},help:{"v1-1qfgid-4n":`Proxy loopback gestito dal Gateway che sostituisce i valori sentinella dei segreti nell'archivio condiviso solo al momento della richiesta in uscita. Riavvia il Gateway dopo aver modificato questa sezione, le cui impostazioni vengono applicate all'avvio.`}},"secrets%2EegressProxy%2EallowedHosts":{label:{"v1-1jt4jwf-x":`Host consentiti per il proxy in uscita per i segreti`},help:{"v1-9ypodl-6t":`Elenco facoltativo delle destinazioni consentite per richieste e tunnel CONNECT. Se presente, le destinazioni devono figurare in questo elenco, in un'associazione host specifica per un segreto o in bypassHosts. Un elenco vuoto consente solo gli host associati o esclusi dal proxy. Riavviare il Gateway dopo ogni modifica.`}},"secrets%2EegressProxy%2EbypassHosts":{label:{"v1-1keo1yv-w":`Host esclusi dal proxy in uscita per i segreti`},help:{"v1-1oiiomv-57":`Nomi host esatti che utilizzano tunnel CONNECT ciechi autenticati per i client con pinning dei certificati. Le sentinelle rimangono cifrate e causano il fallimento dell'autenticazione presso il fornitore anziché esporre testo in chiaro.`}},"secrets%2EegressProxy%2Eenabled":{label:{"v1-ugzvlx-r":`Proxy in uscita per i segreti abilitato`},help:{"v1-u99b1i-2h":`Abilita la sostituzione dei segreti nel traffico in uscita per i sottoprocessi degli agenti ospitati dal Gateway. Valore predefinito: false.`}},session:{label:{"v1-8yh9jr-7":`Sessione`},help:{"v1-j86s32-5d":`Controlli globali di instradamento, reimpostazione, criteri di consegna e manutenzione delle sessioni per la gestione della cronologia delle conversazioni. Mantenere i valori predefiniti, salvo quando servono vincoli più rigorosi di isolamento, conservazione o consegna.`}},"session%2EdmScope":{label:{"v1-ukjin6-g":`Ambito delle sessioni dei messaggi diretti`},help:{"v1-ql362c-5l":`Ambito delle sessioni dei messaggi diretti: "main" mantiene la continuità, mentre "per-peer", "per-channel-peer" e "per-account-channel-peer" aumentano l'isolamento. Utilizzare le modalità isolate per caselle di posta condivise o distribuzioni con più account.`}},"session%2EgroupScope":{label:{"v1-7kncqs-j":`Ambito delle sessioni di gruppo`},help:{"v1-1fdezx2-6i":`Ambito delle sessioni di gruppo/canale: "per-group" mantiene separate le stanze mentre la sessione principale dell'agente le monitora in background, indipendentemente da dmScope; "main" integra il contesto delle stanze nella sessione principale e non richiede monitoraggio. Utilizzare "main" solo per stanze attendibili.`}},"session%2EidentityLinks":{label:{"v1-b28nnm-m":`Collegamenti tra identità per le sessioni`},help:{"v1-1y5jnsm-5n":`Associa le identità canoniche agli ID dei peer con prefisso del provider, in modo che gli utenti equivalenti vengano ricondotti a un'unica conversazione di messaggi diretti (esempio: telegram:123456). Usa questa opzione quando la stessa persona è presente su più canali o account.`}},"session%2EmainKey":{label:{"v1-r57g0n-g":`Chiave della sessione principale`},help:{"v1-18p638h-3q":`Accettato ma ignorato: il suffisso della sessione principale per ciascun agente è sempre "main". Ometti questo campo; l'ambito globale delle sessioni usa invece "global".`}},"session%2Emaintenance":{label:{"v1-p1iywg-j":`Manutenzione delle sessioni`},help:{"v1-imr441-66":`Controlli di manutenzione automatica dell'archivio delle sessioni per l'archiviazione delle sessioni della dashboard, la rimozione in base all'età, i limiti al numero di voci, la conservazione degli archivi di ripristino e la pulizia in base allo spazio allocato su disco. Inizia in modalità warn per osservare l'impatto, quindi passa a enforce dopo aver calibrato le soglie.`}},"session%2Emaintenance%2EarchiveDashboardAfter":{label:{"v1-1ok5zsl-15":`Archivia le sessioni inattive della dashboard dopo`},help:{"v1-1frdtub-5n":"Archivia le sessioni inattive della dashboard dopo questa durata (ad esempio `7d`), così che restino disponibili senza affollare l'elenco delle sessioni attive. Imposta `false` o `0` per disabilitare l'archiviazione automatica delle sessioni della dashboard."}},"session%2Emaintenance%2EcoldStorage":{label:{"v1-353bpe-n":`Archiviazione a freddo delle trascrizioni`},help:{"v1-1kp9s9h-5s":`Sposta le trascrizioni inattive in archivi JSONL compressi, mantenendo i metadati delle sessioni. I file di archivio diventano una parte necessaria della cronologia e devono essere inclusi nei backup. Le modifiche vengono applicate senza riavviare il Gateway.`}},"session%2Emaintenance%2EcoldStorage%2EafterDays":{label:{"v1-1ay0en7-r":`Archivia dopo giorni di inattività`},help:{"v1-zay1q3-5b":`Archivia le trascrizioni dopo questo numero di giorni di inattività (numero intero positivo, valore predefinito 30). Il lavoro in corso è protetto; la modifica della soglia ha effetto al successivo ciclo del processo in background, senza riavviare il Gateway.`}},"session%2Emaintenance%2EcoldStorage%2Eenabled":{label:{"v1-85gcoy-11":`Archivia automaticamente le vecchie trascrizioni`},help:{"v1-6p6vmb-5a":`Abilita l'archiviazione in background delle trascrizioni (valore predefinito: false). Un processo in background verifica ogni minuto la presenza di trascrizioni idonee. Questo criterio di archiviazione esplicito è separato dall'eliminazione e dalla pulizia per il rispetto del limite di spazio su disco.`}},"session%2Emaintenance%2EhighWaterBytes":{label:{"v1-1t9qv0z-u":`Soglia obiettivo di utilizzo del disco per le sessioni`},help:{"v1-143vh09-7z":`Dimensione obiettivo dopo la pulizia in base allo spazio allocato su disco (soglia massima). Il valore predefinito è l'80% di maxDiskBytes; impostalo esplicitamente per recuperare più spazio sui dischi con capacità limitata. Un valore che equivale a zero comporta l'uso del valore predefinito; i valori negativi non sono validi. Per disabilitare il limite di spazio, usa invece maxDiskBytes.`}},"session%2Emaintenance%2EmaxDiskBytes":{label:{"v1-14omfzj-n":`Spazio massimo su disco per le sessioni`},help:{"v1-147lxk3-cj":'Limite di spazio fisico su disco per agente, che include il database principale SQLite, il WAL e gli artefatti conteggiati nella directory delle sessioni (ad esempio `500mb`). Il valore predefinito è `10gb`; i dati protetti possono mantenere l\'utilizzo al di sopra del limite. Quando viene superato, la modalità warn segnala la pressione sullo spazio e la modalità enforce rimuove i vecchi artefatti di reimpostazione/eliminazione, la cronologia senza riferimenti e infine gli archivi creati per rispettare il limite. Gli archivi manuali, quelli creati per i criteri di conservazione temporale, quelli della dashboard, quelli di ripristino e quelli legacy rimangono protetti. Imposta `false`, `0` o `"0"` per disabilitare.'}},"session%2Emaintenance%2EmaxEntries":{label:{"v1-1n4txc9-j":`Numero massimo di voci delle sessioni`},help:{"v1-1w2egrh-7u":`Limita il numero di voci delle sessioni non archiviate (valore predefinito: 5000). Le conversazioni persistenti idonee che superano il limite vengono archiviate insieme alla relativa cronologia; le voci di automazione temporanee vengono rimosse. Gli archivi esistenti non vengono conteggiati ai fini del limite. Le voci attive protette vengono comunque conteggiate e possono mantenere l'archivio dati al di sopra del limite.`}},"session%2Emaintenance%2Emode":{label:{"v1-fudr6r-o":`Modalità di manutenzione delle sessioni`},help:{"v1-bq39hk-6v":`Determina se i criteri di rimozione e di gestione del limite di spazio su disco vengono solo segnalati ("warn") o applicati attivamente ("enforce"). Mantieni "warn" durante l'implementazione iniziale e passa a "enforce" dopo aver verificato che le soglie siano sicure. L'archiviazione a freddo dispone di una propria impostazione esplicita enabled.`}},"session%2Emaintenance%2EpreserveRecent":{label:{"v1-i6rkx1-o":`Conserva le sessioni recenti`},help:{"v1-138q5wx-89":"Protegge le sessioni interattive attive entro questo intervallo (ad esempio `7d`) dalla rimozione automatica della cronologia basata su età, numero di voci e limite di spazio su disco. Se non impostato o impostato su `false`, mantiene il normale criterio che rimuove prima le voci più vecchie. Le righe sintetiche relative a esecuzioni del modello, cron, hook, heartbeat, ACP e sottoagenti restano idonee alla pulizia entro i limiti configurati."}},"session%2Emaintenance%2EpruneAfter":{label:{"v1-1hxlne1-j":`Rimuovi le sessioni dopo`},help:{"v1-1xn50w7-76":"Archivia le conversazioni persistenti idonee e rimuove le voci di automazione temporanee più vecchie di questa durata (valore predefinito `30d`; ad esempio `12h`). Le conversazioni archiviate mantengono la cronologia e possono essere ripristinate; quelle protette o instradabili rimangono attive."}},"session%2Emaintenance%2EresetArchiveRetention":{label:{"v1-1k23ggw-v":`Conservazione degli archivi di reimpostazione delle sessioni`},help:{"v1-16amrs1-7r":"Conservazione basata sull'età per le trascrizioni archiviate (`*.reset.<timestamp>` e `*.deleted.<timestamp>`). Per impostazione predefinita, gli archivi vengono conservati finché il limite di spazio su disco non ne impone la rimozione, a partire dai più vecchi; imposta una durata (ad esempio `30d`) per attivare l'eliminazione in base al tempo effettivamente trascorso, oppure `false` per disattivarla esplicitamente."}},"session%2EnotifyOnCreate":{label:{"v1-19qwl5t-v":`Invia una notifica a Home alla creazione di una sessione`},help:{"v1-c4prn5-8b":`Accoda un avviso di sistema nella sessione Home dell'agente proprietario quando viene creata una sessione (valore predefinito: true). Gli avvisi includono il titolo e i metadati del creatore disponibili e vengono letti al turno o heartbeat successivo di Home. Imposta false per disabilitare; sono esclusi le bozze, le sessioni in incognito, le sessioni interne e le esecuzioni cron pianificate.`}},"session%2Ereset":{label:{"v1-oh2sxm-k":`Criterio di reimpostazione delle sessioni`},help:{"v1-1hmt7n3-6r":`Definisce l'oggetto del criterio di reimpostazione predefinito, usato quando non si applicano impostazioni specifiche per tipo o canale. Per impostazione predefinita, le sessioni non vengono reimpostate automaticamente; usa pianificazioni giornaliere o basate sull'inattività per attivare la reimpostazione automatica, mentre /new e /reset rimangono disponibili in qualsiasi momento.`}},"session%2Ereset%2EatHour":{label:{"v1-3sjhvl-o":`Ora di reimpostazione giornaliera delle sessioni`},help:{"v1-wry8cv-59":`Imposta l'ora locale (0-23) per la modalità di reimpostazione giornaliera, in modo che le sessioni ricomincino a orari prevedibili. Usa questa impostazione con mode=daily e adeguala al fuso orario previsto dall'operatore per un comportamento facilmente comprensibile.`}},"session%2Ereset%2EidleMinutes":{label:{"v1-yoxr77-q":`Minuti di inattività per la reimpostazione delle sessioni`},help:{"v1-1kzj0id-5e":`Imposta l'intervallo di inattività prima della reimpostazione nella modalità basata sull'inattività e può anche fungere da condizione di controllo secondaria nella modalità giornaliera. Usa valori più alti per preservare la continuità o più bassi per conversazioni più recenti e di breve durata.`}},"session%2Ereset%2Emode":{label:{"v1-ern6ub-i":`Modalità di reimpostazione delle sessioni`},help:{"v1-e5ie4w-5b":`Seleziona la strategia di reimpostazione: "none" disabilita la reimpostazione automatica (impostazione predefinita), "daily" esegue la reimpostazione a un'ora configurata e "idle" la esegue dopo un periodo di inattività. /new e /reset restano disponibili in ogni modalità.`}},"session%2EresetByChannel":{label:{"v1-xmfipi-o":`Reimpostazione della sessione per canale`},help:{"v1-1uxsulx-5h":`Fornisce impostazioni di reimpostazione specifiche per canale, indicizzate per ID del provider/canale, per un controllo dettagliato del comportamento. Usa questa opzione solo quando un canale richiede un comportamento di reimpostazione particolare rispetto ai criteri definiti per tipo.`}},"session%2EresetByType":{label:{"v1-1pqdf9f-q":`Reimpostazione della sessione per tipo di chat`},help:{"v1-ypdr7u-52":`Sovrascrive il comportamento di reimpostazione per tipo di chat (diretta, di gruppo, thread) quando le impostazioni predefinite non sono sufficienti. Usa questa opzione quando l'attività nei gruppi o nei thread richiede una frequenza di reimpostazione diversa rispetto ai messaggi diretti.`}},"session%2EresetByType%2Edirect":{label:{"v1-ysq32o-m":`Reimpostazione della sessione (diretta)`},help:{"v1-fjnlp5-56":`Definisce il criterio di reimpostazione per le chat dirette e sostituisce la configurazione di base session.reset per quel tipo. Usa questa opzione come impostazione di riferimento per i messaggi diretti al posto dell'alias legacy dm.`}},"session%2EresetByType%2Egroup":{label:{"v1-kpfypy-l":`Reimpostazione della sessione (gruppo)`},help:{"v1-hl1200-4u":`Definisce il criterio di reimpostazione per le sessioni di chat di gruppo, in cui la continuità e il rumore differiscono da quelli dei messaggi diretti. Usa intervalli di inattività più brevi per i gruppi molto attivi se la deriva del contesto diventa un problema.`}},"session%2EresetByType%2Ethread":{label:{"v1-1jznvzn-m":`Reimpostazione della sessione (thread)`},help:{"v1-1hgpeke-4w":`Definisce il criterio di reimpostazione per le sessioni limitate a un thread, inclusi i flussi di lavoro incentrati sui thread dei canali. Usa questa opzione quando le sessioni dei thread devono scadere prima o dopo rispetto agli altri tipi di chat.`}},"session%2EresetTriggers":{label:{"v1-k9d2el-m":`Trigger di reimpostazione della sessione`},help:{"v1-rcabsw-5a":`Elenca i trigger nei messaggi che forzano la reimpostazione della sessione quando vengono rilevati nei contenuti in entrata. Usali con moderazione per frasi di reimpostazione esplicite, in modo che il contesto non venga perso inaspettatamente durante la normale conversazione.`}},"session%2Escope":{label:{"v1-1j9i0l7-d":`Ambito della sessione`},help:{"v1-axt4ds-5z":`Imposta la strategia di base per il raggruppamento delle sessioni: "per-sender" le separa per mittente, mentre "global" condivide un'unica sessione per contesto del canale. Mantieni "per-sender" per un comportamento multiutente più sicuro, a meno che non sia espressamente richiesto un contesto condiviso.`}},"session%2EsendPolicy":{label:{"v1-1nxtvjb-j":`Criteri di invio della sessione`},help:{"v1-17qpipb-5l":`Controlla le autorizzazioni di invio tra sessioni tramite regole di autorizzazione e negazione valutate in base a channel, chatType e prefissi delle chiavi. Usa questa impostazione per limitare le destinazioni a cui gli strumenti di sessione possono inviare messaggi in ambienti complessi.`}},"session%2EsendPolicy%2Edefault":{label:{"v1-17hik48-y":`Azione predefinita dei criteri di invio della sessione`},help:{"v1-15plhut-53":`Imposta l'azione di ripiego quando nessuna regola sendPolicy corrisponde: "allow" o "deny". Mantieni "allow" per configurazioni più semplici oppure scegli "deny" quando sono necessarie regole di autorizzazione esplicite per ogni destinazione.`}},"session%2EsendPolicy%2Erules":{label:{"v1-uomm0w-p":`Regole dei criteri di invio della sessione`},help:{"v1-o217za-5h":'Regole ordinate di autorizzazione e negazione valutate prima dell\'azione predefinita, ad esempio `{ action: "deny", match: { channel: "discord" } }`. Inserisci prima le regole più specifiche, in modo che quelle generali non prevalgano sulle eccezioni.'}},"session%2EsendPolicy%2Erules%5B%5D%2Eaction":{label:{"v1-sk8rxf-o":`Azione della regola di invio della sessione`},help:{"v1-178vm80-54":`Definisce la decisione della regola come "allow" o "deny" quando i corrispondenti criteri di corrispondenza sono soddisfatti. Dai priorità alle regole di rifiuto quando imponi limiti rigorosi con eccezioni esplicite di autorizzazione.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch":{label:{"v1-i5lkne-n":`Criteri di corrispondenza della regola di invio della sessione`},help:{"v1-18qh5qg-5d":`Definisce condizioni di corrispondenza facoltative per la regola che possono combinare vincoli su channel, chatType e prefisso della chiave. Mantieni i criteri circoscritti affinché l'intento della policy resti chiaro e il debug rimanga semplice.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2Echannel":{label:{"v1-dti9lk-p":`Canale della regola di invio della sessione`},help:{"v1-u5erwx-50":`Limita l'applicazione della regola a un ID di canale o provider specifico (ad esempio discord, telegram, slack). Usa questa opzione quando un canale deve consentire o negare la consegna indipendentemente dagli altri.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EchatType":{label:{"v1-dod3v9-r":`Tipo di chat della regola di invio della sessione`},help:{"v1-7cv4f9-4z":`Limita l'applicazione della regola al tipo di chat (direct, group, thread), così che il comportamento vari in base alla forma della conversazione. Usa questa opzione quando le destinazioni dei messaggi diretti e dei gruppi richiedono limiti di sicurezza diversi.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EkeyPrefix":{label:{"v1-145jj50-s":`Prefisso della chiave della regola di invio della sessione`},help:{"v1-ac4dee-5n":`Verifica la corrispondenza con un prefisso normalizzato della chiave di sessione dopo i passaggi interni di normalizzazione della chiave nei componenti che applicano la policy. Usa questa opzione per controlli generali sui prefissi e preferisci rawKeyPrefix quando è richiesta una corrispondenza esatta con la chiave completa.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2ErawKeyPrefix":{label:{"v1-9eqaoe-w":`Prefisso della chiave non elaborata della regola di invio della sessione`},help:{"v1-1g9w044-5e":`Verifica la corrispondenza con il prefisso non normalizzato della chiave di sessione per applicare criteri mirati alla chiave completa esatta. Usa questa opzione quando il keyPrefix normalizzato è troppo generico e serve una precisione specifica per il prefisso dell'agente o per il trasporto.`}},"session%2Esharing":{label:{"v1-ua4axr-l":`Modalità di condivisione delle sessioni`},help:{"v1-xbh52d-5a":`Controlla quali modalità di collaborazione possono selezionare i proprietari delle sessioni e gli amministratori. I valori booleani omessi sono abilitati per impostazione predefinita; imposta una modalità su false per rimuoverla dal selettore e rifiutare nuove selezioni.`}},"session%2Esharing%2Edrafts":{label:{"v1-egpd9a-k":`Consenti sessioni in bozza`},help:{"v1-1lzap27-2p":`Consente la visibilità in bozza, che nasconde le sessioni agli operatori che non sono né proprietari né amministratori. Valore predefinito: true.`}},"session%2Esharing%2EreadOnly":{label:{"v1-wl9bhk-o":`Consenti sessioni di sola lettura`},help:{"v1-upl3nu-21":`Consente di rendere le sessioni di sola lettura per chi non partecipa. Valore predefinito: true.`}},"session%2Esharing%2Esuggest":{label:{"v1-1a87tux-m":`Consenti sessioni con suggerimenti`},help:{"v1-4i8owu-4g":`Consente la visibilità con suggerimenti. In questa fase applica gli stessi criteri di accesso della modalità di sola lettura; le code dei suggerimenti vengono configurate da una funzionalità successiva. Valore predefinito: true.`}},"session%2Estore":{label:{"v1-1udxgtl-i":`Percorso di archiviazione delle sessioni`},help:{"v1-hreznz-56":`Imposta il percorso del file di archiviazione usato per conservare i record delle sessioni tra i riavvii. Usa un percorso esplicito solo se ti serve un'organizzazione personalizzata del disco, una destinazione specifica per i backup o l'archiviazione su un volume montato.`}},"session%2EthreadBindings":{label:{"v1-hldn3x-n":`Associazioni dei thread delle sessioni`},help:{"v1-zbzihu-4s":`Impostazioni predefinite condivise per la creazione e l'instradamento delle sessioni associate ai thread nei canali supportati. Configura qui le impostazioni predefinite globali e sostituiscile per singolo canale solo quando il comportamento è diverso.`}},"session%2EthreadBindings%2EdefaultSpawnContext":{label:{"v1-yj4mot-k":`Contesto di creazione nei thread`},help:{"v1-1set6nw-4c":`Contesto nativo predefinito del sottoagente per le creazioni associate ai thread. Usa "fork" per partire dalla trascrizione del richiedente o "isolated" per un sottoagente senza contesto preesistente. Valore predefinito: "fork".`}},"session%2EthreadBindings%2Eenabled":{label:{"v1-15vicbp-m":`Associazione ai thread abilitata`},help:{"v1-foomtc-3f":`Interruttore principale globale per la creazione, l'instradamento e la consegna delle sessioni associate ai thread. Disattivalo per disabilitare l'associazione ai thread a livello globale.`}},"session%2EthreadBindings%2EidleHours":{label:{"v1-frd27j-z":`Timeout di inattività dell'associazione ai thread (ore)`},help:{"v1-gffnx3-3h":`Intervallo di inattività predefinito in ore per le sessioni associate ai thread su tutti i provider/canali (0 disabilita la scadenza per inattività). Valore predefinito: 24.`}},"session%2EthreadBindings%2EmaxAgeHours":{label:{"v1-1pyqt5n-u":`Durata massima dell'associazione ai thread (ore)`},help:{"v1-1xfcyhw-39":`Limite massimo assoluto facoltativo in ore per la durata delle sessioni associate ai thread su tutti i provider/canali (0 disabilita il limite assoluto). Valore predefinito: 0.`}},"session%2EthreadBindings%2EspawnSessions":{label:{"v1-hsfsa4-r":`Creazione di sessioni associate ai thread`},help:{"v1-1lqwbdl-46":`Controllo di abilitazione predefinito globale per la creazione di sessioni di lavoro associate ai thread tramite sessions_spawn e le creazioni nei thread di ACP. Valore predefinito: true quando le associazioni ai thread sono abilitate.`}},skills:{label:{"v1-1bk7xrz-6":`Skills`}},"skills%2Eload%2EallowSymlinkTargets":{label:{"v1-i5s6ov-t":`Destinazioni consentite dei collegamenti simbolici delle skill`},help:{"v1-xzybiq-4t":`Directory radice di destinazione reali e attendibili a cui possono risolversi i collegamenti simbolici delle skill quando si trovano al di fuori della radice di origine configurata. Limita questo elenco, ad esempio alla directory delle skill di un repository adiacente.`}},"skills%2Eload%2EextraDirs":{label:{"v1-1ufjbnf-n":`Directory aggiuntive delle skill`},help:{"v1-11o7opu-53":`Directory radice aggiuntive di skill condivise da esaminare con la precedenza più bassa. Usa questa opzione per repository adiacenti o pacchetti di skill condivisi che devono essere disponibili senza copiarli nell'area di lavoro di OpenClaw.`}},"skills%2Eload%2Ewatch":{label:{"v1-fhhyqq-c":`Monitora Skills`},help:{"v1-1ckr2l5-5d":`Abilita il monitoraggio del file system per rilevare modifiche alle definizioni delle skill, così da applicare gli aggiornamenti senza riavviare completamente il processo. Mantienilo abilitato nei flussi di lavoro di sviluppo e disabilitalo nelle immagini di produzione immutabili.`}},"skills%2Eworkshop%2Eautonomous%2Emode":{label:{"v1-1hrc7h4-u":`Modalità autonoma di Skill Workshop`},help:{"v1-1s3kgit-6j":`Controlla l'apprendimento in background: "off" mantiene solo l'invito a fornire suggerimenti, "propose" crea proposte in attesa e "auto" applica le proposte acquisite ed esegue una revisione settimanale delle skill gestite da Workshop tramite normali modifiche ai file. Valore predefinito: "auto".`}},surfaces:{label:{"v1-exl2ye-g":`Criteri delle superfici`},help:{"v1-vgtjbs-50":`Override dei criteri dei messaggi per ciascuna superficie, indicizzati in base all'ID risolto della superficie di recapito. Usa questa opzione solo quando una superficie distribuita richiede una gestione delle risposte silenziose più restrittiva rispetto a quella predefinita dell'agente.`}},"surfaces%2E*%2EsilentReply":{label:{"v1-1n816d1-r":`Criterio delle risposte silenziose della superficie`},help:{"v1-12zgc3n-60":`Sostituisce il criterio delle risposte silenziose per una superficie di recapito risolta. I campi non impostati ereditano agents.defaults.silentReply; usa ID di superficie specifici per evitare che comportamenti interni o propri di un gruppo si estendano ad altre destinazioni.`}},talk:{label:{"v1-15ukbjj-4":`Conversazione`},help:{"v1-1gx10xa-5g":`Impostazioni di sintesi vocale della modalità Talk per l'identità vocale, la selezione del modello, il formato di output e il comportamento in caso di interruzione. Usa questa sezione per ottimizzare l'esperienza vocale dell'utente tenendo sotto controllo latenza e costi.`}},"talk%2EagentId":{label:{"v1-17bcfby-a":`Agente Talk`},help:{"v1-iee5l9-2b":`Agente a cui appartengono le sessioni Talk create senza una chiave di sessione esplicitamente associata a un agente.`}},"talk%2EconsultFastMode":{label:{"v1-12natsq-m":`Modalità rapida delle consultazioni Talk`},help:{"v1-syf3xk-2o":`Usa questa impostazione per impostare su true o false la modalità rapida dell'esecuzione ordinaria dell'agente alla base delle consultazioni Talk in tempo reale.`}},"talk%2EconsultThinkingLevel":{label:{"v1-f04pev-r":`Livello di ragionamento delle consultazioni Talk`},help:{"v1-1ft5njw-2o":`Usa questa impostazione per sovrascrivere il livello di ragionamento dell'esecuzione ordinaria dell'agente alla base delle consultazioni Talk in tempo reale.`}},"talk%2EinterruptOnSpeech":{label:{"v1-12q9u31-o":`Interruzione di Talk quando l'utente parla`},help:{"v1-8n9q4o-3l":`Se impostato su true (valore predefinito), interrompe la voce dell'assistente quando l'utente inizia a parlare in modalità Talk. Mantieni l'opzione abilitata per consentire l'alternanza dei turni nella conversazione.`}},"talk%2Eprovider":{label:{"v1-1y50zho-k":`Provider attivo di Talk`},help:{"v1-wgnxhg-1g":`ID del provider Talk attivo (ad esempio "acme-speech").`}},"talk%2Eproviders":{label:{"v1-1ifkkv5-m":`Impostazioni dei provider Talk`},help:{"v1-oh0yuv-30":`Impostazioni Talk specifiche per provider, indicizzate per ID del provider. Durante la migrazione, preferisci queste impostazioni alle chiavi legacy talk.*.`}},"talk%2Eproviders%2E*":{label:{"v1-1bo3c2y-k":`Configurazione del provider Talk`},help:{"v1-36pblg-1r":`Campi di configurazione Talk gestiti dal provider con l'ID corrispondente.`}},"talk%2Eproviders%2E*%2EapiKey":{label:{"v1-ln76q3-l":`Chiave API del provider Talk`},help:{"v1-1a1p9wp-v":`Chiave API del provider per la modalità Talk.`}},"talk%2Erealtime":{label:{"v1-xsdfxg-d":`Talk in tempo reale`},help:{"v1-c2re7j-3z":`Provider, modello, voce, modalità, trasporto e strategia di ragionamento di Talk in tempo reale. Mantieni la configurazione del provider vocale/TTS in talk.provider e talk.providers.`}},"talk%2Erealtime%2Ebrain":{label:{"v1-7nqi8o-j":`Ragionamento di Talk in tempo reale`},help:{"v1-opsatw-37":`Strategia di ragionamento di Talk: agent-consult per l'assistenza dell'agente mediata dal Gateway, direct-tools per le chiamate locali agli strumenti oppure none.`}},"talk%2Erealtime%2EconsultRouting":{label:{"v1-1nxl3sq-t":`Instradamento delle consultazioni di Talk in tempo reale`},help:{"v1-10qjcvk-5f":`Inoltro di riserva tramite Gateway per le trascrizioni finali dell'utente quando il provider in tempo reale salta openclaw_agent_consult. provider-direct mantiene le risposte del provider; force-agent-consult instrada tramite OpenClaw.`}},"talk%2Erealtime%2Einstructions":{label:{"v1-1aogivp-q":`Istruzioni di Talk in tempo reale`},help:{"v1-1jaaj84-5p":`Istruzioni di sistema aggiuntive accodate al prompt integrato di OpenClaw per Talk in tempo reale. Usale per lo stile vocale, il tono e altri comportamenti in tempo reale del provider, mantenendo intatte le indicazioni di agent-consult.`}},"talk%2Erealtime%2Emode":{label:{"v1-1ulyfkf-i":`Modalità di Talk in tempo reale`},help:{"v1-1u2xui1-1l":`Modalità di esecuzione di Talk: realtime, stt-tts oppure transcription.`}},"talk%2Erealtime%2Emodel":{label:{"v1-3tgxll-j":`Modello di Talk in tempo reale`},help:{"v1-amou5a-27":`Sostituzione dell'ID del modello del provider in tempo reale per le sessioni Talk nel browser o gestite dal Gateway.`}},"talk%2Erealtime%2EprefixPaddingMs":{label:{"v1-1n2zx1c-x":`Margine audio iniziale di Talk in tempo reale (ms)`},help:{"v1-1cwg07n-22":`Millisecondi di audio conservati prima del rilevamento dell'attività vocale in tempo reale.`}},"talk%2Erealtime%2Eprovider":{label:{"v1-13pps61-m":`Provider di Talk in tempo reale`},help:{"v1-wwsmpt-1o":`ID del provider vocale in tempo reale attivo, ad esempio openai o google.`}},"talk%2Erealtime%2Eproviders":{label:{"v1-zi8arq-v":`Impostazioni dei provider in tempo reale di Talk`},help:{"v1-ruagcu-1r":`Impostazioni vocali in tempo reale specifiche per provider, indicizzate per ID del provider.`}},"talk%2Erealtime%2Eproviders%2E*":{label:{"v1-n5oah5-t":`Configurazione del provider in tempo reale di Talk`},help:{"v1-edfpxm-1u":`Configurazione vocale in tempo reale gestita dal provider con l'ID corrispondente.`}},"talk%2Erealtime%2Eproviders%2E*%2EapiKey":{label:{"v1-1kd7m42-u":`Chiave API del provider in tempo reale di Talk`},help:{"v1-1fbmgpx-z":`Chiave API del provider per Talk in tempo reale.`}},"talk%2Erealtime%2EreasoningEffort":{label:{"v1-1cxnmcm-u":`Livello di ragionamento di Talk in tempo reale`},help:{"v1-157xd3e-2t":`Livello di ragionamento specifico del provider per le sessioni di Talk in tempo reale, ad esempio minimal, low, medium o high.`}},"talk%2Erealtime%2EsilenceDurationMs":{label:{"v1-190chw8-z":`Durata del silenzio di Talk in tempo reale (ms)`},help:{"v1-1grnu06-1y":`Millisecondi di silenzio prima che il turno dell'utente in Talk in tempo reale venga confermato.`}},"talk%2Erealtime%2EspeakerVoice":{label:{"v1-hgae7v-r":`Voce del parlante di Talk in tempo reale`},help:{"v1-1kgb166-2h":`Nome della voce del parlante da usare al posto di quello predefinito del provider in tempo reale per le sessioni di Talk nel browser o gestite dal Gateway.`}},"talk%2Erealtime%2EspeakerVoiceId":{label:{"v1-10l8f2s-u":`ID della voce del parlante di Talk in tempo reale`},help:{"v1-1k8w6vk-2f":`ID della voce del parlante da usare al posto di quello predefinito del provider in tempo reale per le sessioni di Talk nel browser o gestite dal Gateway.`}},"talk%2Erealtime%2Etransport":{label:{"v1-1mlwsll-n":`Trasporto di Talk in tempo reale`},help:{"v1-2otjgn-2g":`Trasporto di byte/sessioni di Talk: webrtc, provider-websocket, gateway-relay o managed-room.`}},"talk%2Erealtime%2EvadThreshold":{label:{"v1-1plwtg4-r":`Soglia VAD in tempo reale di Talk`},help:{"v1-nf5l2t-2j":`Soglia di rilevamento dell'attività vocale in tempo reale da 0 (massima sensibilità) a 1 (minima sensibilità).`}},"talk%2EsilenceTimeoutMs":{label:{"v1-q6e4ju-p":`Timeout di silenzio di Talk (ms)`},help:{"v1-1kim32f-59":`Millisecondi di silenzio dell'utente prima che la modalità Talk finalizzi e invii la trascrizione corrente. Lasciare non impostato per mantenere l'intervallo di pausa predefinito della piattaforma (700 ms su macOS e Android, 900 ms su iOS).`}},"talk%2EspeechLocale":{label:{"v1-gbwzpr-i":`Impostazioni locali per il riconoscimento vocale di Talk`},help:{"v1-1un3x4l-4c":`Identificatore delle impostazioni locali BCP 47 per il riconoscimento vocale di Talk sui nodi dei dispositivi e per la voce di sistema iOS usata come alternativa, ad esempio "ru-RU". Lasciare non impostato per usare il valore predefinito di ciascun dispositivo.`}},telemetry:{label:{"v1-sqprmo-9":`Telemetria`},help:{"v1-1o5tru3-55":`Consenso esplicito alle statistiche anonime sulle funzionalità allegate alla verifica giornaliera degli aggiornamenti. Le statistiche sulle funzionalità sono disabilitate per impostazione predefinita e non includono mai messaggi, credenziali o identificatori.`}},"telemetry%2EconsentedAt":{label:{"v1-1cb2euy-10":`Data e ora del consenso alle statistiche sulle funzionalità`},help:{"v1-1t051az-3t":`Data e ora in formato ISO che registrano quando l'operatore ha accettato o rifiutato le statistiche anonime sulle funzionalità. Impedisce alla procedura guidata di configurazione di richiedere nuovamente il consenso.`}},"telemetry%2Eenabled":{label:{"v1-166i16f-s":`Statistiche anonime sulle funzionalità`},help:{"v1-1ptrwuq-4r":`Condivide i nomi dei canali e dei provider abilitati, il numero di plugin e il numero di sessioni recenti durante la verifica giornaliera degli aggiornamenti. Disabilitato per impostazione predefinita e sempre disabilitato quando DO_NOT_TRACK=1.`}},tools:{label:{"v1-15cdqf0-5":`Strumenti`},help:{"v1-1el54kl-5h":`Infrastruttura degli strumenti e impostazioni predefinite comuni a più agenti. Le sezioni di pari livello alla radice gestiscono l'infrastruttura e le impostazioni predefinite comuni a più agenti; agents.defaults gestisce il comportamento del ciclo dell'agente; le voci dei singoli agenti possono sovrascrivere entrambe, dove supportato.`}},"tools%2EagentToAgent":{label:{"v1-19yyyqk-q":`Accesso agli strumenti tra agenti`},help:{"v1-1ynpa5f-cf":`Criteri per le chiamate agli strumenti di sessione tra agenti: invio, elenco, cronologia, ricerca e lettura dello stato (impostazione predefinita: abilitato). Usa allow per limitare le coppie di agenti; enabled=false blocca l'accesso ordinario tra agenti. Le sessioni dei sottoagenti nativi e le sessioni figlie ACP di proprietà del richiedente restano accessibili con visibilità tree o all. Per una separazione rigorosa, imposta tools.sessions.visibility su agent o self (tree consente comunque l'accesso alle sessioni figlie native/ACP di proprietà del richiedente), oppure usa Gateway separati.`}},"tools%2EagentToAgent%2Eallow":{label:{"v1-96jndk-v":`Elenco delle destinazioni consentite tra agenti`},help:{"v1-1jt2ari-76":`ID degli agenti o pattern con * che possono partecipare alle chiamate tra agenti; sia l'agente richiedente sia quello di destinazione devono corrispondere. L'accesso tra agenti è attivo per impostazione predefinita e allow omesso o vuoto consente ogni coppia. Imposta un elenco esplicito per limitare l'accesso; le voci vuote negano l'accesso.`}},"tools%2EagentToAgent%2Eenabled":{label:{"v1-1petv53-q":`Abilita lo strumento tra agenti`},help:{"v1-w950oq-ba":`Abilita l'accesso agli strumenti di sessione tra agenti (impostazione predefinita: true); allow omesso o vuoto consente ogni coppia di agenti. Imposta false per bloccare l'accesso ordinario tra agenti; le sessioni dei sottoagenti nativi e le sessioni figlie ACP di proprietà del richiedente restano accessibili con visibilità tree o all. Per una separazione rigorosa, imposta tools.sessions.visibility su agent o self (tree consente comunque l'accesso alle sessioni figlie native/ACP di proprietà del richiedente), oppure usa Gateway separati.`}},"tools%2Eallow":{label:{"v1-1hmvki6-e":`Elenco degli strumenti consentiti`},help:{"v1-1is3eaq-4v":`Elenco assoluto degli strumenti consentiti che sostituisce le impostazioni predefinite derivate dal profilo per ambienti con requisiti rigorosi. Usalo solo quando intendi eseguire un sottoinsieme attentamente selezionato delle funzionalità degli strumenti.`}},"tools%2EalsoAllow":{label:{"v1-x011gj-o":`Aggiunte all'elenco degli strumenti consentiti`},help:{"v1-1xw9zp8-57":`Voci aggiuntive dell'elenco degli strumenti consentiti, integrate nel profilo degli strumenti selezionato e nei criteri predefiniti. Mantieni questo elenco breve ed esplicito, in modo che le verifiche possano identificare rapidamente le eccezioni intenzionali ai criteri.`}},"tools%2EbyProvider":{label:{"v1-ca7c4x-n":`Criteri degli strumenti per fornitore`},help:{"v1-1ecljob-4y":`Eccezioni ai criteri di autorizzazione o blocco degli strumenti per ciascun fornitore, indicizzate per ID del canale/fornitore, per adattare le funzionalità a ciascuna interfaccia. Usale quando un fornitore richiede controlli più rigorosi rispetto ai criteri globali degli strumenti.`}},"tools%2EcodeMode":{label:{"v1-194jdgf-9":`Modalità codice`},help:{"v1-1ecc39k-6k":'Modalità codice generica di OpenClaw. Se omessa a livello globale, il valore predefinito è `"auto"`; un oggetto definito esplicitamente senza `enabled` resta disattivato. Le esecuzioni dell\'agente con questa modalità attiva espongono al modello solo `exec` e `wait` e accedono agli strumenti standard tramite il bridge del catalogo.'}},"tools%2EcodeMode%2Eenabled":{label:{"v1-162yoj6-g":`Abilita modalità codice`},help:{"v1-rgstxz-aj":"Attivazione globale della modalità codice di OpenClaw. Se l'impostazione globale è completamente assente, il valore predefinito è `\"auto\"`; un oggetto definito esplicitamente senza `enabled` resta disattivato. `\"auto\"` attiva la modalità per i modelli che privilegiano il catalogo, mentre `true` la attiva per le esecuzioni che supportano l'uso di strumenti. Le impostazioni di attivazione specifiche dell'agente e del modello hanno la precedenza. Se il runtime non è disponibile, un'esecuzione con questa modalità attiva viene bloccata per sicurezza anziché esporre l'elenco completo degli strumenti."}},"tools%2EcodeMode%2Eexecutor":{label:{"v1-lbpzic-i":`Esecutore della modalità codice`},help:{"v1-l8nlk2-6x":`Esecutore JavaScript: "node" (predefinito) usa Node vm per il codice attendibile e non è una sandbox di sicurezza; "quickjs" usa il plugin QuickJS WASM incluso per l'esecuzione guest con protezioni rafforzate. Le autorizzazioni degli strumenti si applicano a entrambi. Se l'esecutore selezionato non è disponibile, l'esecuzione viene bloccata per sicurezza.`}},"tools%2EcodeMode%2EmaxOutputBytes":{label:{"v1-aewvtz-m":`Limite di output della modalità codice`},help:{"v1-1hmij9q-1n":`Numero massimo di byte serializzati restituiti tramite l'output della modalità codice.`}},"tools%2EcodeMode%2EmaxPendingToolCalls":{label:{"v1-1keh21t-s":`Limite delle chiamate agli strumenti in sospeso in modalità codice`},help:{"v1-3b5tyd-2i":`Numero massimo di chiamate annidate e simultanee agli strumenti che una VM in modalità codice può avviare prima di dover riprendere l'esecuzione in un secondo momento.`}},"tools%2EcodeMode%2EmaxSearchLimit":{label:{"v1-1f02yk9-s":`Numero massimo di risultati di ricerca in modalità codice`},help:{"v1-1gpue5r-28":`Numero massimo di risultati di ricerca nel catalogo nascosto che un programma in modalità codice può richiedere.`}},"tools%2EcodeMode%2EmaxSnapshotBytes":{label:{"v1-1tt9adm-o":`Limite degli snapshot in modalità codice`},help:{"v1-1mmgkqy-1x":`Numero massimo di byte serializzati conservati per un singolo snapshot QuickJS sospeso.`}},"tools%2EcodeMode%2EmemoryLimitBytes":{label:{"v1-5bockh-m":`Limite di memoria in modalità codice`},help:{"v1-xetora-6n":`Limite dell'heap guest di QuickJS o budget indicativo dell'heap V8 del worker Node, in byte. L'overhead del runtime Node e le allocazioni minime del motore influiscono sul budget effettivo; i buffer esterni e l'RSS del processo sono esclusi. Questo non costituisce una garanzia di sicurezza.`}},"tools%2EcodeMode%2Emode":{label:{"v1-1a1ijjo-h":`Interfaccia della modalità codice`},help:{"v1-dsp2b9-2x":'Interfaccia esposta al modello. È supportato solo "only": espone `exec` e `wait` della modalità codice e nasconde gli strumenti normali.'}},"tools%2EcodeMode%2EsearchDefaultLimit":{label:{"v1-1xkxvss-w":`Numero predefinito di risultati di ricerca in modalità codice`},help:{"v1-1io42lu-2m":"Numero predefinito di risultati di ricerca nel catalogo nascosto restituiti da `catalog.search` in modalità codice."}},"tools%2EcodeMode%2EsnapshotTtlSeconds":{label:{"v1-xs8rwp-m":`TTL degli snapshot in modalità codice`},help:{"v1-1nxfczz-28":"Per quanto tempo è possibile riprendere con `wait` le esecuzioni sospese di Code Mode prima che scadano."}},"tools%2EcodeMode%2EtimeoutMs":{label:{"v1-1rjrbio-h":`Timeout della modalità codice`},help:{"v1-8csycm-1p":"Durata massima in millisecondi di una singola chiamata `exec` o `wait` in modalità codice."}},"tools%2Edeny":{label:{"v1-fwuia7-d":`Elenco degli strumenti bloccati`},help:{"v1-wilr1b-4p":`Elenco globale che blocca gli strumenti indicati anche quando le regole del profilo o del provider li consentirebbero. Usa le regole di blocco per interventi di emergenza e una difesa a più livelli a lungo termine.`}},"tools%2Eelevated":{label:{"v1-15z7aw7-k":`Accesso agli strumenti con privilegi elevati`},help:{"v1-ehcm0r-5a":`Controlli di accesso agli strumenti con privilegi elevati per le interfacce di comando privilegiate, che dovrebbero essere accessibili solo ai mittenti attendibili. Mantieni questa opzione disabilitata, a meno che i flussi di lavoro degli operatori non richiedano esplicitamente azioni con privilegi elevati.`}},"tools%2Eelevated%2EallowFrom":{label:{"v1-yx3m99-p":`Regole di autorizzazione per gli strumenti con privilegi elevati`},help:{"v1-1u9bhih-54":`Regole di autorizzazione dei mittenti per gli strumenti con privilegi elevati, generalmente organizzate per formati di identità del canale/provider. Usa identità specifiche ed esplicite, in modo che i comandi con privilegi elevati non possano essere attivati da utenti non previsti.`}},"tools%2Eelevated%2Eenabled":{label:{"v1-15kpc2g-r":`Abilita l'accesso agli strumenti con privilegi elevati`},help:{"v1-1n8oyal-4l":`Abilita il percorso di esecuzione degli strumenti con privilegi elevati quando i controlli sul mittente e sui criteri vengono superati. Mantieni questa opzione disabilitata nei canali pubblici o condivisi e abilitala solo in contesti attendibili gestiti dal proprietario.`}},"tools%2Eexec":{label:{"v1-33cqoe-9":`Strumento exec`},help:{"v1-p5piic-56":`Raggruppamento dei criteri dello strumento exec per l'host di esecuzione della shell, la modalità di sicurezza, il comportamento delle approvazioni e le associazioni in fase di esecuzione. Mantieni impostazioni predefinite conservative in produzione e applica restrizioni più rigorose ai percorsi di esecuzione con privilegi elevati.`}},"tools%2Eexec%2EapplyPatch%2EallowModels":{label:{"v1-1pc6erm-r":`Elenco dei modelli consentiti per apply_patch`},help:{"v1-4q5ovf-1x":`Elenco facoltativo di ID dei modelli consentiti (ad es. "gpt-5.4" o "openai/gpt-5.4").`}},"tools%2Eexec%2EapplyPatch%2Eenabled":{label:{"v1-c3mjij-i":`Abilita apply_patch`},help:{"v1-1erkir4-31":`Abilita o disabilita apply_patch per i modelli OpenAI e OpenAI Codex quando consentito dai criteri degli strumenti (valore predefinito: true).`}},"tools%2Eexec%2EapplyPatch%2EworkspaceOnly":{label:{"v1-1mlvoxc-q":`apply_patch solo nell'area di lavoro`},help:{"v1-x2z207-3o":`Limita i percorsi di apply_patch alla directory dell'area di lavoro (valore predefinito: true). Imposta false per consentire la scrittura al di fuori dell'area di lavoro (pericoloso).`}},"tools%2Eexec%2EapprovalRunningNoticeMs":{label:{"v1-s8uk67-x":`Avviso di esecuzione dopo l'approvazione di exec (ms)`},help:{"v1-1gwwann-4z":`Ritardo in millisecondi prima di mostrare un avviso di esecuzione in corso dopo che è stata concessa un'approvazione di exec. Aumentalo per ridurre lo sfarfallio con i comandi rapidi oppure diminuiscilo per fornire un riscontro più tempestivo all'operatore.`}},"tools%2Eexec%2Eask":{label:{"v1-1kx7cwd-8":`Richiesta di approvazione di exec`}},"tools%2Eexec%2EcommandHighlighting":{label:{"v1-1n3ojuz-p":`Evidenziazione dei comandi exec`},help:{"v1-kyxd4o-4n":`Mostra l'evidenziazione dei comandi generata dal parser nelle richieste di approvazione di exec (valore predefinito: false). Abilita questa opzione per visualizzare il testo dei comandi evidenziato senza modificare i criteri di approvazione di exec.`}},"tools%2Eexec%2EgrantExpiryDays":{label:{"v1-2d156s-s":`Scadenza delle autorizzazioni permanenti (giorni)`},help:{"v1-5uxe2j-6r":`Durata predefinita, in giorni (1-3650), delle autorizzazioni permanenti create tramite allow-always nelle approvazioni delle automazioni. Se non impostata, le autorizzazioni restano valide fino alla revoca o alla modifica dell'automazione a cui appartengono. Le condizioni vengono fissate alla creazione, quindi la modifica di questo valore influisce solo sulle autorizzazioni future.`}},"tools%2Eexec%2Ehost":{label:{"v1-6z76n1-b":`Destinazione di exec`},help:{"v1-rno1mf-5q":`Seleziona la strategia di destinazione per l'esecuzione dei comandi shell. Usa "auto" per un comportamento basato sull'ambiente di esecuzione (sandbox se disponibile, altrimenti gateway), oppure imposta esplicitamente sandbox/gateway/node quando serve un ambiente fisso.`}},"tools%2Eexec%2Emode":{label:{"v1-luiaev-9":`Modalità di esecuzione`},help:{"v1-1wi6t4l-5q":`Selettore normalizzato dei criteri di esecuzione. Usa "auto" per sottoporre al classificatore i casi privi di approvazione, "ask" per sottoporli a revisione umana, "allowlist" per consentire solo comandi sicuri deterministici oppure "full" per operazioni locali attendibili.`}},"tools%2Eexec%2Enode":{label:{"v1-s03avl-h":`Associazione del nodo di esecuzione`},help:{"v1-rfnz54-4s":`Configurazione dell'associazione dei nodi per gli strumenti di esecuzione quando l'esecuzione dei comandi è delegata ai nodi connessi. Usa un'associazione esplicita dei nodi solo quando è necessario l'instradamento su più nodi.`}},"tools%2Eexec%2EnotifyOnExit":{label:{"v1-rwarum-j":`Notifica al termine dell'esecuzione`},help:{"v1-1ounlvx-3q":`Se impostato su true (valore predefinito), la terminazione delle sessioni di esecuzione in background e gli eventi del ciclo di vita dell'esecuzione sui nodi accodano un evento di sistema e richiedono un heartbeat.`}},"tools%2Eexec%2EnotifyOnExitEmptySuccess":{label:{"v1-1hs7mlg-s":`Notifica per esecuzione riuscita senza output`},help:{"v1-1wx4xxd-3d":`Se impostato su true, le esecuzioni in background terminate correttamente senza output accodano comunque un evento di sistema di completamento (valore predefinito: false).`}},"tools%2Eexec%2EpathPrepend":{label:{"v1-18ajzln-h":`Directory da anteporre a PATH per l'esecuzione`},help:{"v1-s1aimc-1r":`Directory da anteporre a PATH per le esecuzioni (gateway/sandbox).`}},"tools%2Eexec%2Ereviewer":{label:{"v1-1dgtjz-d":`Revisore dell'esecuzione`},help:{"v1-12y548k-4x":`Revisore exec basato su un modello, utilizzato dalla modalità automatica prima di ricorrere all'approvazione umana. Configura qui un modello alternativo dedicato se vuoi isolare la revisione exec dal modello dell'agente principale.`}},"tools%2Eexec%2Ereviewer%2EfastMode":{label:{"v1-hd75ia-n":`Modalità rapida del revisore di esecuzione`},help:{"v1-175bx14-8u":`Modalità rapida opzionale per le revisioni di approvazione di OpenClaw: true richiede l'elaborazione prioritaria sui percorsi OpenAI Responses e ChatGPT/OAuth supportati; false richiede l'elaborazione standard. Omettere per mantenere le impostazioni predefinite del provider. La modalità rapida può comportare costi maggiori ed è soggetta alla disponibilità del provider. Non configura Codex Guardian nativo.`}},"tools%2Eexec%2Ereviewer%2Emodel":{label:{"v1-90ol5u-j":`Modello del revisore exec`},help:{"v1-1lltiy5-3i":`Sostituzione facoltativa del provider/modello per l'agente revisore exec. Omettila per riutilizzare il modello principale configurato per l'agente di destinazione.`}},"tools%2Eexec%2Ereviewer%2Ethinking":{label:{"v1-s17i85-m":`Ragionamento del revisore di esecuzione`},help:{"v1-yg2gby-6u":`Livello di ragionamento opzionale per le revisioni di approvazione di OpenClaw basate su modelli: minimal, low, medium, high, xhigh o max. Omettere per mantenere le impostazioni predefinite del provider. I livelli supportati vengono normalizzati per il modello selezionato. Non configura Codex Guardian nativo.`}},"tools%2Eexec%2Ereviewer%2EtimeoutMs":{label:{"v1-1shnxjr-q":`Timeout del revisore exec (ms)`},help:{"v1-1o30chi-3w":`Timeout del revisore exec in millisecondi per ciascuna fase di preparazione e completamento del modello, prima di ricorrere all'approvazione umana (valore predefinito: 30000).`}},"tools%2Eexec%2EsafeBinProfiles":{label:{"v1-ez9qvm-m":`Profili dei binari sicuri di exec`},help:{"v1-4cdcwe-29":`Profili di sicurezza facoltativi per ciascun binario (limiti degli argomenti posizionali + flag consentiti/vietati).`}},"tools%2Eexec%2EsafeBins":{label:{"v1-21op89-e":`Binari sicuri di exec`},help:{"v1-1of1m2s-21":`Consenti l'esecuzione di binari sicuri che accettano input solo da stdin senza voci esplicite nell'elenco degli elementi consentiti.`}},"tools%2Eexec%2EsafeBinTrustedDirs":{label:{"v1-vpqq4p-q":`Directory attendibili dei binari sicuri di exec`},help:{"v1-zljbcn-2v":`Directory aggiuntive dichiarate esplicitamente attendibili per i controlli dei percorsi dei binari sicuri (le voci di PATH non sono mai considerate attendibili automaticamente).`}},"tools%2Eexec%2Esecurity":{label:{"v1-om3dyq-d":`Sicurezza di exec`}},"tools%2Eexec%2EstrictInlineEval":{label:{"v1-pzx6o5-s":`Richiedi approvazione per la valutazione inline`},help:{"v1-jkmgo7-5z":"Richiedi l'approvazione esplicita per le forme di valutazione inline degli interpreti, come `python -c`, `node -e`, `ruby -e` o `osascript -e`. Impedisce il riutilizzo silenzioso dell'elenco degli elementi consentiti e, per queste forme, sostituisce il consenso permanente con una richiesta di approvazione a ogni utilizzo."}},"tools%2Eexec%2EtimeoutSeconds":{label:{"v1-1d0xrlr-m":`Timeout di esecuzione (secondi)`}},"tools%2Efs%2EworkspaceOnly":{label:{"v1-nx841l-n":`Strumenti del file system limitati all'area di lavoro`},help:{"v1-1mhuvka-2s":`Limita gli strumenti del file system (read/write/edit/apply_patch) alla directory dell'area di lavoro (valore predefinito: false).`}},"tools%2Egithub":{label:{"v1-jfcpb6-y":`Identità GitHub CLI e autore Git`},help:{"v1-1fl77im-5s":`Profilo locale gestito di GitHub CLI e autore Git facoltativo per gli strumenti dell'agente. Ometti questo oggetto per mantenere l'account e l'autore nativi dell'utente che esegue il Gateway; le credenziali remote del repository non vengono mai sovrascritte.`}},"tools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-durd6y-g":`Email dell'autore Git`},help:{"v1-kol5g6-1i":`Email facoltativa dell'autore e del committer Git, valida solo per il processo.`}},"tools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-pv12jh-f":`Nome dell'autore Git`},help:{"v1-z5bl1f-1h":`Nome facoltativo dell'autore e del committer Git, valido solo per il processo.`}},"tools%2Egithub%2Ekind":{label:{"v1-1ubt2yv-m":`Tipo di credenziale GitHub`},help:{"v1-qi3qun-3q":`Identifica un profilo OAuth gestito la cui credenziale di rinnovo a rotazione è di proprietà del Gateway. I profili per cui questo valore è omesso utilizzano un token di accesso personale.`}},"tools%2Egithub%2EprofileId":{label:{"v1-ssneaz-m":`Versione del profilo GitHub`},help:{"v1-4lzl0-27":`Versione del profilo generata e opaca, utilizzata per cambiare le credenziali gestite in modo atomico.`}},"tools%2Elinks%2Eenabled":{label:{"v1-yims6g-p":`Abilita la comprensione dei link`},help:{"v1-23t2io-59":`Abilita la preelaborazione automatica per la comprensione dei link, così da poter riassumere i contenuti degli URL prima del ragionamento dell'agente. Mantieni l'opzione abilitata per un contesto più ricco e disabilitala quando è necessario ridurre l'elaborazione al minimo indispensabile.`}},"tools%2Elinks%2EmaxLinks":{label:{"v1-l7d76c-s":`Numero massimo di link per la comprensione dei link`},help:{"v1-ksxmcv-52":`Numero massimo di link espansi per turno durante la comprensione dei link. Usa valori più bassi per contenere latenza e costi nelle conversazioni molto attive e valori più alti quando il contesto di più link è fondamentale.`}},"tools%2Elinks%2Emodels":{label:{"v1-t894bf-p":`Modelli per la comprensione dei link`},help:{"v1-6j3mnw-5a":`Elenco dei modelli preferiti per le attività di comprensione dei link, valutati in ordine come alternative quando supportato. Usa prima modelli leggeri per i riepiloghi ordinari e modelli più pesanti solo quando necessario.`}},"tools%2Elinks%2Escope":{label:{"v1-x79nuj-o":`Ambito della comprensione dei link`},help:{"v1-183cwpa-55":`Controlla quando viene eseguita la comprensione dei link in base al contesto della conversazione e al tipo di messaggio. Mantieni un ambito limitato per evitare recuperi non necessari nei messaggi in cui i link non sono utilizzabili.`}},"tools%2Elinks%2EtimeoutSeconds":{label:{"v1-hh7o78-w":`Timeout della comprensione dei link (sec)`},help:{"v1-61v30o-4p":`Tempo massimo in secondi per la comprensione di ciascun link, trascorso il quale i link non risolti vengono ignorati. Mantieni questo limite contenuto per evitare lunghe attese quando i siti esterni sono lenti o irraggiungibili.`}},"tools%2EloopDetection%2Eenabled":{label:{"v1-c9sqnr-j":`Rilevamento dei cicli di chiamate agli strumenti`},help:{"v1-1e3rls8-5g":`Controlla il rilevamento dei cicli degli strumenti basato sulla cronologia recente e la protezione dopo la compattazione. Ometti questa impostazione per mantenere disattivato il rilevamento sulla cronologia recente e attivata la protezione dopo la compattazione. Imposta true per abilitare entrambi o false per disabilitare entrambi.`}},"tools%2Emedia%2Eaudio%2Eattachments":{label:{"v1-1r0kwy-11":`Criteri per gli allegati nella comprensione audio`},help:{"v1-1s3t9s5-3o":`Scegli quali allegati audio corrispondenti elaborare. Elabora solo il primo, a meno che tu non voglia trascrivere più allegati.`}},"tools%2Emedia%2Eaudio%2EechoFormat":{label:{"v1-15fud4j-m":`Formato di riproposizione della trascrizione`},help:{"v1-glpdzh-3i":`Formatta la trascrizione da inviare usando il segnaposto {transcript}. Mantieni intatto il segnaposto affinché il messaggio includa la trascrizione.`}},"tools%2Emedia%2Eaudio%2EechoTranscript":{label:{"v1-1gi9x8r-n":`Invia la trascrizione alla chat`},help:{"v1-1dedp8c-3r":`Invia la trascrizione audio alla chat di origine prima dell'elaborazione da parte dell'agente. Abilita questa opzione quando gli utenti devono verificare ciò che il sistema ha sentito.`}},"tools%2Emedia%2Eaudio%2Eenabled":{label:{"v1-1ne86nm-q":`Abilita la comprensione audio`},help:{"v1-1v0x7te-2m":`Abilita la comprensione audio per trascrivere note vocali o clip audio e includerle nel contesto dell'agente.`}},"tools%2Emedia%2Eaudio%2Elanguage":{label:{"v1-1jzzbi3-s":`Lingua per la comprensione audio`},help:{"v1-1ruqt97-3z":`Indicazione della lingua predefinita per i fornitori di trascrizione audio. Impostala quando la lingua parlata principale è nota e il rilevamento da parte del fornitore non è affidabile.`}},"tools%2Emedia%2Eaudio%2EmaxBytes":{label:{"v1-hqnl72-t":`Byte massimi per la comprensione audio`},help:{"v1-1mcckc8-43":`Limite predefinito per le dimensioni dell'audio in ingresso per i modelli configurati e rilevati automaticamente. Impostalo sulle dimensioni massime della registrazione che i fornitori e la rete devono accettare.`}},"tools%2Emedia%2Eaudio%2EmaxChars":{label:{"v1-1vhezc0-t":`Caratteri massimi per la comprensione audio`},help:{"v1-eo1dp-43":`Lunghezza massima predefinita della trascrizione per i modelli configurati e rilevati automaticamente. Usa un valore più basso per evitare che le note vocali lunghe espandano il contesto dell'agente.`}},"tools%2Emedia%2Eaudio%2EpreferredModel":{label:{"v1-1h7yz8z-z":`Modello preferito per la comprensione audio`},help:{"v1-1n5zya1-3c":`Dai priorità a una voce di tools.media.models contrassegnata per capacità per la trascrizione audio rispetto alle altre alternative compatibili.`}},"tools%2Emedia%2Eaudio%2Eprompt":{label:{"v1-1gqi94r-q":`Prompt per la comprensione audio`},help:{"v1-1v5jtay-4b":`Prompt predefinito per la trascrizione audio quando non è sovrascritto da una voce del modello. Mantieni stabile l'istruzione quando i flussi di lavoro a valle dipendono dallo stile della trascrizione.`}},"tools%2Emedia%2Eaudio%2Escope":{label:{"v1-erazqj-p":`Ambito della comprensione audio`},help:{"v1-1pptfg0-3w":`Limita la comprensione audio in base al canale, al tipo di chat o alla chiave di origine. Mantieni ristretto questo ambito quando la trascrizione automatica è delicata o costosa.`}},"tools%2Emedia%2Eaudio%2EtimeoutSeconds":{label:{"v1-1ja2x9w-x":`Timeout della comprensione audio (sec)`},help:{"v1-n8wc6c-3b":`Timeout predefinito per le richieste di comprensione audio. Aumentalo per registrazioni lunghe o modelli di trascrizione locali più lenti.`}},"tools%2Emedia%2Econcurrency":{label:{"v1-1ru9noi-v":`Concorrenza della comprensione multimediale`},help:{"v1-13kr9np-58":`Numero massimo di operazioni simultanee di comprensione multimediale per turno, tra attività su immagini, audio e video. Riduci questo valore nelle installazioni con risorse limitate per evitare la saturazione della CPU o della rete.`}},"tools%2Emedia%2Eimage%2Eattachments":{label:{"v1-19jrjw9-11":`Criterio per gli allegati nella comprensione delle immagini`},help:{"v1-11hofbw-3e":`Scegli quali allegati immagine corrispondenti elaborare. Elabora solo il primo, a meno che tu non intenda analizzare più immagini.`}},"tools%2Emedia%2Eimage%2Eenabled":{label:{"v1-dbw751-q":`Abilita la comprensione delle immagini`},help:{"v1-1b2zw34-50":`Abilita la comprensione delle immagini per interpretare le immagini allegate o a cui si fa riferimento e convertirle in contesto testuale. Disabilitala se hai bisogno di usare solo testo o vuoi evitare i costi di elaborazione delle immagini.`}},"tools%2Emedia%2Eimage%2EmaxBytes":{label:{"v1-943dvt-t":`Byte massimi per la comprensione delle immagini`},help:{"v1-jwwpd1-3v":`Limite predefinito delle dimensioni delle immagini in ingresso per i modelli configurati e rilevati automaticamente. Imposta questo valore in base ai limiti del payload del fornitore e alla larghezza di banda dell'ambiente di distribuzione.`}},"tools%2Emedia%2Eimage%2EmaxChars":{label:{"v1-1p6mqsn-t":`Caratteri massimi per la comprensione delle immagini`},help:{"v1-ebnxhk-3q":`Lunghezza massima predefinita della descrizione delle immagini. Usa un valore inferiore per un contesto compatto o un valore superiore per l'OCR e l'analisi dettagliata delle scene.`}},"tools%2Emedia%2Eimage%2EpreferredModel":{label:{"v1-gy243w-z":`Modello preferito per la comprensione delle immagini`},help:{"v1-1o2uwo6-3c":`Dai priorità a una voce di tools.media.models contrassegnata con un tag di capacità per la comprensione delle immagini rispetto alle restanti alternative compatibili.`}},"tools%2Emedia%2Eimage%2Eprompt":{label:{"v1-i4kxh2-q":`Prompt per la comprensione delle immagini`},help:{"v1-1jdcu8b-3u":`Prompt predefinito per la comprensione delle immagini quando una voce non lo sovrascrive. Mantienilo deterministico quando i sistemi che lo utilizzano richiedono descrizioni stabili.`}},"tools%2Emedia%2Eimage%2Escope":{label:{"v1-xpdk4k-p":`Ambito della comprensione delle immagini`},help:{"v1-tievo1-3s":`Limita la comprensione delle immagini in base al canale, al tipo di chat o alla chiave di origine. Mantieni un ambito ristretto nei canali molto attivi o non attendibili per controllare l'elaborazione.`}},"tools%2Emedia%2Eimage%2EtimeoutSeconds":{label:{"v1-60t1jb-x":`Timeout della comprensione delle immagini (sec)`},help:{"v1-1wcm84x-31":`Timeout predefinito per le richieste di comprensione delle immagini. Aumentalo per immagini di grandi dimensioni o modelli di visione locali più lenti.`}},"tools%2Emedia%2Emodels":{label:{"v1-b1r5p4-x":`Modelli condivisi per la comprensione multimediale`},help:{"v1-f34u65-47":`Elenco canonico dei modelli per la comprensione multimediale. Usa i tag di capacità image, audio o video per ogni voce, in modo che ogni pipeline selezioni solo alternative compatibili.`}},"tools%2Emedia%2Evideo%2Eattachments":{label:{"v1-e4yzf-11":`Criteri per gli allegati nella comprensione dei video`},help:{"v1-1qm1qrc-3e":`Scegli quali allegati video corrispondenti vengono elaborati. Elabora solo il primo, a meno che tu non intenda analizzare più video.`}},"tools%2Emedia%2Evideo%2Eenabled":{label:{"v1-sg3427-q":`Abilita la comprensione dei video`},help:{"v1-1ltx5gl-58":`Abilita la comprensione dei video per riassumere le clip in testo da usare nei ragionamenti e nelle risposte successive. Disabilitala quando l'elaborazione dei video non è consentita dai criteri o è troppo costosa per la tua installazione.`}},"tools%2Emedia%2Evideo%2EmaxBytes":{label:{"v1-wzauwr-t":`Limite massimo di byte per la comprensione dei video`},help:{"v1-2mp77v-3v":`Limite predefinito per le dimensioni dei video in ingresso per i modelli configurati e rilevati automaticamente. Impostalo in base ai limiti del payload del fornitore e alla larghezza di banda disponibile nell'installazione.`}},"tools%2Emedia%2Evideo%2EmaxChars":{label:{"v1-gb00od-t":`Limite massimo di caratteri per la comprensione dei video`},help:{"v1-1j0x40b-3j":`Lunghezza massima predefinita della descrizione dei video. Usa un valore più basso per un contesto compatto o un valore più alto per riepiloghi dettagliati delle scene.`}},"tools%2Emedia%2Evideo%2EpreferredModel":{label:{"v1-11pflaa-z":`Modello preferito per la comprensione dei video`},help:{"v1-1cygq5k-3c":`Dai la preferenza a una voce di tools.media.models contrassegnata per capacità per la comprensione dei video, prima delle altre alternative compatibili.`}},"tools%2Emedia%2Evideo%2Eprompt":{label:{"v1-dq4his-q":`Prompt per la comprensione dei video`},help:{"v1-ul2jx4-3r":`Prompt predefinito per la comprensione dei video quando una voce non lo sostituisce. Mantienilo deterministico quando i sistemi che lo utilizzano richiedono riepiloghi stabili.`}},"tools%2Emedia%2Evideo%2Escope":{label:{"v1-iwg12i-p":`Ambito della comprensione dei video`},help:{"v1-7gfrx3-3s":`Limita la comprensione dei video in base al canale, al tipo di chat o alla chiave di origine. Mantieni questo ambito ristretto nei canali molto attivi o non attendibili per controllare l'elaborazione.`}},"tools%2Emedia%2Evideo%2EtimeoutSeconds":{label:{"v1-syt2z1-x":`Timeout per la comprensione dei video (sec)`},help:{"v1-e8rzsy-33":`Timeout predefinito per le richieste di comprensione dei video. Aumentalo per clip più lunghe o modelli di analisi locali più lenti.`}},"tools%2Emessage%2Eactions%2Eallow":{label:{"v1-a6trwv-o":`Elenco delle azioni consentite per i messaggi`},help:{"v1-1iceqwa-5c":`Elenco globale delle azioni consentite per lo strumento message. Usalo solo quando l'intero ambiente di esecuzione deve esporre e accettare un insieme ridotto di azioni; per gli agenti pubblici o in sandbox, preferisci elenchi di azioni consentite specifici per agente.`}},"tools%2Emessage%2Ebroadcast%2Eenabled":{label:{"v1-awk06q-o":`Abilita la diffusione dei messaggi`},help:{"v1-1ms74z7-14":`Abilita l'azione broadcast (valore predefinito: true).`}},"tools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-lzee7y-12":`Consenti l'invio tra contesti (tra provider)`},help:{"v1-276qxo-2s":`Consenti l'invio tra provider diversi (valore predefinito: true). Imposta false per bloccare l'invio di messaggi tra provider diversi.`}},"tools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-1ujg1kq-z":`Consenti invii tra contesti (stesso provider)`},help:{"v1-1sg4x49-1z":`Consenti invii ad altri canali dello stesso provider (valore predefinito: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eenabled":{label:{"v1-4n38r9-k":`Indicatore di invio tra contesti`},help:{"v1-1fg6jrp-1z":`Aggiungi un indicatore visibile dell'origine per gli invii tra contesti (valore predefinito: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eprefix":{label:{"v1-vaqy0z-r":`Prefisso dell'indicatore di invio tra contesti`},help:{"v1-eblsru-1p":`Prefisso testuale per gli indicatori di invio tra contesti (supporta "{channel}").`}},"tools%2Emessage%2EcrossContext%2Emarker%2Esuffix":{label:{"v1-wa9bei-r":`Suffisso dell'indicatore di invio tra contesti`},help:{"v1-1nk0jub-1p":`Suffisso testuale per gli indicatori di invio tra contesti (supporta "{channel}").`}},"tools%2Eprofile":{label:{"v1-89srgu-c":`Profilo degli strumenti`},help:{"v1-h6k98q-5k":`Nome del profilo globale degli strumenti usato per selezionare una base predefinita di regole per gli strumenti prima di applicare le deroghe di autorizzazione o blocco. Usalo per mantenere un assetto coerente dell'ambiente tra gli agenti e mantieni stabili i nomi dei profili.`}},"tools%2Esandbox":{label:{"v1-5qrg9w-j":`Regole degli strumenti nella sandbox`},help:{"v1-ea7awo-4k":`Contenitore delle regole degli strumenti per le esecuzioni degli agenti nella sandbox, che consente di definire limiti distinti alle funzionalità disponibili. Usalo per rafforzare la sicurezza nei contesti sandbox.`}},"tools%2Esandbox%2Etools":{label:{"v1-y6y4ns-u":`Regole di autorizzazione e blocco degli strumenti nella sandbox`},help:{"v1-ub701o-4t":`Regole di autorizzazione e blocco degli strumenti applicate quando gli agenti vengono eseguiti in ambienti sandbox. Mantieni le autorizzazioni al minimo affinché le attività nella sandbox non possano estendersi ad azioni esterne non necessarie.`}},"tools%2Esessions%2Evisibility":{label:{"v1-sk4wbc-o":`Visibilità degli strumenti di sessione`},help:{"v1-1vtq2rh-c5":`Controlla a quali sessioni possono accedere sessions_list/sessions_history/sessions_search/sessions_send/session_status. ("all", valore predefinito = qualsiasi sessione sul Gateway, incluse quelle di altri agenti e utenti; "agent" = qualsiasi sessione con l'ID dell'agente corrente; "self" = solo quella corrente; "tree" = sessione corrente + sessioni dei sottoagenti avviati). L'accesso tra agenti è attivo per impostazione predefinita e regolato da tools.agentToAgent; usa una visibilità più limitata per restringere l'accesso.`}},"tools%2Esubagents":{label:{"v1-5a8obi-k":`Criteri degli strumenti dei sottoagenti`},help:{"v1-1xoug01-4z":`Insieme di criteri degli strumenti per i sottoagenti avviati, che consente di limitare o ampliare la disponibilità degli strumenti rispetto alle impostazioni predefinite dell'agente padre. Usalo per mantenere le capacità degli agenti delegati entro l'ambito dell'attività.`}},"tools%2Esubagents%2Etools":{label:{"v1-m8ydym-v":`Criteri di autorizzazione/blocco degli strumenti dei sottoagenti`},help:{"v1-7vxsbf-5d":`Criteri di autorizzazione/blocco degli strumenti applicati agli ambienti di esecuzione dei sottoagenti avviati. Mantieni un ambito più ristretto rispetto a quello dell'agente padre. Gli strumenti riservati all'agente padre, come progress_card, sono sempre bloccati, anche tramite allow/alsoAllow.`}},"tools%2Eswarm":{label:{"v1-1a8h35r-5":`Sciame`},help:{"v1-1q96vvs-45":`Orchestrazione dei sottoagenti in modalità raccolta. Abilitata per impostazione predefinita; imposta false per disabilitarla. Le autorizzazioni degli strumenti si applicano comunque ad agents_wait e alle opzioni di avvio dello sciame.`}},"tools%2Eswarm%2EdefaultAgentId":{label:{"v1-wwvduv-j":`Agente predefinito dello sciame`},help:{"v1-p4alpg-2m":`Agente di destinazione predefinito per gli avvii dello sciame che omettono agentId. L'elenco dei sottoagenti consentiti continua ad applicarsi.`}},"tools%2Eswarm%2Eenabled":{label:{"v1-1ppe1ta-c":`Abilita sciame`},help:{"v1-1nnnrq9-2e":`Abilita i sottoagenti in modalità raccolta e agents_wait. Attivo per impostazione predefinita; imposta false per disabilitarlo.`}},"tools%2Eswarm%2EmaxChildrenPerGroup":{label:{"v1-1vzvgye-t":`Processi figli attivi dello sciame per gruppo`},help:{"v1-kfx6qp-1c":`Numero massimo di processi figli di raccolta attivi per gruppo dello sciame.`}},"tools%2Eswarm%2EmaxConcurrent":{label:{"v1-1dmgf1f-p":`Processi figli simultanei dello sciame`},help:{"v1-1d46jtm-1s":`Numero massimo di processi figli di raccolta in esecuzione simultanea per gruppo dello sciame.`}},"tools%2Eswarm%2EmaxTotalPerGroup":{label:{"v1-1r1vzms-u":`Processi figli totali dello sciame per gruppo`},help:{"v1-1gc9vl1-1e":`Numero massimo di processi di raccolta avviati nell'intero ciclo di vita di ciascun gruppo dello sciame.`}},"tools%2Eswarm%2EwaitTimeoutSecondsMax":{label:{"v1-1naot35-q":`Timeout massimo di attesa dello sciame`},help:{"v1-bog18y-1g":`Timeout massimo accettato da agents_wait, in secondi.`}},"tools%2EtoolSearch":{label:{"v1-pq1rnt-b":`Ricerca strumenti`},help:{"v1-s0kx04-7y":`Compatta i cataloghi di strumenti di grandi dimensioni di OpenClaw, MCP e dei client. Se non viene specificata alcuna impostazione, gli ambienti di esecuzione di OpenClaw usano automaticamente Tool Search strutturato; Code Mode, se attivo, ha la precedenza e Codex usa la propria ricerca nativa. Imposta false per disabilitarlo, true per il bridge di codice oppure usa il formato oggetto per scegliere una modalità.`}},"tools%2EtoolSearch%2EcodeTimeoutMs":{label:{"v1-yyul8h-o":`Timeout del codice di ricerca strumenti`},help:{"v1-105r499-34":"Numero massimo di millisecondi per una singola esecuzione di `tool_search_code`. L'ambiente di esecuzione limita i valori all'intervallo supportato da 1 a 60 secondi."}},"tools%2EtoolSearch%2Eenabled":{label:{"v1-14qildc-i":`Abilita la ricerca strumenti`},help:{"v1-1vm3hfr-4h":"Abilita la ricerca strumenti. Quando è attiva, OpenClaw nasconde i cataloghi di strumenti di grandi dimensioni dietro `tool_search_code` o strumenti strutturati di ricerca, descrizione e chiamata durante le esecuzioni nell'ambiente integrato."}},"tools%2EtoolSearch%2EmaxSearchLimit":{label:{"v1-396rdd-n":`Numero massimo di risultati della ricerca strumenti`},help:{"v1-7du4kh-32":`Numero massimo di risultati della ricerca di strumenti che un modello può richiedere. In fase di esecuzione, i valori vengono limitati all'intervallo supportato 1..50.`}},"tools%2EtoolSearch%2Emode":{label:{"v1-1qs9bxi-j":`Interfaccia di ricerca degli strumenti`},help:{"v1-jybcbe-7x":'Scegli l\'interfaccia esposta al modello: "code" espone `tool_search_code`; "tools" espone strumenti strutturati di ricerca/descrizione/chiamata come alternativa; "directory" mantiene visibile un elenco limitato di strumenti, espone un insieme limitato di schemi probabilmente utili o necessari e rende accessibili gli altri tramite ricerca/descrizione/chiamata.'}},"tools%2EtoolSearch%2EsearchDefaultLimit":{label:{"v1-fq001m-r":`Risultati predefiniti della ricerca di strumenti`},help:{"v1-1uchq7t-39":"Numero predefinito di risultati della ricerca di strumenti restituiti quando il modello omette un limite. In fase di esecuzione, questo valore viene limitato a `maxSearchLimit`."}},"tools%2EupdatePlan":{label:{"v1-1u23ymq-r":`Abilita lo strumento per i piani strutturati`},help:{"v1-1xgegme-4o":"Strumento di stato unificato `progress_card` per piani persistenti e note descrittive nelle sessioni principali. Abilitato per impostazione predefinita; imposta false per disabilitarlo. Non è mai disponibile per i sottoagenti."}},"tools%2Eweb":{label:{"v1-3b07wa-9":`Strumenti web`},help:{"v1-fpsy5-4y":`Raggruppamento delle regole degli strumenti web per configurare provider di ricerca/recupero, limiti e comportamento alternativo. Mantieni le impostazioni abilitate coerenti con la disponibilità delle chiavi API e con le regole per le connessioni di rete in uscita.`}},"tools%2Eweb%2Efetch%2EcacheTtlMinutes":{label:{"v1-1odhu2w-p":`TTL della cache di recupero web (min)`},help:{"v1-1hk89qp-17":`TTL della cache in minuti per i risultati di web_fetch.`}},"tools%2Eweb%2Efetch%2Eenabled":{label:{"v1-zuwpji-l":`Abilita lo strumento di recupero web`},help:{"v1-yrswld-1f":`Abilita lo strumento web_fetch (recupero HTTP leggero).`}},"tools%2Eweb%2Efetch%2Eheaders":{label:{"v1-3129be-p":`Intestazioni delle richieste di recupero web`},help:{"v1-16bjkv5-me":"Intestazioni aggiuntive inviate con le richieste web_fetch dirette, ad esempio intestazioni per l'instradamento del gateway o per l'autenticazione. Ogni valore configurato viene trattato come sensibile e oscurato nella configurazione esposta e nelle acquisizioni di debug. I valori sono stringhe semplici, supportano la sostituzione ${VAR} e la sequenza di escape globale $${VAR} per i valori letterali e vengono inviati agli URL scelti dal modello. Le voci vengono convalidate durante la creazione della richiesta anziché al caricamento della configurazione, quindi un nome non valido o un valore non inviabile viene scartato e registrato nei log anziché disabilitare la funzionalità; vengono scartate anche le intestazioni Accept, Accept-Language, User-Agent e quelle di framing come Transfer-Encoding. Usa tools.web.fetch.userAgent per modificare lo user agent. I reindirizzamenti tra origini diverse mantengono solo le intestazioni sicure incluse nell'elenco consentito di guarded-fetch; la modifica delle intestazioni effettivamente inviate suddivide la cache di recupero in partizioni."}},"tools%2Eweb%2Efetch%2EmaxChars":{label:{"v1-1wbzc7m-j":`Numero massimo di caratteri per il recupero web`},help:{"v1-12d1fw7-1d":`Numero massimo di caratteri restituiti da web_fetch (con troncamento).`}},"tools%2Eweb%2Efetch%2EmaxCharsCap":{label:{"v1-141potx-o":`Limite massimo assoluto di caratteri per il recupero web`},help:{"v1-cl2mf1-1v":`Limite massimo assoluto per maxChars di web_fetch (si applica alla configurazione e alle chiamate allo strumento).`}},"tools%2Eweb%2Efetch%2EmaxRedirects":{label:{"v1-81lxou-n":`Numero massimo di reindirizzamenti per il recupero web`},help:{"v1-t6eak9-1h":`Numero massimo di reindirizzamenti consentiti per web_fetch (valore predefinito: 3).`}},"tools%2Eweb%2Efetch%2EmaxResponseBytes":{label:{"v1-uabe8-z":`Dimensione massima del download per il recupero web (byte)`},help:{"v1-q6ld9c-10":`Dimensione massima del download prima del troncamento.`}},"tools%2Eweb%2Efetch%2Eprovider":{label:{"v1-1xu05t2-i":`Fornitore del recupero web`},help:{"v1-6pb3nv-v":`ID del provider di fallback per il recupero web.`}},"tools%2Eweb%2Efetch%2Ereadability":{label:{"v1-32zds-w":`Estrazione con Readability per il recupero web`},help:{"v1-19exqzx-2c":`Usa Readability per estrarre il contenuto principale dall'HTML (in caso di errore, esegue una pulizia di base dell'HTML).`}},"tools%2Eweb%2Efetch%2EssrfPolicy":{label:{"v1-jaq5z9-l":`Criteri SSRF per il recupero web`},help:{"v1-qtn7zx-3c":`Deroghe circoscritte ai criteri SSRF per web_fetch. Mantieni un ambito ristretto e abilitale solo per ambienti proxy noti nella rete locale.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowedHostnames":{label:{"v1-1r9zld3-r":`Nomi host consentiti per il recupero web`},help:{"v1-1j9ctya-35":`Nomi host esatti o indirizzi IP letterali consentiti per web_fetch, incluse le destinazioni altrimenti bloccate. Mantieni l'elenco al minimo.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-t82ara-13":`Consenti l'intervallo IPv6 locale univoco per il recupero web`},help:{"v1-1eyz55i-3b":`Consenti gli indirizzi IPv6 locali univoci (fc00::/7) per la compatibilità con proxy fake-IP attendibili come sing-box, Clash o Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-4hkyhg-14":`Consenti l'intervallo di benchmark RFC 2544 per il recupero web`},help:{"v1-u5asdb-2y":`Consenti gli indirizzi IP dell'intervallo di benchmark RFC 2544 (198.18.0.0/15) per la compatibilità con proxy fake-IP come Clash o Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1gm3p1b-r":`Nomi host bloccati per il recupero web`},help:{"v1-1164vvk-66":`Pattern dei nomi host bloccati prima della risoluzione DNS e delle regole di autorizzazione a ogni reindirizzamento di web_fetch. Supporta host esatti e "*.example.com" solo per i sottodomini; aggiungi "example.com" separatamente per bloccare il dominio radice. Se vuoto o non impostato, non aggiunge alcun blocco.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1rhrboq-17":`Recupero web: consenti accesso alla rete privata (pericoloso)`},help:{"v1-2s6mv7-3t":`Consente a web_fetch di accedere a destinazioni di rete private e interne. Mantieni disabilitato a meno che gli URL selezionati dal modello non siano attendibili in questa installazione.`}},"tools%2Eweb%2Efetch%2EtimeoutSeconds":{label:{"v1-ry7npa-n":`Timeout del recupero web (sec)`},help:{"v1-1c3yfr4-16":`Timeout in secondi per le richieste web_fetch.`}},"tools%2Eweb%2Efetch%2EuserAgent":{label:{"v1-5t3azc-k":`User-Agent del recupero web`},help:{"v1-s7pe8j-1e":`Sostituisce l'intestazione User-Agent per le richieste web_fetch.`}},"tools%2Eweb%2Efetch%2EuseTrustedEnvProxy":{label:{"v1-1pkpnd9-r":`Proxy d'ambiente attendibile per il recupero web`},help:{"v1-1ypkqj7-54":`Instrada web_fetch attraverso un proxy HTTP(S) attendibile configurato tramite variabili d'ambiente e lascia che il proxy risolva il DNS. Abilita solo se il proxy è controllato dall'operatore e applica i criteri per il traffico in uscita dopo la risoluzione DNS.`}},"tools%2Eweb%2Esearch%2EcacheTtlMinutes":{label:{"v1-14u7axu-q":`TTL della cache di ricerca web (min)`},help:{"v1-6trzlf-18":`TTL della cache in minuti per i risultati di web_search.`}},"tools%2Eweb%2Esearch%2Eenabled":{label:{"v1-1yn3rki-m":`Abilita lo strumento di ricerca web`},help:{"v1-n1cm4y-27":`Abilita web_search gestito e la ricerca nativa di Codex facoltativa per i modelli compatibili.`}},"tools%2Eweb%2Esearch%2EmaxResults":{label:{"v1-jy940f-m":`Numero massimo di risultati della ricerca web`},help:{"v1-mrw7mi-z":`Numero di risultati da restituire (1-10).`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EallowedDomains":{label:{"v1-aqtmld-l":`Domini consentiti per Codex`},help:{"v1-1cv4y44-43":`Elenco dei domini consentiti per web_search nativo di Codex. Nei turni con ricerca ospitata nativa, limita anche web_fetch gestito; i turni con provider gestito rimangono invariati.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EcontextSize":{label:{"v1-1s2nw4o-p":`Dimensione del contesto di ricerca di Codex`},help:{"v1-antack-1u":`Indicazione della dimensione del contesto di ricerca nativa di Codex: "low", "medium" o "high".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Eenabled":{label:{"v1-1eejtq4-u":`Abilita la ricerca web nativa di Codex`},help:{"v1-ek2jzd-1k":`Abilita la ricerca web nativa di Codex per i modelli compatibili con Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Emode":{label:{"v1-1eic0y9-l":`Modalità di ricerca web di Codex`},help:{"v1-1ahyq9f-32":`Preferenza per la ricerca web nativa di Codex: "cached" (predefinita; nei turni Codex senza restrizioni viene risolta come live) o "live".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecity":{label:{"v1-1p5e722-f":`Città dell'utente Codex`},help:{"v1-1y95orp-1d":`Città approssimativa inviata alla ricerca web nativa di Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecountry":{label:{"v1-u0nthl-i":`Paese dell'utente Codex`},help:{"v1-1xkm5ms-1g":`Paese approssimativo inviato alla ricerca web nativa di Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Eregion":{label:{"v1-1pmca79-h":`Regione dell'utente Codex`},help:{"v1-lhar02-1l":`Regione o stato approssimativi inviati alla ricerca web nativa di Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Etimezone":{label:{"v1-by3d62-j":`Fuso orario dell'utente Codex`},help:{"v1-fgv9fh-1h":`Fuso orario approssimativo inviato alla ricerca web nativa di Codex.`}},"tools%2Eweb%2Esearch%2Eprovider":{label:{"v1-rztytk-j":`Provider di ricerca web`},help:{"v1-10omglr-1x":`ID del provider di ricerca. Se omesso, viene rilevato automaticamente dalle chiavi API disponibili.`}},"tools%2Eweb%2Esearch%2EtimeoutSeconds":{label:{"v1-2gxsb4-o":`Timeout della ricerca web (sec)`},help:{"v1-i0egvw-17":`Timeout in secondi per le richieste web_search.`}},transcripts:{label:{"v1-1iqk6o8-b":`Trascrizioni`},help:{"v1-1i0sc09-66":`Impostazioni principali di acquisizione delle trascrizioni per gli appunti delle riunioni, gli strumenti dell'agente con funzionalità di registrazione e le fonti configurate per l'avvio automatico delle riunioni in tempo reale. Per impostazione predefinita, i plugin per le riunioni acquisiscono appunti persistenti; imposta enabled su false per disattivare l'acquisizione a livello globale.`}},"transcripts%2EautoStart":{label:{"v1-1ocjrmc-u":`Fonti di avvio automatico delle trascrizioni`},help:{"v1-1mzsl79-5s":`Fonti di trascrizione in tempo reale gestite automaticamente dall'avvio del gateway. Ogni voce è abilitata per il solo fatto di essere presente; rimuovi una voce per disabilitare la relativa fonte. Le fonti acquisiscono continuamente, a meno che whenOccupied non sia abilitato.`}},"transcripts%2EautoStart%5B%5D%2EaccountId":{label:{"v1-1ffe8lp-l":`ID account della trascrizione`},help:{"v1-6g2kjj-4b":`Identificatore facoltativo dell'account o dello spazio di lavoro del provider per le fonti di trascrizione che richiedono la distinzione tra account. Usa il formato dell'ID account documentato dal provider.`}},"transcripts%2EautoStart%5B%5D%2EchannelId":{label:{"v1-ujvqt-l":`ID canale della trascrizione`},help:{"v1-1lk9d5o-4u":`ID del canale del provider per la sorgente della trascrizione in tempo reale, ad esempio un canale vocale Discord o un canale per le riunioni rapide Slack. Verifica la semantica degli ID specifica del provider prima di abilitare l'avvio automatico.`}},"transcripts%2EautoStart%5B%5D%2EguildId":{label:{"v1-tdpg2t-g":`ID del server Discord`},help:{"v1-fyfgnk-4l":`ID facoltativo del server Discord per le sorgenti di trascrizione vocale Discord. Configuralo con il channelId corrispondente quando il provider richiede la ricerca del canale vocale all'interno di un server.`}},"transcripts%2EautoStart%5B%5D%2EmeetingUrl":{label:{"v1-f1fo9f-m":`URL della riunione da trascrivere`},help:{"v1-1xtt9ci-4f":`URL facoltativo della riunione per i provider che si connettono tramite URL anziché tramite ID del canale. Usa solo link a riunioni attendibili, perché l'avvio automatico potrebbe connettersi alla riunione e acquisirne i contenuti.`}},"transcripts%2EautoStart%5B%5D%2EproviderId":{label:{"v1-1dnfgvi-t":`ID del provider della sorgente di trascrizione`},help:{"v1-1uur06p-3s":`ID del provider della sorgente di trascrizione, ad esempio un provider vocale Discord o un futuro provider per le riunioni rapide Slack. Usa l'ID esatto esposto dal plugin del provider.`}},"transcripts%2EautoStart%5B%5D%2EsessionId":{label:{"v1-1q57lkc-l":`ID della sessione di trascrizione`},help:{"v1-xyo4x5-5o":`ID fisso facoltativo della sessione di trascrizione per questa sorgente ad avvio automatico. Ignorato quando whenOccupied è true. Lascia il campo non impostato per generare gli ID automaticamente, a meno che non ti serva un selettore giornaliero stabile e tu possa evitare conflitti nello stesso giorno.`}},"transcripts%2EautoStart%5B%5D%2Etitle":{label:{"v1-11w5opp-g":`Titolo della trascrizione`},help:{"v1-ycjnmp-5y":`Titolo facoltativo per le future acquisizioni di trascrizioni. La modifica dei soli titoli mantiene attive le acquisizioni in corso e non modifica il titolo assegnato inizialmente né le note salvate. Le altre modifiche alla sorgente mantengono il normale comportamento di riavvio.`}},"transcripts%2EautoStart%5B%5D%2EwhenOccupied":{label:{"v1-12ewhvp-w":`Acquisizione delle trascrizioni in presenza di persone`},help:{"v1-34jid4-78":`Avvia una nuova sessione di trascrizione ogni volta che nella sorgente sono presenti persone e la interrompe (generando note) quando l'ultima persona esce. Richiede un provider che segnali la presenza di persone, come discord-voice. Valore predefinito: false (acquisizione continua dall'avvio del gateway).`}},"transcripts%2Eenabled":{label:{"v1-d2c4ax-j":`Trascrizioni abilitate`},help:{"v1-fyqqr0-6d":`Abilita il salvataggio persistente delle note automatiche delle riunioni, lo strumento transcripts dell'agente e le sorgenti configurate per l'avvio automatico. Valore predefinito: true. Imposta false per disabilitare la persistenza e lo strumento; la modalità esplicita di trascrizione delle riunioni mantiene la propria finestra limitata di contenuti recenti in tempo reale.`}},tts:{label:{"v1-bmxkk9-e":`Sintesi vocale`},help:{"v1-1o27tk2-4n":`Criteri di sintesi vocale per leggere ad alta voce le risposte dell'agente nelle interfacce vocali o audio supportate. Mantieni questa funzione disabilitata, a meno che la riproduzione vocale non faccia parte del flusso di lavoro dell'operatore o dell'utente.`}},"tts%2Epersona":{label:{"v1-118fea6-b":`Profilo vocale TTS`},help:{"v1-1r0opcb-29":`ID del profilo vocale TTS predefinito. Le preferenze locali del profilo vocale TTS possono sostituire questo valore per ciascun host.`}},"tts%2Epersonas":{label:{"v1-1gi7idj-c":`Profili vocali TTS`},help:{"v1-19aybhl-2l":`Profili vocali TTS con nome che definiscono un'identità vocale stabile e associazioni vocali specifiche del provider.`}},"tts%2Epersonas%2E*":{label:{"v1-118fea6-b":`Profilo vocale TTS`},help:{"v1-10s52ah-2l":`Un profilo vocale TTS. Usa associazioni specifiche del provider per indicare voci, modelli e template di prompt precisi.`}},"tts%2Epersonas%2E*%2Eproviders":{label:{"v1-dji537-t":`Associazioni dei fornitori per la persona TTS`},help:{"v1-993jop-3e":`Associazioni della persona TTS specifiche per fornitore, indicizzate per ID del fornitore vocale. Per la persona attiva, queste vengono unite a tts.providers, sovrascrivendo i valori corrispondenti.`}},"tts%2Eproviders":{label:{"v1-1y7c1ro-l":`Impostazioni dei fornitori TTS`},help:{"v1-1k80nl4-4y":`Impostazioni TTS specifiche per fornitore, indicizzate per ID del fornitore vocale. Usa queste impostazioni anziché le chiavi di primo livello specifiche dei fornitori inclusi, in modo che i plugin vocali restino indipendenti dallo schema di configurazione principale.`}},"tts%2Eproviders%2E*":{label:{"v1-15ged0b-j":`Configurazione del fornitore TTS`},help:{"v1-dwapva-3d":`Configurazione TTS specifica per un singolo ID di fornitore vocale. Limita i campi all'ambito del plugin che gestisce quel fornitore.`}},"tts%2Eproviders%2E*%2EapiKey":{label:{"v1-68k8k0-k":`Chiave API del fornitore TTS`},help:{"v1-1m2fj0i-2o":`Chiave API del fornitore utilizzata da quel fornitore vocale quando il suo plugin richiede l'accesso autenticato al TTS.`}},tui:{label:{"v1-c8hus1-b":`Interfaccia del terminale`},help:{"v1-1fg9vw2-3s":`Impostazioni di visualizzazione dell'interfaccia del terminale. Usa questa sezione per le preferenze di presentazione specifiche del terminale, senza modificare il comportamento di Gateway o di altre interfacce.`}},"tui%2Efooter":{label:{"v1-1nnfi3c-i":`Piè di pagina dell'interfaccia del terminale`},help:{"v1-6e12l3-3k":`Impostazioni di visualizzazione del piè di pagina dell'interfaccia del terminale. Mantieni compatte le informazioni di contesto facoltative affinché i dati su sessione, modello, obiettivo e token restino leggibili.`}},ui:{label:{"v1-ye4dff-2":`UI`},help:{"v1-dt1924-42":`Impostazioni di presentazione dell'interfaccia per i colori di accento e le preferenze di visualizzazione dell'operatore. Usale per personalizzare la leggibilità senza modificare il comportamento in fase di esecuzione.`}},"ui%2Eprefs%2Eaccent":{label:{"v1-1e4sxpj-h":`Colore di accento dell'utente`},help:{"v1-16klzws-4z":`Colore di risalto di Control UI: #RRGGBB per un colore personalizzato, oppure 'theme' per la tavolozza del tema selezionato. Sovrascrive ui.seamColor; cancella il valore per ereditare il colore di giunzione configurato o quello predefinito del tema.`}},"ui%2EseamColor":{label:{"v1-1ddt13c-c":`Colore di accento`},help:{"v1-14q3r4h-4g":`Colore di accento principale usato nelle superfici dell'interfaccia per evidenziazioni, badge ed elementi di identità visiva. Usa valori ad alto contrasto che rimangano leggibili nei temi chiari e scuri.`}},update:{label:{"v1-k12u1x-7":`Aggiornamenti`},help:{"v1-11c5k8v-5c":`Comportamento del canale di aggiornamento e del controllo all'avvio per mantenere aggiornate le versioni del runtime di OpenClaw. Usa canali conservativi in produzione e canali più sperimentali solo in ambienti controllati.`}},"update%2Eauto%2Eenabled":{label:{"v1-1ahdhbe-j":`Aggiornamento automatico abilitato`},help:{"v1-49xs2h-3c":`Abilita l'aggiornamento automatico in background per le installazioni da pacchetto stable e beta; gli aggiornamenti extended-stable non vengono mai applicati automaticamente (valore predefinito: false).`}},"update%2Echannel":{label:{"v1-zk8ncv-e":`Canale di aggiornamento`},help:{"v1-lqtdvf-5b":`Canale di aggiornamento per le installazioni git + npm ("stable", "extended-stable", "beta" o "dev"). Il canale extended-stable è disponibile solo per le installazioni da pacchetto: l'installazione avviene solo in primo piano, con avvisi facoltativi di sola lettura all'avvio.`}},"update%2EcheckOnStart":{label:{"v1-10js111-l":`Controllo aggiornamenti all'avvio`},help:{"v1-qy3q9g-5v":`Verifica la disponibilità di aggiornamenti all'avvio del Gateway, incluse le indicazioni di sola lettura per extended-stable (valore predefinito: true). Imposta false per disabilitare la verifica e l'applicazione automatiche degli aggiornamenti del Gateway e dei nodi senza interfaccia grafica, nonché le richieste anonime di verifica degli aggiornamenti.`}},voicewake:{label:{"v1-txt1wb-a":`Attivazione vocale`}},web:{label:{"v1-1ae9z56-b":`Canale web`}},wizard:{label:{"v1-28jonk-h":`Preferenze di configurazione`},help:{"v1-14jh6rm-3b":`Preferenze di configurazione gestite dall'utente. La cronologia della configurazione guidata e lo stato delle conferme gestiti dal sistema risiedono nel database di stato condiviso.`}},"wizard%2EaccessMode":{label:{"v1-1ayx2hy-m":`Accesso al rilevamento in fase di configurazione`},help:{"v1-1nqxt0w-38":`Consenso al rilevamento per la configurazione guidata: "full" esegue la scansione senza chiedere conferma, mentre "guarded" chiede il consenso prima di esaminare le applicazioni locali.`}},"wizard%2EappRecommendations":{label:{"v1-jc89qd-p":`Suggerimenti sulle app durante la configurazione`},help:{"v1-ub8uoi-30":`Controlla se la configurazione guidata può utilizzare le etichette delle applicazioni installate per suggerire plugin e Skills pertinenti.`}},"wizard%2ElastRunAt":{label:{"v1-1puf3az-p":`Data e ora dell'ultima esecuzione della procedura guidata`},help:{"v1-1y0fbk-1k":`Data e ora dell'ultima esecuzione della procedura guidata salvata correttamente.`}},"wizard%2ElastRunCommand":{label:{"v1-3f99ei-n":`Comando dell'ultima esecuzione della procedura guidata`},help:{"v1-x2pfkk-15":`Comando che ha avviato l'ultima esecuzione della procedura guidata.`}},"wizard%2ElastRunCommit":{label:{"v1-1a2uglw-m":`Commit dell'ultima esecuzione della procedura guidata`},help:{"v1-h0jkmt-1i":`Commit del codice sorgente utilizzato dall'ultima esecuzione della procedura guidata in ambiente di sviluppo.`}},"wizard%2ElastRunMode":{label:{"v1-p2iydm-k":`Modalità dell'ultima esecuzione della procedura guidata`},help:{"v1-16508qy-1r":`Indica se l'ultima esecuzione della procedura guidata era destinata alla configurazione "local" o "remote".`}},"wizard%2ElastRunVersion":{label:{"v1-1kvlwlr-n":`Versione dell'ultima esecuzione della procedura guidata`},help:{"v1-1tr4z9d-19":`Versione di OpenClaw utilizzata dall'ultima esecuzione della procedura guidata.`}},"wizard%2EsecurityAcknowledgedAt":{label:{"v1-17xanyw-15":`Data e ora della presa visione delle avvertenze di sicurezza nella procedura guidata`},help:{"v1-86i182-2a":`Data e ora della presa visione delle avvertenze di sicurezza durante la configurazione, salvate insieme alla configurazione di destinazione.`}},worktreeAcceleration:{label:{"v1-128z6h8-l":`Accelerazione dei worktree`},help:{"v1-9es3gc-4r":`Usa l'accelerazione del filesystem per i nuovi worktree gestiti, se supportata (valore predefinito: true). Imposta false per usare il normale checkout Git e la copia dei file. Si applica solo ai nuovi worktree.`}},worktreeRoot:{label:{"v1-bqutg0-d":`Directory radice dei worktree`},help:{"v1-1tgti9j-5d":`Directory globale per i nuovi worktree gestiti. Usa un percorso assoluto oppure ~ per la tua directory home; il valore predefinito è <state-dir>/worktrees. I worktree esistenti mantengono i percorsi registrati quando questo valore cambia.`}}}}})))()}export{t as n,n as t};